SOURCES = {'scripts/build_training_cache.py': '#!/usr/bin/env python3\n"""Kaggle CPU staging job for an exactly equivalent, faster training read format."""\nfrom concurrent.futures import ThreadPoolExecutor\nimport hashlib\nimport json\nfrom pathlib import Path\nimport time\nimport pandas as pd\nfrom qmmf.slab_cache import build_training_slabs\n\n\ndef run(input_dir="/kaggle/input", output_dir="/kaggle/working/training_slabs"):\n    start = time.monotonic()\n    hits = list(Path(input_dir).rglob("preparation_complete.json"))\n    if len(hits) != 1:\n        raise ValueError("Attach exactly one verified original cache source")\n    prepared = hits[0].parent\n    report = json.loads((prepared / "dataset_fingerprint.json").read_text())\n    manifest = pd.read_csv(prepared / "manifest.csv", dtype=str)\n    ids = sorted(manifest.case_id.tolist())\n    if len(ids) != 484 or len(set(ids)) != len(ids):\n        raise ValueError("Unexpected input case universe")\n    out = Path(output_dir); (out / "cache").mkdir(parents=True, exist_ok=True)\n    def convert(cid):\n        return build_training_slabs(prepared / "cache_v2" / f"{cid}.npz",\n                                    out / "cache" / f"{cid}.npz", slab_depth=8)\n    rows = []\n    with ThreadPoolExecutor(max_workers=2) as pool:\n        for i, result in enumerate(pool.map(convert, ids), 1):\n            rows.append(result)\n            if i % 25 == 0:\n                print(f"Verified lossless slabs {i}/{len(ids)}", flush=True)\n    table = out / "case_inventory.csv"\n    pd.DataFrame(rows).to_csv(table, index=False)\n    complete = {"completed": True, "n_cases": len(rows), "manifest_hash": report["manifest_hash"],\n        "source_cache_version": 2, "training_slab_format_version": 1, "slab_depth": 8,\n        "voxel_equality_verified_for_all_cases": all(r["voxel_equality_verified"] for r in rows),\n        "case_inventory_sha256": hashlib.sha256(table.read_bytes()).hexdigest(),\n        "wall_seconds": time.monotonic() - start, "slab_bytes": sum(r["slab_bytes"] for r in rows),\n        "source_bytes": sum(r["source_bytes"] for r in rows),\n        "purpose": "lossless selective decompression; no training, tuning or model evaluation"}\n    (out / "training_slabs_complete.json").write_text(json.dumps(complete, indent=2))\n    print(json.dumps(complete, indent=2), flush=True)\n\n\nif __name__ == "__main__":\n    run()\n', 'segmentation/src/qmmf/__init__.py': '"""QMMF-Net: Quality-Conditioned Masked Moment Fusion for calibrated brain\ntumour segmentation with arbitrary missing MRI modalities.\n\nReference implementation of the master research plan (protocol qmmf-v1.0).\n\nNothing in this package claims an experimental result. Every performance\nnumber the plan mentions is a planning target or a decision gate; the code\nproduces measurements, and the notebooks record them.\n"""\n\nfrom .config import (\n    DataConfig, EvalConfig, ExperimentConfig, LossConfig, MODALITIES,\n    ModelConfig, OUTPUTS, PROTOCOL_VERSION, TrainingConfig,\n)\n\n__version__ = "1.0.0"\n__protocol__ = PROTOCOL_VERSION\n\n__all__ = [\n    "ExperimentConfig", "DataConfig", "ModelConfig", "LossConfig",\n    "TrainingConfig", "EvalConfig", "MODALITIES", "OUTPUTS",\n    "PROTOCOL_VERSION", "__version__",\n]\n', 'segmentation/src/qmmf/calibration.py': '"""Calibration, uncertainty, failure detection and selective segmentation.\n\nPlan 10.2. Every fitting step here uses development data only: the temperature\nand any region scaling are cross-fitted on the development pool, and the adult\nlocked test and the pediatric cohort are never used to choose a parameter.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom typing import Dict, List, Optional, Sequence, Tuple\n\nimport numpy as np\n\n\n# --------------------------------------------------------------------------- #\n# Calibration error\n# --------------------------------------------------------------------------- #\ndef _bin_stats(probs, labels, n_bins, adaptive):\n    p = np.asarray(probs, dtype=np.float64).ravel()\n    y = np.asarray(labels, dtype=np.float64).ravel()\n    if p.size == 0:\n        return np.array([]), np.array([]), np.array([])\n    if adaptive:\n        edges = np.quantile(p, np.linspace(0, 1, n_bins + 1))\n        edges[0], edges[-1] = 0.0, 1.0\n        edges = np.unique(edges)\n    else:\n        edges = np.linspace(0.0, 1.0, n_bins + 1)\n    idx = np.clip(np.digitize(p, edges[1:-1], right=False), 0, len(edges) - 2)\n    counts = np.bincount(idx, minlength=len(edges) - 1).astype(np.float64)\n    conf = np.bincount(idx, weights=p, minlength=len(edges) - 1)\n    acc = np.bincount(idx, weights=y, minlength=len(edges) - 1)\n    nz = counts > 0\n    return conf[nz] / counts[nz], acc[nz] / counts[nz], counts[nz]\n\n\ndef expected_calibration_error(probs, labels, n_bins: int = 20) -> float:\n    """ECE: count-weighted mean gap over equal-width bins."""\n    conf, acc, counts = _bin_stats(probs, labels, n_bins, adaptive=False)\n    if conf.size == 0:\n        return float("nan")\n    return float(np.sum(counts * np.abs(conf - acc)) / counts.sum())\n\n\ndef average_calibration_error(probs, labels, n_bins: int = 20) -> float:\n    """mL1-ACE: unweighted mean gap over non-empty *equal-mass* bins.\n\n    Reported alongside ECE because equal-width bins are dominated by the huge\n    background mass in segmentation (Barfoot et al., MICCAI 2024).\n    """\n    conf, acc, _ = _bin_stats(probs, labels, n_bins, adaptive=True)\n    if conf.size == 0:\n        return float("nan")\n    return float(np.mean(np.abs(conf - acc)))\n\n\ndef maximum_calibration_error(probs, labels, n_bins: int = 20) -> float:\n    conf, acc, _ = _bin_stats(probs, labels, n_bins, adaptive=False)\n    return float(np.max(np.abs(conf - acc))) if conf.size else float("nan")\n\n\ndef brier_score(probs, labels) -> float:\n    p = np.asarray(probs, dtype=np.float64).ravel()\n    y = np.asarray(labels, dtype=np.float64).ravel()\n    return float(np.mean((p - y) ** 2)) if p.size else float("nan")\n\n\ndef negative_log_likelihood(probs, labels, eps: float = 1e-7) -> float:\n    p = np.clip(np.asarray(probs, dtype=np.float64).ravel(), eps, 1 - eps)\n    y = np.asarray(labels, dtype=np.float64).ravel()\n    return float(-np.mean(y * np.log(p) + (1 - y) * np.log(1 - p))) if p.size else float("nan")\n\n\ndef reliability_diagram_data(probs, labels, n_bins: int = 20) -> Dict[str, np.ndarray]:\n    conf, acc, counts = _bin_stats(probs, labels, n_bins, adaptive=False)\n    return {"confidence": conf, "accuracy": acc, "count": counts}\n\n\ndef calibration_report(probs, labels, n_bins: int = 20) -> Dict[str, float]:\n    return {\n        "ece": expected_calibration_error(probs, labels, n_bins),\n        "ml1_ace": average_calibration_error(probs, labels, n_bins),\n        "mce": maximum_calibration_error(probs, labels, n_bins),\n        "brier": brier_score(probs, labels),\n        "nll": negative_log_likelihood(probs, labels),\n    }\n\n\n# --------------------------------------------------------------------------- #\n# Temperature scaling, fitted on development data only\n# --------------------------------------------------------------------------- #\n@dataclass\nclass TemperatureScaler:\n    """One temperature per region, fitted by minimising NLL on logits.\n\n    `fit` runs a bounded scalar search rather than gradient descent, so it is\n    deterministic and needs no torch.\n    """\n\n    temperatures: np.ndarray                 # [R]\n    regions: Tuple[str, ...] = ("wt", "tc", "et")\n\n    @classmethod\n    def fit(cls, logits: np.ndarray, labels: np.ndarray,\n            regions: Sequence[str] = ("wt", "tc", "et"),\n            grid: Optional[np.ndarray] = None) -> "TemperatureScaler":\n        """logits/labels: [R, N] arrays of development-set voxel samples."""\n        logits = np.atleast_2d(np.asarray(logits, dtype=np.float64))\n        labels = np.atleast_2d(np.asarray(labels, dtype=np.float64))\n        grid = np.geomspace(0.25, 4.0, 61) if grid is None else np.asarray(grid)\n        temps = np.ones(logits.shape[0])\n        for r in range(logits.shape[0]):\n            best, best_nll = 1.0, np.inf\n            for t in grid:\n                p = 1.0 / (1.0 + np.exp(-logits[r] / t))\n                nll = negative_log_likelihood(p, labels[r])\n                if nll < best_nll:\n                    best, best_nll = float(t), nll\n            temps[r] = best\n        return cls(temperatures=temps, regions=tuple(regions))\n\n    def transform_logits(self, logits: np.ndarray) -> np.ndarray:\n        t = self.temperatures.reshape((-1,) + (1,) * (np.ndim(logits) - 1))\n        return np.asarray(logits, dtype=np.float64) / t\n\n    def transform_probs(self, logits: np.ndarray) -> np.ndarray:\n        return 1.0 / (1.0 + np.exp(-self.transform_logits(logits)))\n\n    def to_dict(self) -> Dict:\n        return {"temperatures": self.temperatures.tolist(), "regions": list(self.regions)}\n\n    @classmethod\n    def from_dict(cls, d: Dict) -> "TemperatureScaler":\n        return cls(np.array(d["temperatures"], dtype=np.float64), tuple(d["regions"]))\n\n\n# --------------------------------------------------------------------------- #\n# Uncertainty\n# --------------------------------------------------------------------------- #\ndef predictive_entropy(probs: np.ndarray, eps: float = 1e-7) -> np.ndarray:\n    """Binary entropy per voxel per region."""\n    p = np.clip(np.asarray(probs, dtype=np.float64), eps, 1 - eps)\n    return -(p * np.log(p) + (1 - p) * np.log(1 - p))\n\n\ndef ensemble_statistics(member_probs: Sequence[np.ndarray]) -> Dict[str, np.ndarray]:\n    """Three-seed deep ensemble: mean, inter-model variance, mean entropy.\n\n    The plan\'s uncertainty source is the ensemble; entropy of a single model is\n    reported as a comparison, not as the primary signal.\n    """\n    stack = np.stack([np.asarray(p, dtype=np.float64) for p in member_probs], axis=0)\n    mean = stack.mean(axis=0)\n    return {\n        "mean": mean,\n        "variance": stack.var(axis=0),\n        "entropy_of_mean": predictive_entropy(mean),\n        "mean_entropy": predictive_entropy(stack).mean(axis=0),\n        "mutual_information": predictive_entropy(mean) - predictive_entropy(stack).mean(axis=0),\n    }\n\n\ndef case_uncertainty_summary(\n    probs: np.ndarray, brain_mask: Optional[np.ndarray] = None,\n    variance: Optional[np.ndarray] = None,\n) -> Dict[str, float]:\n    """Scalar per-patient uncertainty features used for failure prediction."""\n    ent = predictive_entropy(probs)\n    if brain_mask is not None:\n        m = np.asarray(brain_mask, dtype=bool)\n        ent_vals = ent[..., m] if ent.ndim == 4 else ent[m]\n    else:\n        ent_vals = ent\n    out = {\n        "mean_entropy": float(np.mean(ent_vals)),\n        "p95_entropy": float(np.percentile(ent_vals, 95)),\n        "candidate_entropy": float(\n            np.mean(ent[(probs > 0.1) & (probs < 0.9)]) if np.any((probs > 0.1) & (probs < 0.9)) else 0.0\n        ),\n    }\n    if variance is not None:\n        out["mean_ensemble_variance"] = float(np.mean(variance))\n    return out\n\n\n# --------------------------------------------------------------------------- #\n# Failure detection and selective segmentation\n# --------------------------------------------------------------------------- #\ndef failure_labels(dice_values: Sequence[float], threshold: float) -> np.ndarray:\n    """A case is a \'failure\' when its macro Dice falls below a threshold fixed\n    on development data (plan 10.2 \'Failure definition\')."""\n    return (np.asarray(dice_values, dtype=np.float64) < threshold).astype(int)\n\n\ndef failure_detection_scores(\n    uncertainty: Sequence[float], failures: Sequence[int]\n) -> Dict[str, float]:\n    """AUROC/AUPRC of ranking cases by uncertainty to predict failure."""\n    from sklearn.metrics import average_precision_score, roc_auc_score\n    u = np.asarray(uncertainty, dtype=np.float64)\n    f = np.asarray(failures, dtype=int)\n    if f.sum() == 0 or f.sum() == len(f):\n        return {"auroc": float("nan"), "auprc": float("nan"),\n                "n_failures": int(f.sum()), "n_cases": int(len(f))}\n    return {\n        "auroc": float(roc_auc_score(f, u)),\n        "auprc": float(average_precision_score(f, u)),\n        "n_failures": int(f.sum()),\n        "n_cases": int(len(f)),\n    }\n\n\ndef risk_coverage_curve(\n    scores: Sequence[float], uncertainty: Sequence[float],\n    risk: str = "one_minus_dice",\n) -> Dict[str, np.ndarray]:\n    """Risk as a function of retained coverage, ordering by ascending uncertainty.\n\n    Selective segmentation abstains on the most uncertain cases; a useful\n    uncertainty signal makes risk decrease monotonically as coverage falls.\n    """\n    s = np.asarray(scores, dtype=np.float64)\n    u = np.asarray(uncertainty, dtype=np.float64)\n    order = np.argsort(u, kind="stable")\n    s_sorted = s[order]\n    losses = 1.0 - s_sorted if risk == "one_minus_dice" else s_sorted\n    n = len(s_sorted)\n    coverage = np.arange(1, n + 1) / n\n    risks = np.cumsum(losses) / np.arange(1, n + 1)\n    return {"coverage": coverage, "risk": risks, "sorted_score": s_sorted}\n\n\ndef area_under_risk_coverage(curve: Dict[str, np.ndarray]) -> float:\n    return float(np.trapezoid(curve["risk"], curve["coverage"])) \\\n        if hasattr(np, "trapezoid") else float(np.trapz(curve["risk"], curve["coverage"]))\n\n\ndef selective_performance(\n    scores: Sequence[float], uncertainty: Sequence[float],\n    coverages: Sequence[float] = (1.0, 0.9, 0.8),\n) -> Dict[str, float]:\n    """Mean score among the retained cases at each coverage level."""\n    s = np.asarray(scores, dtype=np.float64)\n    u = np.asarray(uncertainty, dtype=np.float64)\n    order = np.argsort(u, kind="stable")\n    out: Dict[str, float] = {}\n    for c in coverages:\n        k = max(int(round(c * len(s))), 1)\n        out[f"score_at_coverage_{int(round(c * 100))}"] = float(s[order][:k].mean())\n    return out\n', 'segmentation/src/qmmf/config.py': '"""Typed experiment configuration for QMMF-Net.\n\nMirrors Appendix A of the master research plan. Every field that changes a\nresult must live here so that `config_hash` identifies a run uniquely.\n\nNothing in this module reads data or touches the GPU.\n"""\n\nfrom __future__ import annotations\n\nimport dataclasses\nimport hashlib\nimport json\nfrom dataclasses import dataclass, field, asdict\nfrom pathlib import Path\nfrom typing import Any, Dict, List, Optional, Tuple\n\nPROTOCOL_VERSION = "qmmf-v2.0-corrected"\n\n# Canonical modality order. Never assume this from filenames: Notebook 01\n# verifies it against dataset.json and intensity checks (plan 5.5).\nMODALITIES: Tuple[str, ...] = ("t1", "t1ce", "t2", "flair")\nOUTPUTS: Tuple[str, ...] = ("wt", "tc", "et")\n\n\n# --------------------------------------------------------------------------- #\n# Sub-configs\n# --------------------------------------------------------------------------- #\n@dataclass\nclass DataConfig:\n    crop_size: Tuple[int, int] = (192, 192)\n    context_slices: int = 5           # D in the plan; ablation A14 uses 1/3/5/7\n    modalities: Tuple[str, ...] = MODALITIES\n    outputs: Tuple[str, ...] = OUTPUTS\n    normalization: str = "robust_zscore_nonzero_brain"\n    clip_sigma: float = 5.0\n    # Sampling policy, plan 6.3\n    p_tumor_window: float = 0.50\n    p_boundary_window: float = 0.25\n    p_random_window: float = 0.25\n    # Augmentation, plan 6.4\n    aug_flip_lr: bool = True\n    aug_rotation_deg: float = 10.0\n    aug_scale: float = 0.1\n    aug_elastic: bool = False         # only after a pilot confirms label fidelity\n    aug_intensity: bool = True\n    # Label efficiency, plan 6.5\n    label_fraction: float = 1.0       # 0.25 / 0.50 / 1.0, nested subsets\n    # Integrity, filled by Notebook 01\n    manifest_hash: str = ""\n    split_hash: str = ""\n    root: str = ""\n\n\n@dataclass\nclass ModelConfig:\n    name: str = "qmmf_net"\n    widths: Tuple[int, ...] = (24, 48, 96, 160)\n    moment_fusion: Tuple[str, ...] = ("mean", "variance", "max")\n    quality_dim: int = 7\n    modality_embed_dim: int = 16\n    context_block: str = "factorized_large_kernel"   # or "none" (A8), "kernel3" (A9)\n    context_depth: int = 2\n    context_kernel: int = 7\n    deep_supervision: bool = True\n    gate_hidden: int = 32\n    use_quality: bool = True          # A5 sets False\n    use_availability_gate: bool = True  # A4 keeps this, drops quality\n    dropout: float = 0.0\n    use_film: bool = True             # A15 sets False\n\n\n@dataclass\nclass LossConfig:\n    dice: float = 0.60\n    bce: float = 0.40\n    seg: float = 1.00\n    boundary: float = 0.10\n    nested: float = 0.05\n    consistency: float = 0.20\n    calibration: float = 0.00         # optional locked ablation, not assumed useful\n    deep_supervision_weights: Tuple[float, ...] = (0.5, 0.25)\n    consistency_warmup_frac: float = 0.15\n    consistency_conf_threshold: float = 0.90\n\n\n@dataclass\nclass TrainingConfig:\n    optimizer: str = "adamw"\n    lr: float = 3e-4                  # pilot range 2e-4..5e-4\n    weight_decay: float = 1e-3        # pilot range 1e-4..1e-2\n    amp: bool = True\n    batch_size: int = 4               # per-GPU; effective batch via accumulation\n    accumulation_steps: int = 4       # effective ~16-32 central slices\n    max_epochs: int = 120\n    warmup_frac: float = 0.05\n    grad_clip: float = 1.0\n    early_stopping_patience: int = 20\n    ema_decay_start: float = 0.99\n    ema_decay_end: float = 0.999\n    modality_curriculum: str = "v1"   # A11 sets "uniform"\n    num_workers: int = 2\n    persistent_workers: bool = False\n    seed: int = 42\n    steps_per_epoch: int = 250\n    val_every: int = 1\n    grad_checkpointing: bool = False\n\n\n@dataclass\nclass EvalConfig:\n    nsd_tolerance_mm: float = 1.0\n    empty_reference_rule: str = "exclude_from_dice_report_separately"\n    bootstrap_replicates: int = 10_000\n    alpha: float = 0.05\n    non_inferiority_margin_pp: float = 1.5   # H1, locked before any test result\n    calibration_bins: int = 20\n    selective_coverages: Tuple[float, ...] = (1.0, 0.9, 0.8)\n    mc_seeds: Tuple[int, ...] = (42, 43, 44)  # three-seed deep ensemble\n\n\n@dataclass\nclass ExperimentConfig:\n    protocol_version: str = PROTOCOL_VERSION\n    seed: int = 42\n    fold: int = 0\n    label_fraction: float = 1.0\n    model: str = "qmmf_net"\n    ablation: str = "A0"\n    stage: str = "development"        # development | locked_adult | ood_pediatric\n    data: DataConfig = field(default_factory=DataConfig)\n    net: ModelConfig = field(default_factory=ModelConfig)\n    loss: LossConfig = field(default_factory=LossConfig)\n    train: TrainingConfig = field(default_factory=TrainingConfig)\n    evaluation: EvalConfig = field(default_factory=EvalConfig)\n    out_dir: str = "/kaggle/working/qmmf_runs"\n    notes: str = ""\n\n    # ----------------------------------------------------------------- #\n    def to_dict(self) -> Dict[str, Any]:\n        return _tuples_to_lists(asdict(self))\n\n    def config_hash(self) -> str:\n        """Stable hash of the fully resolved configuration (Appendix C)."""\n        payload = json.dumps(self.to_dict(), sort_keys=True, separators=(",", ":"))\n        return hashlib.sha256(payload.encode("utf-8")).hexdigest()[:16]\n\n    def run_id(self) -> str:\n        return (\n            f"{self.model}_{self.ablation}_f{self.fold}_s{self.seed}"\n            f"_lf{int(self.label_fraction * 100)}_{self.config_hash()[:8]}"\n        )\n\n    def run_dir(self) -> Path:\n        return Path(self.out_dir) / self.run_id()\n\n    def save(self, path: str | Path) -> None:\n        path = Path(path)\n        path.parent.mkdir(parents=True, exist_ok=True)\n        path.write_text(json.dumps(self.to_dict(), indent=2, sort_keys=True))\n\n    # ----------------------------------------------------------------- #\n    @classmethod\n    def from_dict(cls, d: Dict[str, Any]) -> "ExperimentConfig":\n        d = dict(d)\n        sub = {\n            "data": DataConfig,\n            "net": ModelConfig,\n            "loss": LossConfig,\n            "train": TrainingConfig,\n            "evaluation": EvalConfig,\n        }\n        kwargs: Dict[str, Any] = {}\n        for key, klass in sub.items():\n            kwargs[key] = _build(klass, d.pop(key, {}) or {})\n        known = {f.name for f in dataclasses.fields(cls)}\n        unknown = set(d) - known\n        if unknown:\n            raise ValueError(f"Unknown configuration keys: {sorted(unknown)}")\n        kwargs.update(d)\n        return cls(**kwargs)\n\n    @classmethod\n    def load(cls, path: str | Path) -> "ExperimentConfig":\n        text = Path(path).read_text()\n        if str(path).endswith((".yaml", ".yml")):\n            import yaml  # local import keeps the dependency optional\n            raw = yaml.safe_load(text)\n        else:\n            raw = json.loads(text)\n        raw = raw.get("experiment", raw) if isinstance(raw, dict) else raw\n        return cls.from_dict(raw)\n\n    def merged(self, overrides: Dict[str, Any]) -> "ExperimentConfig":\n        """Return a copy with dotted-key overrides applied, e.g. {\'net.widths\': [...]}"""\n        base = self.to_dict()\n        for dotted, value in overrides.items():\n            node = base\n            parts = dotted.split(".")\n            for p in parts[:-1]:\n                if p not in node:\n                    raise KeyError(f"Unknown config section \'{p}\' in \'{dotted}\'")\n                node = node[p]\n            if parts[-1] not in node:\n                raise KeyError(f"Unknown config key \'{dotted}\'")\n            node[parts[-1]] = value\n        return ExperimentConfig.from_dict(base)\n\n\n# --------------------------------------------------------------------------- #\ndef _build(klass, d: Dict[str, Any]):\n    fields = {f.name: f for f in dataclasses.fields(klass)}\n    unknown = set(d) - set(fields)\n    if unknown:\n        raise ValueError(f"Unknown keys for {klass.__name__}: {sorted(unknown)}")\n    kwargs = {}\n    for name, value in d.items():\n        anno = str(fields[name].type)\n        if "Tuple" in anno and isinstance(value, list):\n            value = tuple(value)\n        kwargs[name] = value\n    return klass(**kwargs)\n\n\ndef _tuples_to_lists(obj):\n    if isinstance(obj, dict):\n        return {k: _tuples_to_lists(v) for k, v in obj.items()}\n    if isinstance(obj, (list, tuple)):\n        return [_tuples_to_lists(v) for v in obj]\n    return obj\n\n\n__all__ = [\n    "ExperimentConfig", "DataConfig", "ModelConfig", "LossConfig",\n    "TrainingConfig", "EvalConfig", "MODALITIES", "OUTPUTS", "PROTOCOL_VERSION",\n]\n', 'segmentation/src/qmmf/dataset.py': '"""Case cache and 2.5D torch Datasets.\n\nTwo datasets:\n  * `SliceDataset`      - random 2.5D windows for training, with the modality\n                          curriculum and augmentation;\n  * `VolumeSliceDataset` - every slice of one volume in order, for deterministic\n                          validation / inference and 3D reconstruction.\n\nPreprocessed cases are cached to compressed .npz once (plan 11.3: "small\npersistent cache of preprocessed metadata, not duplicate copies of all volumes\nin RAM"). A cache entry stores the cropped, normalised volume in float16 to\nkeep the Kaggle working directory small.\n"""\n\nfrom __future__ import annotations\n\nimport json\nfrom collections import OrderedDict\nfrom pathlib import Path\nfrom typing import Dict, List, Optional, Sequence, Tuple\n\nimport numpy as np\n\ntry:\n    import torch\n    from torch.utils.data import Dataset\nexcept ImportError:  # audit-only environments\n    torch = None\n\n    class Dataset:  # type: ignore\n        pass\n\nfrom .config import MODALITIES, DataConfig\nfrom .labels import LabelScheme, to_nested_targets\nfrom .quality import QualityNormalizer, compute_quality_matrix\nfrom .subsets import availability_mask, sample_subset\nfrom .transforms import (\n    AugmentConfig, augment_window, center_pad_or_crop, extract_window,\n    preprocess_case, sample_slice_index,\n)\n\n\ndef canonical_modality_order(metadata: Dict) -> Tuple[int, ...]:\n    """Resolve source indices explicitly; MSD stores FLAIR, T1w, t1gd, T2w."""\n    aliases = {"t1": "t1", "t1w": "t1", "t1ce": "t1ce", "t1gd": "t1ce",\n               "t1c": "t1ce", "t2": "t2", "t2w": "t2", "flair": "flair"}\n    block = metadata.get("modality", metadata.get("channel_names", {}))\n    source = {}\n    for index, value in block.items():\n        name = str(value).lower().replace("-", "").replace("_", "").replace(" ", "")\n        if name not in aliases or aliases[name] in source:\n            raise ValueError(f"Unknown or repeated modality in metadata: {block}")\n        source[aliases[name]] = int(index)\n    if set(source) != set(MODALITIES):\n        raise ValueError(f"Expected {MODALITIES}, found {block}")\n    return tuple(source[m] for m in MODALITIES)\n\n\n# --------------------------------------------------------------------------- #\n# Case cache\n# --------------------------------------------------------------------------- #\nclass CaseCache:\n    """Builds and reads the preprocessed per-case cache."""\n\n    def __init__(self, cache_dir: str | Path, scheme: LabelScheme,\n                 clip_sigma: float = 5.0, crop_margin: int = 8,\n                 max_memory_cases: int = 2, training_slabs: Optional[str | Path] = None):\n        self.cache_dir = Path(cache_dir)\n        self.cache_dir.mkdir(parents=True, exist_ok=True)\n        self.scheme = scheme\n        self.clip_sigma = clip_sigma\n        self.crop_margin = crop_margin\n        self.max_memory_cases = max_memory_cases\n        self._memory = OrderedDict()\n        from .slab_cache import TrainingSlabReader\n        self.training_slabs = TrainingSlabReader(training_slabs) if training_slabs is not None else None\n\n    def path(self, case_id: str) -> Path:\n        return self.cache_dir / f"{case_id}.npz"\n\n    def build(self, case_id: str, image_path: str, label_path: Optional[str],\n              overwrite: bool = False) -> Path:\n        out = self.path(case_id)\n        if out.exists() and not overwrite:\n            with np.load(out, allow_pickle=False) as existing:\n                if "cache_version" in existing and int(existing["cache_version"]) == 2:\n                    return out\n        import nibabel as nib\n\n        img = np.asanyarray(nib.load(image_path).dataobj).astype(np.float32)\n        if img.ndim != 4:\n            raise ValueError(f"{case_id}: expected 4D image, got shape {img.shape}")\n        img = np.moveaxis(img, -1, 0)                       # [M, H, W, D]\n        metadata_path = next((p / "dataset.json" for p in Path(image_path).parents\n                              if (p / "dataset.json").exists()), None)\n        if metadata_path is None:\n            raise ValueError("dataset.json is required to verify modality order")\n        order = canonical_modality_order(json.loads(metadata_path.read_text()))\n        img = img[list(order)]\n        lbl = (np.asanyarray(nib.load(label_path).dataobj).astype(np.int16)\n               if label_path else None)\n\n        prep = preprocess_case(img, lbl, self.clip_sigma, self.crop_margin)\n        payload: Dict[str, np.ndarray] = {\n            "cache_version": np.array(2, dtype=np.int32),\n            "source_channel_order": np.array(order, dtype=np.int32),\n            "image": prep["image"].astype(np.float16),\n            "brain_mask": prep["brain_mask"].astype(np.bool_),\n            "crop_box": np.array(prep["crop_box"], dtype=np.int32),\n            "original_shape": np.array(prep["original_shape"], dtype=np.int32),\n        }\n        # Quality features are computed on the *preprocessed* volume, matching\n        # what the network sees, and are stored raw (normalised at load time\n        # with training-fold statistics only).\n        payload["quality_raw"] = compute_quality_matrix(\n            [prep["image"][m] for m in range(prep["image"].shape[0])],\n            prep["brain_mask"],\n        ).astype(np.float32)\n\n        if lbl is not None:\n            if np.count_nonzero(prep["label"]) != np.count_nonzero(lbl):\n                raise ValueError(f"{case_id}: brain crop would discard annotated voxels")\n            targets = to_nested_targets(prep["label"], self.scheme)\n            payload["target"] = targets.astype(np.uint8)\n        tmp = out.with_suffix(".tmp.npz")\n        np.savez_compressed(tmp, **payload)\n        tmp.replace(out)\n        self._memory.pop(case_id, None)\n        return out\n\n    def load(self, case_id: str) -> Dict[str, np.ndarray]:\n        if case_id in self._memory:\n            self._memory.move_to_end(case_id)\n            return self._memory[case_id]\n        with np.load(self.path(case_id), allow_pickle=False) as z:\n            result = {k: z[k] for k in z.files}\n        if int(result.get("cache_version", 0)) != 2:\n            raise ValueError("Legacy cache has unverified channel order; rebuild it")\n        if self.max_memory_cases:\n            self._memory[case_id] = result\n            while len(self._memory) > self.max_memory_cases:\n                self._memory.popitem(last=False)\n        return result\n\n    def quality_raw(self, case_id: str) -> np.ndarray:\n        # Reading this one member avoids decompressing an entire volume.\n        with np.load(self.path(case_id), allow_pickle=False) as z:\n            return z["quality_raw"]\n\n    def sample_training_window(self, case_id, cfg, rng):\n        if self.training_slabs is not None:\n            return self.training_slabs.sample(case_id, cfg, rng)\n        rec = self.load(case_id)\n        z = sample_slice_index(rec["target"][0], rec["brain_mask"], rng,\n                              p_tumor=cfg.p_tumor_window, p_boundary=cfg.p_boundary_window)\n        return (extract_window(rec["image"], z, cfg.context_slices).astype(np.float32),\n                rec["target"][..., z].astype(np.float32), z, rec["quality_raw"])\n\n\n# --------------------------------------------------------------------------- #\ndef _to_tensor(x: np.ndarray, dtype=None):\n    t = torch.from_numpy(np.ascontiguousarray(x))\n    return t.to(dtype) if dtype is not None else t\n\n\nclass SliceDataset(Dataset):\n    """Random 2.5D training windows with curriculum modality dropout."""\n\n    def __init__(\n        self,\n        case_ids: Sequence[str],\n        cache: CaseCache,\n        data_cfg: DataConfig,\n        quality_norm: Optional[QualityNormalizer] = None,\n        curriculum: str = "v1",\n        augment: bool = True,\n        length: Optional[int] = None,\n        seed: int = 42,\n        shuffle_quality: bool = False,     # ablation A17 negative control\n        zero_quality: bool = False,        # ablation A5\n        case_to_group: Optional[Dict[str, str]] = None,\n    ):\n        self.case_ids = list(case_ids)\n        if not self.case_ids:\n            raise ValueError("SliceDataset received an empty case list.")\n        if len(set(self.case_ids)) != len(self.case_ids):\n            raise ValueError("Training case IDs must be unique")\n        mapping = case_to_group if case_to_group is not None else {c: c for c in self.case_ids}\n        if not set(self.case_ids) <= set(mapping):\n            raise ValueError("Every training case needs a similarity group")\n        self.group_members = {}\n        for cid in sorted(self.case_ids):\n            self.group_members.setdefault(mapping[cid], []).append(cid)\n        self.group_ids = sorted(self.group_members)\n        self.cache = cache\n        self.cfg = data_cfg\n        self.quality_norm = quality_norm\n        self.curriculum = curriculum\n        self.augment = augment\n        self.length = length or (len(self.case_ids) * 32)\n        self.seed = seed\n        self.shuffle_quality = shuffle_quality\n        self.zero_quality = zero_quality\n        self.epoch_frac = 0.0\n        self._aug = AugmentConfig(\n            flip_lr=data_cfg.aug_flip_lr,\n            rotation_deg=data_cfg.aug_rotation_deg,\n            scale=data_cfg.aug_scale,\n            elastic=data_cfg.aug_elastic,\n            intensity=data_cfg.aug_intensity,\n        )\n        self._epoch = 0\n        self._shuffled_quality = None\n        self.quality_donors = {}\n        if shuffle_quality:\n            if len(self.group_ids) < 2:\n                raise ValueError("Shuffled-quality control needs at least two training groups")\n            donor_rng = np.random.default_rng(seed + 17000)\n            permutation = donor_rng.permutation(len(self.group_ids))\n            donor = np.roll(permutation, 1)\n            for i, j in zip(permutation, donor):\n                source = self.group_members[self.group_ids[j]]\n                for cid in self.group_members[self.group_ids[i]]:\n                    self.quality_donors[cid] = source[int(donor_rng.integers(len(source)))]\n            self._shuffled_quality = {cid: cache.quality_raw(donor)\n                                      for cid, donor in self.quality_donors.items()}\n\n    def set_epoch(self, epoch: int, max_epochs: int) -> None:\n        """Advance the curriculum. Called by the trainer once per epoch."""\n        self._epoch = epoch\n        self.epoch_frac = float(epoch) / max(max_epochs, 1)\n\n    def __len__(self) -> int:\n        return self.length\n\n    def sample_case(self, rng) -> str:\n        """Equal group probability, then equal probability within that group."""\n        group = self.group_ids[int(rng.integers(len(self.group_ids)))]\n        members = self.group_members[group]\n        return members[int(rng.integers(len(members)))]\n\n    def __getitem__(self, index: int) -> Dict:\n        rng = np.random.default_rng((self.seed, self._epoch, index))\n        case_id = self.sample_case(rng)\n        window, target, z, quality_raw = self.cache.sample_training_window(case_id, self.cfg, rng)\n\n        if self.augment:\n            window, target = augment_window(window, target, rng, self._aug)\n\n        window, _ = center_pad_or_crop(window, tuple(self.cfg.crop_size))\n        target, _ = center_pad_or_crop(target, tuple(self.cfg.crop_size))\n\n        subset = sample_subset(rng, self.epoch_frac, self.curriculum)\n        avail = availability_mask(subset, self.cfg.modalities)\n\n        quality = (self._shuffled_quality[case_id] if self._shuffled_quality is not None\n                   else quality_raw).astype(np.float32)\n        if self.quality_norm is not None:\n            quality = self.quality_norm.transform(quality)\n        if self.zero_quality:\n            quality = np.zeros_like(quality)\n\n        # Absent modalities are zeroed at the input as well as masked in fusion,\n        # so no residual signal can leak through a non-masked path.\n        full_window = window\n        window = full_window * avail[:, None, None, None]\n\n        return {\n            "image": _to_tensor(window, torch.float32),\n            "full_image": _to_tensor(full_window, torch.float32),\n            "target": _to_tensor(target, torch.float32),\n            "availability": _to_tensor(avail, torch.float32),\n            "quality": _to_tensor(quality, torch.float32),\n            "case_id": case_id,\n            "z": int(z),\n        }\n\n\nclass VolumeSliceDataset(Dataset):\n    """Every slice of one case in order, with a fixed availability mask.\n\n    Used for validation, locked-test inference and every one of the 15 subset\n    evaluations. No augmentation, no sampling, no test-time augmentation.\n    """\n\n    def __init__(\n        self,\n        case_id: str,\n        cache: CaseCache,\n        data_cfg: DataConfig,\n        availability: Optional[np.ndarray] = None,\n        quality_norm: Optional[QualityNormalizer] = None,\n        corrupt: Optional[Dict] = None,\n    ):\n        self.case_id = case_id\n        self.cache = cache\n        self.cfg = data_cfg\n        self.rec = cache.load(case_id)\n        self.image = self.rec["image"].astype(np.float32)\n        self.target3d = (self.rec["target"].astype(np.uint8)\n                         if "target" in self.rec else None)\n        self.depth = self.image.shape[-1]\n        # Fully convolutional inference pads to a multiple of 16 and preserves\n        # the entire brain field of view; training crops must not truncate test anatomy.\n        self.inference_size = tuple(max(int(c), ((int(s) + 15) // 16) * 16)\n                                    for c, s in zip(data_cfg.crop_size, self.image.shape[1:3]))\n        self.availability = (\n            np.ones(len(data_cfg.modalities), dtype=np.float32)\n            if availability is None else np.asarray(availability, dtype=np.float32)\n        )\n        if corrupt is not None:\n            self._apply_corruption(corrupt)\n        quality = self.rec["quality_raw"].astype(np.float32)\n        if corrupt is not None:\n            # Quality is recomputed on the corrupted image: the whole point of\n            # the quality vector is that it reacts to degraded input.\n            quality = compute_quality_matrix(\n                [self.image[m] for m in range(self.image.shape[0])],\n                self.rec["brain_mask"],\n            )\n        self.quality = (quality_norm.transform(quality)\n                        if quality_norm is not None else quality)\n        self.image = self.image * self.availability[:, None, None, None]\n        self._offsets: Optional[Tuple[int, int, int, int]] = None\n\n    def _apply_corruption(self, corrupt: Dict) -> None:\n        from .transforms import apply_corruption\n        targets = corrupt.get("modalities")\n        if targets is None:\n            targets = [m for m in range(self.image.shape[0]) if self.availability[m] > 0]\n        for m in targets:\n            if self.availability[m] <= 0:\n                continue\n            self.image[m] = apply_corruption(\n                self.image[m], corrupt["kind"], corrupt["severity"],\n                seed=corrupt.get("seed", 0) + m,\n            )\n\n    def __len__(self) -> int:\n        return self.depth\n\n    def __getitem__(self, z: int) -> Dict:\n        window = extract_window(self.image, z, self.cfg.context_slices)\n        window, offsets = center_pad_or_crop(window, self.inference_size)\n        self._offsets = offsets\n        item = {\n            "image": _to_tensor(window, torch.float32),\n            "availability": _to_tensor(self.availability, torch.float32),\n            "quality": _to_tensor(self.quality, torch.float32),\n            "z": int(z),\n        }\n        if self.target3d is not None:\n            tgt = self.target3d[..., z].astype(np.float32)\n            tgt, _ = center_pad_or_crop(tgt, self.inference_size)\n            item["target"] = _to_tensor(tgt, torch.float32)\n        return item\n\n    # ------------------------------------------------------------------ #\n    @property\n    def geometry(self) -> Dict:\n        """Everything needed to invert the 2.5D pipeline exactly."""\n        return {\n            "crop_box": self.rec["crop_box"].tolist(),\n            "original_shape": tuple(int(s) for s in self.rec["original_shape"]),\n            "cropped_hw": (int(self.image.shape[1]), int(self.image.shape[2])),\n            "depth": self.depth,\n            "pad_offsets": self._offsets,\n        }\n\n\ndef collate(batch: List[Dict]) -> Dict:\n    """Default collation that keeps string ids as a list."""\n    out: Dict = {}\n    for key in batch[0]:\n        values = [b[key] for b in batch]\n        if torch is not None and torch.is_tensor(values[0]):\n            out[key] = torch.stack(values, dim=0)\n        else:\n            out[key] = values\n    return out\n', 'segmentation/src/qmmf/ema.py': '"""Exponential moving average teacher (plan 8.4).\n\nThe teacher always sees the full four-modality input; the student sees a\nsampled subset. No separate heavyweight teacher network is trained, which is\nwhat keeps the consistency term affordable on a single T4.\n"""\n\nfrom __future__ import annotations\n\nimport copy\nfrom typing import Iterator, Optional\n\nimport torch\nimport torch.nn as nn\n\n\nclass ModelEMA:\n    def __init__(self, model: nn.Module, decay_start: float = 0.99,\n                 decay_end: float = 0.999, warmup_steps: int = 1000,\n                 device: Optional[torch.device] = None):\n        self.module = copy.deepcopy(model).eval()\n        for p in self.module.parameters():\n            p.requires_grad_(False)\n        if device is not None:\n            self.module.to(device)\n        self.decay_start = decay_start\n        self.decay_end = decay_end\n        self.warmup_steps = max(warmup_steps, 1)\n        self.step_count = 0\n\n    def current_decay(self) -> float:\n        """Ramp from decay_start to decay_end over warmup_steps."""\n        t = min(self.step_count / self.warmup_steps, 1.0)\n        return self.decay_start + (self.decay_end - self.decay_start) * t\n\n    @torch.no_grad()\n    def update(self, model: nn.Module) -> None:\n        d = self.current_decay()\n        msd = model.state_dict()\n        for key, value in self.module.state_dict().items():\n            source = msd[key]\n            if value.dtype.is_floating_point:\n                value.mul_(d).add_(source.detach().to(value.dtype), alpha=1.0 - d)\n            else:\n                value.copy_(source)\n        self.step_count += 1\n\n    @torch.no_grad()\n    def __call__(self, *args, **kwargs):\n        return self.module(*args, **kwargs)\n\n    def state_dict(self):\n        return {"module": self.module.state_dict(), "step_count": self.step_count}\n\n    def load_state_dict(self, state):\n        self.module.load_state_dict(state["module"])\n        self.step_count = int(state.get("step_count", 0))\n', 'segmentation/src/qmmf/evaluate.py': '"""End-to-end evaluation orchestration.\n\nTies inference, metrics, subsets, Shapley, calibration and statistics into the\nthree things the plan actually asks for:\n\n  * `evaluate_cases`        - full-modality patient metrics for a cohort;\n  * `evaluate_all_subsets`  - the exhaustive 15-subset table per patient;\n  * `validation_metrics`    - the cheap in-training validation used by the\n                              composite checkpoint-selection rule.\n"""\n\nfrom __future__ import annotations\n\nfrom pathlib import Path\nfrom typing import Dict, List, Optional, Sequence\n\nimport numpy as np\nimport torch\n\nfrom .calibration import case_uncertainty_summary\nfrom .config import ExperimentConfig\nfrom .dataset import CaseCache\nfrom .inference import binarize, predict_volume\nfrom .metrics import CaseMetrics, evaluate_case, macro_dice, summarize\nfrom .subsets import ALL_SUBSETS, availability_mask, subset_key\n\n\nDEFAULT_VALIDATION_SUBSETS = [\n    ("t1", "t1ce", "t2", "flair"),\n    ("t1", "t2", "flair"),          # T1ce missing: the hard TC/ET case\n    ("t1", "t1ce", "t2"),           # FLAIR missing: the hard WT case\n    ("t1ce",),\n    ("flair",),\n]\n\n\ndef evaluate_cases(\n    model: torch.nn.Module,\n    case_ids: Sequence[str],\n    cache: CaseCache,\n    cfg: ExperimentConfig,\n    spacing_lookup: Dict[str, Sequence[float]],\n    availability: Optional[np.ndarray] = None,\n    threshold: float = 0.5,\n    device: Optional[torch.device] = None,\n    corrupt: Optional[Dict] = None,\n    collect_probs: bool = False,\n    detailed_metrics: bool = True,\n) -> Dict[str, object]:\n    """Patient-level metrics for a cohort under one availability mask."""\n    rows: List[CaseMetrics] = []\n    per_case_macro: Dict[str, float] = {}\n    uncertainty: Dict[str, Dict[str, float]] = {}\n    gates: Dict[str, np.ndarray] = {}\n    probs_out: Dict[str, np.ndarray] = {}\n\n    for cid in case_ids:\n        out = predict_volume(model, cid, cache, cfg, availability, corrupt=corrupt,\n                             device=device)\n        probs = out["probs"]\n        ref = out["reference"]\n        if ref is None:\n            raise ValueError(f"Case {cid} has no reference labels to evaluate against.")\n        pred = binarize(probs, threshold)\n        spacing = spacing_lookup.get(cid, (1.0, 1.0, 1.0))\n        case_rows = evaluate_case(pred, ref, spacing, case_id=cid,\n                                  nsd_tolerance_mm=cfg.evaluation.nsd_tolerance_mm,\n                                  lesion_metrics=detailed_metrics, surface_metrics=detailed_metrics)\n        rows.extend(case_rows)\n        per_case_macro[cid] = macro_dice(case_rows)\n        if detailed_metrics:\n            uncertainty[cid] = case_uncertainty_summary(probs)\n        if "gate_alpha" in out:\n            gates[cid] = out["gate_alpha"]\n        if collect_probs:\n            probs_out[cid] = probs.astype(np.float16)\n\n    return {\n        "rows": rows,\n        "summary": summarize(rows),\n        "per_case_macro": per_case_macro,\n        "uncertainty": uncertainty,\n        "gates": gates,\n        "probs": probs_out,\n    }\n\n\ndef evaluate_all_subsets(\n    model: torch.nn.Module,\n    case_ids: Sequence[str],\n    cache: CaseCache,\n    cfg: ExperimentConfig,\n    spacing_lookup: Dict[str, Sequence[float]],\n    threshold: float = 0.5,\n    device: Optional[torch.device] = None,\n    subsets: Optional[Sequence[Sequence[str]]] = None,\n) -> Dict[str, object]:\n    """The exhaustive counterfactual table: every case under every subset.\n\n    Returns per_case[case_id][subset_key] = macro Dice, plus per-region tables,\n    which is exactly the input exact Shapley needs.\n    """\n    subsets = subsets or ALL_SUBSETS\n    per_case: Dict[str, Dict[str, float]] = {c: {} for c in case_ids}\n    per_case_region: Dict[str, Dict[str, Dict[str, float]]] = {\n        c: {} for c in case_ids\n    }\n    subset_summary: Dict[str, Dict[str, float]] = {}\n    gates: Dict[str, Dict[str, np.ndarray]] = {c: {} for c in case_ids}\n\n    for subset in subsets:\n        key = subset_key(subset)\n        mask = availability_mask(subset, cfg.data.modalities)\n        result = evaluate_cases(model, case_ids, cache, cfg, spacing_lookup,\n                                availability=mask, threshold=threshold, device=device,\n                                detailed_metrics=False)\n        subset_summary[key] = result["summary"]\n        for cid, value in result["per_case_macro"].items():\n            per_case[cid][key] = value\n        for row in result["rows"]:\n            per_case_region[row.case_id].setdefault(row.region, {})[key] = row.dice\n        for cid, g in result["gates"].items():\n            gates[cid][key] = g\n\n    mean_over_subsets = {\n        c: float(np.nanmean(list(v.values()))) for c, v in per_case.items()\n    }\n    worst_subset = {\n        c: float(np.nanmin(list(v.values()))) for c, v in per_case.items()\n    }\n    return {\n        "per_case": per_case,\n        "per_case_region": per_case_region,\n        "subset_summary": subset_summary,\n        "mean_over_subsets": mean_over_subsets,\n        "worst_subset": worst_subset,\n        "gates": gates,\n    }\n\n\ndef validation_metrics(\n    model: torch.nn.Module,\n    case_ids: Sequence[str],\n    cache: CaseCache,\n    cfg: ExperimentConfig,\n    spacing_lookup: Dict[str, Sequence[float]],\n    device: Optional[torch.device] = None,\n    subsets: Sequence[Sequence[str]] = tuple(DEFAULT_VALIDATION_SUBSETS),\n    max_cases: Optional[int] = None,\n) -> Dict[str, float]:\n    """Cheap validation for checkpoint selection.\n\n    Uses a small fixed set of subsets rather than all 15, because validation\n    runs every epoch. The full 15-subset evaluation is a locked-test activity.\n    """\n    ids = list(case_ids)[:max_cases] if max_cases else list(case_ids)\n    scores: Dict[str, float] = {}\n    per_subset_case: List[List[float]] = []\n\n    for subset in subsets:\n        mask = availability_mask(subset, cfg.data.modalities)\n        res = evaluate_cases(model, ids, cache, cfg, spacing_lookup,\n                             availability=mask, device=device, detailed_metrics=False)\n        vals = [res["per_case_macro"][c] for c in ids]\n        scores[f"macro_dice::{subset_key(subset)}"] = float(np.nanmean(vals))\n        per_subset_case.append(vals)\n\n    full_key = f"macro_dice::{subset_key(tuple(cfg.data.modalities))}"\n    arr = np.array(per_subset_case, dtype=float)          # [n_subsets, n_cases]\n    return {\n        "full_macro_dice": scores.get(full_key, float("nan")),\n        "mean_subset_macro_dice": float(np.nanmean(arr)),\n        "worst_subset_macro_dice": float(np.nanmean(np.nanmin(arr, axis=0))),\n        **scores,\n    }\n', 'segmentation/src/qmmf/grouping.py': '"""Equal weighting of conservative image groups; no patient-identity claim."""\nfrom collections import defaultdict\nimport numpy as np\n\n\ndef group_means(per_case, case_to_group):\n    """Mean cases within each group, retaining one value per observed group."""\n    values = defaultdict(list)\n    for cid, value in per_case.items():\n        if cid not in case_to_group or not np.isfinite(value):\n            raise ValueError("Every finite case score needs a known similarity group")\n        values[case_to_group[cid]].append(float(value))\n    if not values:\n        raise ValueError("Cannot aggregate an empty cohort")\n    return {group: float(np.mean(items)) for group, items in sorted(values.items())}\n\n\ndef group_quality_medians(case_ids, cache, case_to_group):\n    """One robust descriptor matrix per training group for fitting its scaler."""\n    values = defaultdict(list)\n    for cid in case_ids:\n        values[case_to_group[cid]].append(cache.quality_raw(cid))\n    return [np.median(np.stack(values[g]), axis=0) for g in sorted(values)]\n', 'segmentation/src/qmmf/inference.py': '"""2.5D inference and exact 3D reconstruction (plan 6.2 step 13, 11.3).\n\nThe central slice of each window is the prediction for that slice; slices are\nassembled in order, the pad/crop is inverted, and the brain crop is undone, so\nthe output lands in the original volume geometry voxel-for-voxel. `test_reconstruction`\nin the test suite checks that this round-trip is exact on synthetic data.\n\nNo test-time augmentation on the default path (plan 11.3); TTA exists only as a\nseparately reported optional ablation.\n"""\n\nfrom __future__ import annotations\n\nfrom pathlib import Path\nfrom typing import Dict, List, Optional, Sequence, Tuple\n\nimport numpy as np\nimport torch\nfrom torch.utils.data import DataLoader\n\nfrom .config import ExperimentConfig\nfrom .dataset import CaseCache, VolumeSliceDataset, collate\nfrom .models import project_nested_numpy\nfrom .transforms import invert_center_pad_or_crop, uncrop_to_original\n\n\n@torch.no_grad()\ndef predict_volume(\n    model: torch.nn.Module,\n    case_id: str,\n    cache: CaseCache,\n    cfg: ExperimentConfig,\n    availability: Optional[np.ndarray] = None,\n    corrupt: Optional[Dict] = None,\n    device: Optional[torch.device] = None,\n    batch_size: int = 8,\n    return_logits: bool = False,\n    apply_nesting: bool = True,\n) -> Dict[str, np.ndarray]:\n    """Run one case through the model and reconstruct a full 3D probability map.\n\n    Returns {\'probs\': [3, H, W, D] in original volume geometry, \'gate_alpha\':\n    [S, M] mean gate weights, \'geometry\': ...}.\n    """\n    device = device or next(model.parameters()).device\n    model.eval()\n\n    normalizer = getattr(model, "quality_normalizer", None)\n    if cfg.model == "qmmf_net" and cfg.net.use_quality and normalizer is None:\n        raise ValueError("Quality-conditioned inference requires the training-fitted normalizer")\n    ds = VolumeSliceDataset(case_id, cache, cfg.data, availability,\n                            quality_norm=normalizer, corrupt=corrupt)\n    loader = DataLoader(ds, batch_size=batch_size, shuffle=False, num_workers=0,\n                        collate_fn=collate)\n\n    cropped_h, cropped_w = ds.image.shape[1], ds.image.shape[2]\n    depth = ds.depth\n    n_out = len(cfg.data.outputs)\n    slices: List[np.ndarray] = []\n    gate_alpha: List[np.ndarray] = []\n    offsets: Optional[Tuple[int, int, int, int]] = None\n\n    for batch in loader:\n        image = batch["image"].to(device)\n        avail = batch["availability"].to(device)\n        quality = batch["quality"].to(device)\n        with torch.autocast("cuda", enabled=(cfg.train.amp and device.type == "cuda")):\n            out = model(image, avail, quality, return_aux=True)\n        logits, aux = out if isinstance(out, tuple) else (out, {})\n        logits = logits.float()\n        if not torch.isfinite(logits).all():\n            raise FloatingPointError(f"Non-finite inference logits for {case_id}")\n        arr = logits.cpu().numpy() if return_logits else torch.sigmoid(logits).cpu().numpy()\n        slices.append(arr)\n        if "gate_alpha" in aux:\n            gate_alpha.append(aux["gate_alpha"].float().cpu().numpy())\n        offsets = ds._offsets\n\n    stacked = np.concatenate(slices, axis=0)            # [D, 3, h, w] in model space\n    stacked = np.moveaxis(stacked, 0, -1)               # [3, h, w, D]\n\n    # Invert the pad/crop back to the cropped-brain grid, slice by slice.\n    restored = np.stack([\n        invert_center_pad_or_crop(stacked[..., z], offsets, (cropped_h, cropped_w))\n        for z in range(depth)\n    ], axis=-1)                                         # [3, H_c, W_c, D]\n\n    if apply_nesting and not return_logits:\n        restored = project_nested_numpy(restored)\n\n    geom = ds.geometry\n    full = uncrop_to_original(restored, geom["crop_box"], geom["original_shape"])\n\n    out: Dict[str, np.ndarray] = {"probs" if not return_logits else "logits": full}\n    if gate_alpha:\n        out["gate_alpha"] = np.concatenate(gate_alpha, axis=0).mean(axis=0)   # [S, M]\n    out["geometry"] = geom\n    out["reference"] = (\n        uncrop_to_original(ds.target3d, geom["crop_box"], geom["original_shape"])\n        if ds.target3d is not None else None\n    )\n    return out\n\n\ndef binarize(probs: np.ndarray, threshold: float = 0.5,\n             enforce_nesting: bool = True) -> np.ndarray:\n    """Threshold then (optionally) enforce ET subset TC subset WT on the masks.\n\n    The threshold is fixed on development data only and never tuned on the\n    locked test (plan 6.1, gate G6).\n    """\n    masks = (np.asarray(probs) >= threshold)\n    if not np.isfinite(probs).all():\n        raise FloatingPointError("Non-finite probabilities cannot be reported as empty predictions")\n    if enforce_nesting:\n        wt = masks[0]\n        tc = masks[1] & wt\n        et = masks[2] & tc\n        masks = np.stack([wt, tc, et], axis=0)\n    return masks\n\n\n@torch.no_grad()\ndef predict_all_subsets(\n    model: torch.nn.Module,\n    case_id: str,\n    cache: CaseCache,\n    cfg: ExperimentConfig,\n    device: Optional[torch.device] = None,\n    batch_size: int = 8,\n) -> Dict[str, Dict[str, np.ndarray]]:\n    """Exhaustive inference over the 15 non-empty modality subsets for one case.\n\n    This is what makes the Shapley values exact rather than sampled.\n    """\n    from .subsets import ALL_SUBSETS, availability_mask, subset_key\n\n    out: Dict[str, Dict[str, np.ndarray]] = {}\n    for subset in ALL_SUBSETS:\n        mask = availability_mask(subset, cfg.data.modalities)\n        out[subset_key(subset)] = predict_volume(\n            model, case_id, cache, cfg, availability=mask,\n            device=device, batch_size=batch_size,\n        )\n    return out\n\n\n@torch.no_grad()\ndef ensemble_predict(\n    models: Sequence[torch.nn.Module],\n    case_id: str,\n    cache: CaseCache,\n    cfg: ExperimentConfig,\n    availability: Optional[np.ndarray] = None,\n    device: Optional[torch.device] = None,\n    batch_size: int = 8,\n) -> Dict[str, np.ndarray]:\n    """Three-seed deep ensemble: mean probability plus inter-model variance."""\n    members = [\n        predict_volume(m, case_id, cache, cfg, availability, device=device,\n                       batch_size=batch_size, apply_nesting=False)["probs"]\n        for m in models\n    ]\n    stack = np.stack(members, axis=0)\n    mean = stack.mean(axis=0)\n    return {\n        "probs": project_nested_numpy(mean),\n        "variance": stack.var(axis=0),\n        "members": stack,\n    }\n\n\ndef compress_probabilities(probs: np.ndarray, brain_mask: Optional[np.ndarray] = None\n                           ) -> Dict[str, np.ndarray]:\n    """Store only what the analysis needs (plan 11.3): float16 probabilities\n    inside the brain support, not full feature maps for every patient."""\n    p = np.asarray(probs, dtype=np.float16)\n    if brain_mask is None:\n        return {"probs_f16": p}\n    idx = np.nonzero(brain_mask)\n    return {\n        "values_f16": p[(slice(None),) + idx].astype(np.float16),\n        "index": np.stack(idx).astype(np.int16),\n        "shape": np.array(p.shape, dtype=np.int32),\n    }\n\n\ndef decompress_probabilities(payload: Dict[str, np.ndarray]) -> np.ndarray:\n    if "probs_f16" in payload:\n        return payload["probs_f16"].astype(np.float32)\n    shape = tuple(int(s) for s in payload["shape"])\n    out = np.zeros(shape, dtype=np.float32)\n    idx = tuple(payload["index"].astype(int))\n    out[(slice(None),) + idx] = payload["values_f16"].astype(np.float32)\n    return out\n', 'segmentation/src/qmmf/labels.py': '"""Label-map verification and WT/TC/ET derivation.\n\nThe plan flags this as a critical hazard (TriMUSE 3.3, QMMF 5.5/6.2): MSD\nTask01 label integers are *not* assumed to follow any tutorial convention.\n`infer_label_scheme` checks the dataset\'s own metadata and the data itself, and\n`to_nested_targets` refuses to convert under an unverified scheme.\n\nAdult MSD Task01 dataset.json declares:\n    0 background, 1 edema, 2 non-enhancing tumour, 3 enhancing tumour\nBraTS-style files usually declare:\n    0 background, 1 necrotic/non-enhancing core, 2 edema, 4 enhancing tumour\nThese map to different WT/TC/ET expressions, so the scheme must be resolved\nper cohort before any target is built.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom typing import Dict, Iterable, Mapping, Optional, Sequence\n\nimport numpy as np\n\n\n@dataclass(frozen=True)\nclass LabelScheme:\n    """Which integer label means what, for one cohort."""\n\n    name: str\n    edema: int\n    non_enhancing: int\n    enhancing: int\n    background: int = 0\n\n    def component_labels(self) -> Dict[str, int]:\n        return {\n            "background": self.background,\n            "edema": self.edema,\n            "non_enhancing": self.non_enhancing,\n            "enhancing": self.enhancing,\n        }\n\n    def wt_labels(self) -> set:\n        return {self.edema, self.non_enhancing, self.enhancing}\n\n    def tc_labels(self) -> set:\n        return {self.non_enhancing, self.enhancing}\n\n    def et_labels(self) -> set:\n        return {self.enhancing}\n\n\n# The two schemes seen in practice. Nothing here is applied without verification.\nMSD_TASK01 = LabelScheme(name="msd_task01", edema=1, non_enhancing=2, enhancing=3)\nBRATS_LEGACY = LabelScheme(name="brats_legacy", edema=2, non_enhancing=1, enhancing=4)\n\nKNOWN_SCHEMES = (MSD_TASK01, BRATS_LEGACY)\n\n# Keyword -> component, used to read dataset.json "labels" dictionaries.\n_KEYWORDS = {\n    "edema": "edema",\n    "oedema": "edema",\n    "peritumoral": "edema",\n    "non-enhancing": "non_enhancing",\n    "nonenhancing": "non_enhancing",\n    "necrotic": "non_enhancing",\n    "necrosis": "non_enhancing",\n    "ncr": "non_enhancing",\n    "net": "non_enhancing",\n    "core": "non_enhancing",\n    "enhancing": "enhancing",\n    "background": "background",\n}\n\n\nclass LabelSchemeError(RuntimeError):\n    """Raised when the label scheme cannot be established from evidence."""\n\n\ndef scheme_from_dataset_json(labels: Mapping) -> LabelScheme:\n    """Parse the `labels` block of a dataset.json into a LabelScheme.\n\n    \'non-enhancing\' is checked before \'enhancing\' because the former contains\n    the latter as a substring.\n    """\n    assigned: Dict[str, int] = {}\n    for key, value in labels.items():\n        try:\n            index = int(key)\n        except (TypeError, ValueError):\n            # Some cards invert the mapping: {"edema": "1", ...}\n            index = int(value)\n            value = key\n        text = str(value).strip().lower()\n        component = None\n        for keyword in ("non-enhancing", "nonenhancing", "necrotic", "necrosis",\n                        "ncr", "net", "enhancing", "edema", "oedema",\n                        "peritumoral", "background", "core"):\n            if keyword in text:\n                component = _KEYWORDS[keyword]\n                break\n        if component is None:\n            raise LabelSchemeError(\n                f"Unrecognised label description {value!r} for index {index}. "\n                "Inspect dataset.json manually before deriving WT/TC/ET."\n            )\n        if component in assigned and assigned[component] != index:\n            raise LabelSchemeError(\n                f"Component \'{component}\' claimed by both label {assigned[component]} "\n                f"and {index}."\n            )\n        assigned[component] = index\n    missing = {"edema", "non_enhancing", "enhancing"} - set(assigned)\n    if missing:\n        raise LabelSchemeError(f"dataset.json is missing components: {sorted(missing)}")\n    return LabelScheme(\n        name="from_dataset_json",\n        background=assigned.get("background", 0),\n        edema=assigned["edema"],\n        non_enhancing=assigned["non_enhancing"],\n        enhancing=assigned["enhancing"],\n    )\n\n\ndef verify_scheme_against_data(\n    scheme: LabelScheme,\n    observed_labels: Iterable[int],\n) -> None:\n    """Assert that every observed integer belongs to the declared scheme."""\n    declared = set(scheme.component_labels().values())\n    observed = {int(v) for v in observed_labels}\n    unexpected = observed - declared\n    if unexpected:\n        raise LabelSchemeError(\n            f"Labels {sorted(unexpected)} are present in the data but not declared "\n            f"by scheme \'{scheme.name}\' ({sorted(declared)}). "\n            "Do not convert until this is resolved."\n        )\n\n\ndef infer_label_scheme(\n    dataset_json: Optional[Mapping] = None,\n    observed_labels: Optional[Iterable[int]] = None,\n) -> LabelScheme:\n    """Resolve the scheme from metadata when possible, otherwise from observed\n    labels only when they are unambiguous. Raises rather than guessing."""\n    if dataset_json is not None and "labels" in dataset_json:\n        scheme = scheme_from_dataset_json(dataset_json["labels"])\n        if observed_labels is not None:\n            verify_scheme_against_data(scheme, observed_labels)\n        return scheme\n    if observed_labels is None:\n        raise LabelSchemeError("Provide dataset.json labels or observed label values.")\n    observed = {int(v) for v in observed_labels}\n    matches = [s for s in KNOWN_SCHEMES if observed <= set(s.component_labels().values())]\n    if len(matches) != 1:\n        raise LabelSchemeError(\n            f"Observed labels {sorted(observed)} match {len(matches)} known schemes. "\n            "Manual verification is required (plan 5.5 \'Label dictionary\')."\n        )\n    return matches[0]\n\n\n# --------------------------------------------------------------------------- #\n# Target construction\n# --------------------------------------------------------------------------- #\ndef to_nested_targets(seg: np.ndarray, scheme: LabelScheme) -> np.ndarray:\n    """Map an integer segmentation to three overlapping binary channels.\n\n    Returns array of shape (3, ...) ordered (WT, TC, ET), as uint8.\n    The nesting ET subset TC subset WT holds by construction.\n    """\n    seg = np.asarray(seg)\n    # Refuse to convert under an unverified scheme: an integer the scheme does\n    # not declare means the mirror is not the cohort we think it is.\n    verify_scheme_against_data(scheme, np.unique(seg).tolist())\n    wt = np.isin(seg, list(scheme.wt_labels()))\n    tc = np.isin(seg, list(scheme.tc_labels()))\n    et = np.isin(seg, list(scheme.et_labels()))\n    stacked = np.stack([wt, tc, et], axis=0).astype(np.uint8)\n    assert_nesting(stacked)\n    return stacked\n\n\ndef assert_nesting(targets: np.ndarray) -> None:\n    """ET subset TC subset WT, enforced on every derived target."""\n    wt, tc, et = targets[0].astype(bool), targets[1].astype(bool), targets[2].astype(bool)\n    if np.any(et & ~tc):\n        raise LabelSchemeError("Nesting violated: ET voxels outside TC.")\n    if np.any(tc & ~wt):\n        raise LabelSchemeError("Nesting violated: TC voxels outside WT.")\n\n\ndef label_histogram(seg: np.ndarray) -> Dict[int, int]:\n    values, counts = np.unique(np.asarray(seg), return_counts=True)\n    return {int(v): int(c) for v, c in zip(values, counts)}\n\n\ndef region_volumes_ml(\n    targets: np.ndarray, spacing_mm: Sequence[float]\n) -> Dict[str, float]:\n    """Volume of each nested region in millilitres."""\n    voxel_ml = float(np.prod(np.asarray(spacing_mm, dtype=np.float64))) / 1000.0\n    names = ("wt", "tc", "et")\n    return {n: float(targets[i].sum()) * voxel_ml for i, n in enumerate(names)}\n\n\ndef et_present(targets: np.ndarray, min_voxels: int = 1) -> bool:\n    """ET presence indicator used for split stratification and empty-region rules."""\n    return bool(targets[2].sum() >= min_voxels)\n', 'segmentation/src/qmmf/ledger.py': '"""Append-safe experiment queue and ledger (plan 11.2, Appendix C).\n\nTwo processes - one per T4 - claim experiments from a shared JSON queue and\nappend rows to a shared CSV ledger. Both operations use file locking plus\natomic rename so an interrupted Kaggle session cannot corrupt the record or\ncause the same experiment to run twice.\n"""\n\nfrom __future__ import annotations\n\nimport csv\nimport fcntl\nimport json\nimport os\nimport time\nimport traceback\nfrom contextlib import contextmanager\nfrom dataclasses import dataclass, asdict, field\nfrom pathlib import Path\nfrom typing import Any, Dict, Iterable, List, Optional\n\nLEDGER_FIELDS: List[str] = [\n    "run_id", "status", "gpu", "model", "ablation", "fold", "seed",\n    "label_fraction", "stage", "config_hash", "manifest_hash", "split_hash",\n    "code_hash", "best_epoch", "best_score", "checkpoint",\n    "full_macro_dice", "mean_subset_macro_dice", "worst_subset_macro_dice",\n    "parameters", "macs", "peak_vram_gb", "wall_seconds", "seconds_per_volume",\n    "failure_message", "timestamp", "git_commit",\n]\n\nSTATUSES = ("pending", "running", "completed", "failed", "resource_rejected")\n\n\n@contextmanager\ndef file_lock(path: Path, timeout: float = 60.0):\n    """Exclusive advisory lock on a sidecar file."""\n    path.parent.mkdir(parents=True, exist_ok=True)\n    lock_path = path.with_suffix(path.suffix + ".lock")\n    start = time.time()\n    fh = open(lock_path, "a+")\n    try:\n        while True:\n            try:\n                fcntl.flock(fh, fcntl.LOCK_EX | fcntl.LOCK_NB)\n                break\n            except BlockingIOError:\n                if time.time() - start > timeout:\n                    raise TimeoutError(f"Could not lock {lock_path} within {timeout}s")\n                time.sleep(0.1)\n        yield\n    finally:\n        try:\n            fcntl.flock(fh, fcntl.LOCK_UN)\n        finally:\n            fh.close()\n\n\n# --------------------------------------------------------------------------- #\n@dataclass\nclass ExperimentEntry:\n    run_id: str\n    model: str\n    ablation: str = "A0"\n    fold: int = 0\n    seed: int = 42\n    label_fraction: float = 1.0\n    stage: str = "development"\n    config_path: str = ""\n    status: str = "pending"\n    claimed_by: Optional[int] = None\n    claimed_at: Optional[float] = None\n\n    def to_dict(self) -> Dict[str, Any]:\n        return asdict(self)\n\n\nclass ExperimentQueue:\n    """A JSON list of experiments that two workers claim atomically."""\n\n    def __init__(self, path: str | Path):\n        self.path = Path(path)\n        if not self.path.exists():\n            self._write([])\n\n    # -------------------------------------------------------------- #\n    def _read(self) -> List[Dict[str, Any]]:\n        return json.loads(self.path.read_text()) if self.path.exists() else []\n\n    def _write(self, entries: List[Dict[str, Any]]) -> None:\n        tmp = self.path.with_suffix(".tmp")\n        tmp.parent.mkdir(parents=True, exist_ok=True)\n        tmp.write_text(json.dumps(entries, indent=2))\n        tmp.replace(self.path)\n\n    # -------------------------------------------------------------- #\n    def add(self, entries: Iterable[ExperimentEntry], skip_existing: bool = True) -> int:\n        with file_lock(self.path):\n            current = self._read()\n            known = {e["run_id"] for e in current}\n            added = 0\n            for e in entries:\n                if skip_existing and e.run_id in known:\n                    continue\n                current.append(e.to_dict())\n                known.add(e.run_id)\n                added += 1\n            self._write(current)\n        return added\n\n    def claim(self, gpu: int, stale_after: float = 6 * 3600) -> Optional[Dict[str, Any]]:\n        """Atomically take the next pending experiment.\n\n        A \'running\' entry older than `stale_after` is reclaimed, which is what\n        makes the queue survive a Kaggle session that was cut off mid-run.\n        """\n        with file_lock(self.path):\n            entries = self._read()\n            now = time.time()\n            for e in entries:\n                stale = (\n                    e["status"] == "running"\n                    and e.get("claimed_at") is not None\n                    and now - float(e["claimed_at"]) > stale_after\n                )\n                if e["status"] == "pending" or stale:\n                    e["status"] = "running"\n                    e["claimed_by"] = gpu\n                    e["claimed_at"] = now\n                    self._write(entries)\n                    return dict(e)\n            return None\n\n    def release(self, run_id: str, status: str) -> None:\n        if status not in STATUSES:\n            raise ValueError(f"Unknown status \'{status}\'. Have {STATUSES}.")\n        with file_lock(self.path):\n            entries = self._read()\n            for e in entries:\n                if e["run_id"] == run_id:\n                    e["status"] = status\n            self._write(entries)\n\n    def summary(self) -> Dict[str, int]:\n        entries = self._read()\n        out: Dict[str, int] = {s: 0 for s in STATUSES}\n        for e in entries:\n            out[e["status"]] = out.get(e["status"], 0) + 1\n        out["total"] = len(entries)\n        return out\n\n    def pending(self) -> List[Dict[str, Any]]:\n        return [e for e in self._read() if e["status"] == "pending"]\n\n\n# --------------------------------------------------------------------------- #\nclass Ledger:\n    """Append-only CSV of run outcomes. One row per run, written under a lock."""\n\n    def __init__(self, path: str | Path, fields: Optional[List[str]] = None):\n        self.path = Path(path)\n        self.fields = fields or LEDGER_FIELDS\n        if not self.path.exists():\n            self.path.parent.mkdir(parents=True, exist_ok=True)\n            with self.path.open("w", newline="") as fh:\n                csv.DictWriter(fh, fieldnames=self.fields).writeheader()\n\n    def append(self, row: Dict[str, Any]) -> None:\n        clean = {k: row.get(k, "") for k in self.fields}\n        clean["timestamp"] = clean.get("timestamp") or time.strftime(\n            "%Y-%m-%dT%H:%M:%SZ", time.gmtime()\n        )\n        with file_lock(self.path):\n            with self.path.open("a", newline="") as fh:\n                csv.DictWriter(fh, fieldnames=self.fields).writerow(clean)\n\n    def read(self):\n        import pandas as pd\n        return pd.read_csv(self.path)\n\n    def completed_run_ids(self) -> set:\n        df = self.read()\n        if df.empty:\n            return set()\n        return set(df.loc[df.status == "completed", "run_id"].astype(str))\n\n    def record_failure(self, row: Dict[str, Any], exc: BaseException) -> None:\n        """Failures are recorded, not swallowed (plan 9.2: \'report failures,\n        OOMs and runtime gates rather than silently dropping baselines\')."""\n        row = dict(row)\n        row["status"] = "failed"\n        row["failure_message"] = (\n            f"{type(exc).__name__}: {exc}\\n{traceback.format_exc()[-4000:]}"\n        )\n        self.append(row)\n', 'segmentation/src/qmmf/losses.py': '"""Loss composition of plan 8.1-8.2.\n\n    L_seg   = 0.60 * soft_dice + 0.40 * BCE\n    L_total = 1.00 * L_seg\n            + 0.10 * L_boundary\n            + 0.05 * L_nested\n            + 0.20 * L_subset_consistency\n            + 0.02 * L_calibration     (optional ablation, not assumed beneficial)\n\nEvery auxiliary term has a matching ablation (A10, A12, A13 and the calibration\nablation), so a term that does not earn its place is removed and the negative\nresult is reported.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom typing import Dict, List, Optional, Sequence\n\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\n\nfrom .config import LossConfig\n\n\n# --------------------------------------------------------------------------- #\n# Overlap and voxel terms\n# --------------------------------------------------------------------------- #\ndef soft_dice_loss(\n    logits: torch.Tensor, target: torch.Tensor, eps: float = 1e-5,\n    weights: Optional[torch.Tensor] = None,\n) -> torch.Tensor:\n    """Per-sample, per-region soft Dice on sigmoid probabilities.\n\n    Averaged over regions then over the batch, so a large WT does not dominate\n    a small ET (plan 5.6 of the sibling plan; same discipline applies here).\n    """\n    probs = torch.sigmoid(logits.float())\n    dims = tuple(range(2, probs.dim()))\n    inter = (probs * target).sum(dims)\n    denom = probs.sum(dims) + target.sum(dims)\n    dice = (2 * inter + eps) / (denom + eps)\n    loss = 1.0 - dice                                    # [B, R]\n    if weights is not None:\n        loss = loss * weights.to(loss.dtype).view(1, -1)\n        return loss.sum(dim=1).mean() / weights.sum()\n    return loss.mean()\n\n\ndef bce_loss(\n    logits: torch.Tensor, target: torch.Tensor,\n    pos_weight: Optional[torch.Tensor] = None,\n) -> torch.Tensor:\n    return F.binary_cross_entropy_with_logits(\n        logits, target, pos_weight=pos_weight, reduction="mean"\n    )\n\n\ndef nested_penalty(logits: torch.Tensor) -> torch.Tensor:\n    """Penalise ET outside TC and TC outside WT (plan 8.2).\n\n    L = mean(relu(p_ET - p_TC)) + mean(relu(p_TC - p_WT)); differentiable, and\n    the hard projection is applied separately at inference.\n    """\n    p = torch.sigmoid(logits.float())\n    wt, tc, et = p[:, 0], p[:, 1], p[:, 2]\n    return F.relu(et - tc).mean() + F.relu(tc - wt).mean()\n\n\n# --------------------------------------------------------------------------- #\n# Boundary term\n# --------------------------------------------------------------------------- #\ndef _boundary_band(target: torch.Tensor, width: int = 3) -> torch.Tensor:\n    """Dilation minus erosion of the target: a cheap boundary band.\n\n    This is the low-cost implementation of the two the plan screens; the signed\n    distance map variant is the alternative, retained only if it clearly\n    improves NSD/HD95 (A13 decides).\n    """\n    pad = width // 2\n    dil = F.max_pool2d(target, width, stride=1, padding=pad)\n    ero = -F.max_pool2d(-target, width, stride=1, padding=pad)\n    return (dil - ero).clamp(0, 1)\n\n\ndef boundary_loss(\n    logits: torch.Tensor, target: torch.Tensor, width: int = 3\n) -> torch.Tensor:\n    """Weighted BCE restricted to the boundary band of the reference.\n\n    Returns 0 for a batch with no boundary voxels (e.g. all-empty ET), rather\n    than a NaN.\n    """\n    band = _boundary_band(target, width)\n    total = band.sum()\n    if total < 1:\n        return logits.float().sum() * 0.0\n    per_voxel = F.binary_cross_entropy_with_logits(logits, target, reduction="none")\n    return (per_voxel * band).sum() / total\n\n\n# --------------------------------------------------------------------------- #\n# Subset consistency with an EMA full-modality teacher\n# --------------------------------------------------------------------------- #\ndef consistency_loss(\n    student_logits: torch.Tensor,\n    teacher_logits: torch.Tensor,\n    confidence_threshold: float = 0.90,\n    symmetric: bool = False,\n) -> torch.Tensor:\n    """Match the student\'s subset prediction to the teacher\'s full-modality one,\n    only where the teacher is confident (plan 8.2).\n\n    Confidence masking is what stops the teacher from teaching its own errors\n    near uncertain reference boundaries.\n    """\n    with torch.no_grad():\n        t = torch.sigmoid(teacher_logits.float())\n        if symmetric:\n            mask = torch.ones_like(t)\n        else:\n            conf = torch.maximum(t, 1 - t)\n            mask = (conf >= confidence_threshold).to(t.dtype)\n    s = torch.sigmoid(student_logits.float())\n    per_voxel = (s - t) ** 2\n    denom = mask.sum().clamp_min(1.0)\n    return (per_voxel * mask).sum() / denom\n\n\n# --------------------------------------------------------------------------- #\n# Calibration term (optional ablation)\n# --------------------------------------------------------------------------- #\ndef ml1_ace_loss(\n    logits: torch.Tensor, target: torch.Tensor, n_bins: int = 15,\n    soft: bool = True, temperature: float = 0.05,\n) -> torch.Tensor:\n    """Differentiable marginal L1 average calibration error.\n\n    Follows the ACE family (Barfoot et al., MICCAI 2024): probabilities are\n    assigned to equal-width bins and the absolute gap between mean confidence\n    and empirical frequency is averaged over non-empty bins. `soft=True` uses a\n    smooth bin assignment so the term is differentiable; the hard-binned\n    version in metrics.py is what gets *reported*.\n    """\n    probs = torch.sigmoid(logits.float()).reshape(-1)\n    tgt = target.reshape(-1).to(probs.dtype)\n    centers = torch.linspace(\n        1.0 / (2 * n_bins), 1.0 - 1.0 / (2 * n_bins), n_bins,\n        device=probs.device, dtype=probs.dtype,\n    )\n    if soft:\n        w = torch.exp(-((probs[:, None] - centers[None, :]) ** 2) / (2 * temperature ** 2))\n        w = w / w.sum(dim=1, keepdim=True).clamp_min(1e-8)\n    else:\n        idx = torch.clamp((probs * n_bins).long(), 0, n_bins - 1)\n        w = F.one_hot(idx, n_bins).to(probs.dtype)\n    counts = w.sum(dim=0)\n    mean_conf = (w * probs[:, None]).sum(dim=0) / counts.clamp_min(1e-8)\n    mean_acc = (w * tgt[:, None]).sum(dim=0) / counts.clamp_min(1e-8)\n    nonempty = counts > 0\n    if not nonempty.any():\n        return probs.sum() * 0.0\n    return (mean_conf - mean_acc).abs()[nonempty].mean()\n\n\n# --------------------------------------------------------------------------- #\n# Composite\n# --------------------------------------------------------------------------- #\nclass QMMFLoss(nn.Module):\n    """The full objective, returning every component for the loss-balance audit."""\n\n    def __init__(self, cfg: Optional[LossConfig] = None,\n                 region_weights: Optional[Sequence[float]] = None):\n        super().__init__()\n        self.cfg = cfg or LossConfig()\n        rw = torch.tensor(region_weights if region_weights else [1.0, 1.0, 1.0])\n        self.register_buffer("region_weights", rw)\n\n    def forward(\n        self,\n        logits: torch.Tensor,\n        target: torch.Tensor,\n        deep_logits: Optional[List[torch.Tensor]] = None,\n        teacher_logits: Optional[torch.Tensor] = None,\n        use_consistency: bool = True,\n    ) -> Dict[str, torch.Tensor]:\n        c = self.cfg\n        parts: Dict[str, torch.Tensor] = {}\n\n        parts["dice"] = soft_dice_loss(logits, target, weights=self.region_weights)\n        parts["bce"] = bce_loss(logits, target)\n        seg = c.dice * parts["dice"] + c.bce * parts["bce"]\n        parts["seg"] = seg\n\n        total = c.seg * seg\n\n        if c.boundary > 0:\n            parts["boundary"] = boundary_loss(logits, target)\n            total = total + c.boundary * parts["boundary"]\n        if c.nested > 0:\n            parts["nested"] = nested_penalty(logits)\n            total = total + c.nested * parts["nested"]\n        if c.consistency > 0 and teacher_logits is not None and use_consistency:\n            parts["consistency"] = consistency_loss(\n                logits, teacher_logits, c.consistency_conf_threshold\n            )\n            total = total + c.consistency * parts["consistency"]\n        if c.calibration > 0:\n            parts["calibration"] = ml1_ace_loss(logits, target)\n            total = total + c.calibration * parts["calibration"]\n\n        # Deep supervision: reduced-weight segmentation loss on intermediate maps.\n        if deep_logits:\n            ds_total = logits.float().sum() * 0.0\n            for w, dl in zip(c.deep_supervision_weights, deep_logits):\n                small = F.interpolate(target, size=dl.shape[-2:], mode="nearest")\n                ds_total = ds_total + w * (\n                    c.dice * soft_dice_loss(dl, small, weights=self.region_weights)\n                    + c.bce * bce_loss(dl, small)\n                )\n            parts["deep_supervision"] = ds_total\n            total = total + ds_total\n\n        parts["total"] = total\n        return parts\n\n\n# --------------------------------------------------------------------------- #\ndef estimate_region_weights(\n    positive_fractions: Sequence[float], cap: float = 4.0\n) -> torch.Tensor:\n    """Inverse-prevalence region weights, estimated from training data and then\n    fixed for the whole run (plan 8.2). Capped so ET cannot dominate the loss.\n    """\n    f = torch.tensor(list(positive_fractions), dtype=torch.float32).clamp_min(1e-6)\n    w = (1.0 / f)\n    w = w / w.min()\n    return w.clamp(max=cap)\n\n\n@torch.no_grad()\ndef loss_gradient_audit(\n    model: nn.Module, parts: Dict[str, torch.Tensor]\n) -> Dict[str, float]:\n    """Report the magnitude of each loss component so a term that dominates by\n    an order of magnitude is caught rather than silently rescaled."""\n    return {k: float(v.detach()) for k, v in parts.items()}\n', 'segmentation/src/qmmf/manifest.py': '"""Dataset manifest, NIfTI integrity audit and duplicate/overlap detection.\n\nImplements the mandatory audit of plan 5.5 and cells 06-13 of Notebook 01.\nThis module is deliberately independent of torch so the audit can run on a\nCPU-only session.\n"""\n\nfrom __future__ import annotations\n\nimport json\nimport warnings\nfrom dataclasses import dataclass, field\nfrom pathlib import Path\nfrom typing import Any, Dict, Iterable, List, Optional, Sequence, Tuple\n\nimport numpy as np\nimport pandas as pd\n\nfrom .labels import (\n    LabelScheme, LabelSchemeError, infer_label_scheme, label_histogram,\n    region_volumes_ml, to_nested_targets,\n)\nfrom .utils import affine_hash, sha256_array, sha256_file, sha256_obj\n\n\n# --------------------------------------------------------------------------- #\n# Dataset discovery\n# --------------------------------------------------------------------------- #\ndef read_manifest(path: str | Path) -> pd.DataFrame:\n    """Preserve the 512-bit signature as text instead of numeric CSV inference."""\n    return pd.read_csv(path, dtype={"case_id": str, "fingerprint": str})\n\n\ndef load_dataset_json(root: Path) -> Optional[Dict[str, Any]]:\n    for candidate in (root / "dataset.json", root / "Task01_BrainTumour" / "dataset.json"):\n        if candidate.exists():\n            return json.loads(candidate.read_text())\n    return None\n\n\ndef discover_cases(root: Path) -> List[Dict[str, str]]:\n    """Pair every labelled image with its mask.\n\n    MSD Task01 stores 4-channel images in imagesTr and integer masks in\n    labelsTr under the same file name. Files beginning with \'.\' are macOS\n    resource forks in some mirrors and are skipped.\n    """\n    root = Path(root)\n    images_dir = next(\n        (p for p in (root / "imagesTr", root / "Task01_BrainTumour" / "imagesTr")\n         if p.is_dir()), None,\n    )\n    labels_dir = next(\n        (p for p in (root / "labelsTr", root / "Task01_BrainTumour" / "labelsTr")\n         if p.is_dir()), None,\n    )\n    if images_dir is None or labels_dir is None:\n        raise FileNotFoundError(f"imagesTr/labelsTr not found under {root}")\n\n    cases = []\n    for img in sorted(images_dir.glob("*.nii*")):\n        if img.name.startswith("."):\n            continue\n        lbl = labels_dir / img.name\n        if not lbl.exists():\n            warnings.warn(f"No label for {img.name}; excluded from the labelled cohort.")\n            continue\n        cases.append({\n            "case_id": img.name.split(".")[0],\n            "image_path": str(img),\n            "label_path": str(lbl),\n        })\n    if not cases:\n        raise FileNotFoundError(f"No image/label pairs discovered under {root}")\n    return cases\n\n\n# --------------------------------------------------------------------------- #\n# Per-case audit\n# --------------------------------------------------------------------------- #\n@dataclass\nclass CaseAudit:\n    case_id: str\n    image_path: str\n    label_path: str\n    ok: bool = True\n    problems: List[str] = field(default_factory=list)\n    record: Dict[str, Any] = field(default_factory=dict)\n\n    def fail(self, message: str) -> None:\n        self.ok = False\n        self.problems.append(message)\n\n\ndef audit_case(\n    case: Dict[str, str],\n    scheme: LabelScheme,\n    n_modalities: int = 4,\n    compute_hashes: bool = True,\n    intensity_stats: bool = True,\n) -> CaseAudit:\n    """Read one case and record geometry, intensity, label and hash evidence."""\n    import nibabel as nib\n\n    out = CaseAudit(case["case_id"], case["image_path"], case["label_path"])\n    rec: Dict[str, Any] = {\n        "case_id": case["case_id"],\n        "image_path": case["image_path"],\n        "label_path": case["label_path"],\n    }\n    try:\n        img = nib.load(case["image_path"])\n        lbl = nib.load(case["label_path"])\n    except Exception as exc:  # noqa: BLE001 - a corrupt archive must be reported\n        out.fail(f"unreadable: {exc}")\n        out.record = rec\n        return out\n\n    img_data = np.asanyarray(img.dataobj)\n    lbl_data = np.asanyarray(lbl.dataobj)\n\n    rec["image_shape"] = tuple(int(s) for s in img_data.shape)\n    rec["label_shape"] = tuple(int(s) for s in lbl_data.shape)\n    rec["zooms"] = tuple(float(z) for z in img.header.get_zooms()[:3])\n    rec["orientation"] = "".join(nib.aff2axcodes(img.affine))\n    rec["label_orientation"] = "".join(nib.aff2axcodes(lbl.affine))\n    rec["affine_hash"] = affine_hash(img.affine)\n    rec["label_affine_hash"] = affine_hash(lbl.affine)\n    rec["dtype"] = str(img_data.dtype)\n    rec["file_bytes"] = int(Path(case["image_path"]).stat().st_size)\n\n    # Geometry agreement between image and mask.\n    if img_data.ndim != 4:\n        out.fail(f"image is {img_data.ndim}D, expected 4D (H,W,D,M)")\n    elif img_data.shape[-1] != n_modalities:\n        out.fail(f"{img_data.shape[-1]} channels, expected {n_modalities}")\n    if img_data.ndim == 4 and img_data.shape[:3] != lbl_data.shape:\n        out.fail(f"image {img_data.shape[:3]} vs label {lbl_data.shape} shape mismatch")\n    if rec["orientation"] != rec["label_orientation"]:\n        out.fail(\n            f"orientation mismatch image {rec[\'orientation\']} vs "\n            f"label {rec[\'label_orientation\']}"\n        )\n    if not np.allclose(img.affine, lbl.affine, atol=1e-3):\n        out.fail("image and label affines differ beyond tolerance")\n\n    # Intensity sanity per modality.\n    if img_data.ndim == 4 and intensity_stats:\n        for m in range(img_data.shape[-1]):\n            vol = np.asarray(img_data[..., m], dtype=np.float32)\n            finite = np.isfinite(vol)\n            if not finite.all():\n                out.fail(f"modality {m} contains NaN/Inf")\n            nz = vol[finite & (vol != 0)]\n            rec[f"m{m}_nonzero_frac"] = float(nz.size / max(vol.size, 1))\n            if nz.size == 0:\n                out.fail(f"modality {m} is all zero")\n                continue\n            rec[f"m{m}_mean"] = float(nz.mean())\n            rec[f"m{m}_std"] = float(nz.std())\n            rec[f"m{m}_p05"] = float(np.percentile(nz, 5))\n            rec[f"m{m}_p95"] = float(np.percentile(nz, 95))\n\n    # Labels and nested targets.\n    hist = label_histogram(lbl_data)\n    rec["label_histogram"] = hist\n    declared = set(scheme.component_labels().values())\n    unexpected = set(hist) - declared\n    if unexpected:\n        out.fail(f"labels {sorted(unexpected)} outside declared scheme {sorted(declared)}")\n    else:\n        try:\n            targets = to_nested_targets(lbl_data, scheme)\n        except LabelSchemeError as exc:\n            out.fail(str(exc))\n        else:\n            vols = region_volumes_ml(targets, rec["zooms"])\n            rec["wt_volume_ml"] = vols["wt"]\n            rec["tc_volume_ml"] = vols["tc"]\n            rec["et_volume_ml"] = vols["et"]\n            rec["et_present"] = int(targets[2].sum() > 0)\n            rec["et_voxels"] = int(targets[2].sum())\n            rec["brain_support_frac"] = float(\n                (np.asarray(img_data, dtype=np.float32).sum(axis=-1) != 0).mean()\n            ) if img_data.ndim == 4 else float("nan")\n\n    if compute_hashes:\n        rec["file_sha256"] = sha256_file(case["image_path"])\n        rec["label_file_sha256"] = sha256_file(case["label_path"])\n        rec["array_sha256"] = sha256_array(np.asarray(img_data))\n        rec["label_array_sha256"] = sha256_array(np.asarray(lbl_data))\n        rec["fingerprint"] = perceptual_fingerprint(img_data)\n\n    rec["audit_ok"] = out.ok\n    rec["audit_problems"] = "; ".join(out.problems)\n    out.record = rec\n    return out\n\n\ndef perceptual_fingerprint(volume: np.ndarray, grid: int = 8) -> str:\n    """Coarse downsampled signature for *near*-duplicate detection.\n\n    Exact duplicates are caught by array_sha256; this catches re-encodings and\n    resamples of the same patient across the adult and pediatric sources.\n    """\n    vol = np.asarray(volume, dtype=np.float32)\n    if vol.ndim == 4:\n        vol = vol.mean(axis=-1)\n    nz = vol[vol != 0]\n    if nz.size == 0:\n        return "empty"\n    vol = (vol - nz.mean()) / (nz.std() + 1e-6)\n    factors = [max(1, s // grid) for s in vol.shape]\n    trimmed = vol[: factors[0] * grid, : factors[1] * grid, : factors[2] * grid]\n    small = trimmed.reshape(\n        grid, factors[0], grid, factors[1], grid, factors[2]\n    ).mean(axis=(1, 3, 5))\n    bits = (small > np.median(small)).astype(np.uint8).ravel()\n    return "".join(str(int(b)) for b in bits)\n\n\n# --------------------------------------------------------------------------- #\n# Cohort-level manifest\n# --------------------------------------------------------------------------- #\ndef build_manifest(\n    root: Path,\n    scheme: Optional[LabelScheme] = None,\n    limit: Optional[int] = None,\n    compute_hashes: bool = True,\n    progress: bool = True,\n    workers: int = 1,\n) -> Tuple[pd.DataFrame, Dict[str, Any]]:\n    """Audit every labelled case and return (manifest, report).\n\n    The report carries the pass/fail gate that Notebook 02 refuses to train\n    without.\n    """\n    root = Path(root)\n    dataset_json = load_dataset_json(root)\n    cases = discover_cases(root)\n    if limit:\n        cases = cases[:limit]\n\n    if scheme is None:\n        observed: set = set()\n        import nibabel as nib\n        for case in cases[: min(20, len(cases))]:\n            observed |= set(np.unique(np.asanyarray(nib.load(case["label_path"]).dataobj)).astype(int).tolist())\n        scheme = infer_label_scheme(dataset_json, observed)\n\n    from concurrent.futures import ThreadPoolExecutor\n    records, problems = [], []\n    with ThreadPoolExecutor(max_workers=max(1, workers)) as pool:\n        audits = pool.map(lambda c: audit_case(c, scheme, compute_hashes=compute_hashes), cases)\n        for i, audit in enumerate(audits):\n            records.append(audit.record)\n            if not audit.ok:\n                problems.append({"case_id": audit.case_id, "problems": audit.problems})\n            if progress and (i + 1) % 25 == 0:\n                print(f"  audited {i + 1}/{len(cases)} cases", flush=True)\n\n    manifest = pd.DataFrame.from_records(records)\n    dup = duplicate_audit(manifest)\n    report = {\n        "root": str(root),\n        "n_cases": int(len(manifest)),\n        "label_scheme": scheme.name,\n        "label_scheme_mapping": scheme.component_labels(),\n        "dataset_json_present": dataset_json is not None,\n        "modality_order_source": (\n            dataset_json.get("modality") if dataset_json else "unverified"\n        ),\n        "n_failed_cases": len(problems),\n        "failed_cases": problems,\n        "duplicates": dup,\n        "geometry": geometry_summary(manifest),\n        "manifest_hash": manifest_hash(manifest),\n    }\n    report["gate_pass"] = bool(\n        report["n_failed_cases"] == 0\n        and not dup["exact_duplicate_groups"]\n        and report["n_cases"] > 0\n    )\n    return manifest, report\n\n\ndef geometry_summary(manifest: pd.DataFrame) -> Dict[str, Any]:\n    if "image_shape" not in manifest:\n        return {}\n    shapes = manifest["image_shape"].astype(str).value_counts().to_dict()\n    zooms = manifest["zooms"].astype(str).value_counts().to_dict()\n    orients = manifest.get("orientation", pd.Series(dtype=str)).value_counts().to_dict()\n    return {\n        "distinct_shapes": shapes,\n        "distinct_spacings": zooms,\n        "distinct_orientations": orients,\n        "spacing_is_uniform": len(zooms) == 1,\n    }\n\n\ndef duplicate_audit(\n    manifest: pd.DataFrame, fingerprint_threshold: int = 4\n) -> Dict[str, Any]:\n    """Exact and near-duplicate detection (plan 5.5).\n\n    Near-duplicate pairs are *flagged for manual review*, not auto-removed;\n    the Hamming threshold is a screening heuristic, not a proof of identity.\n    """\n    out: Dict[str, Any] = {"exact_duplicate_groups": [], "near_duplicate_pairs": []}\n    if "array_sha256" in manifest:\n        groups = manifest.groupby("array_sha256")["case_id"].apply(list)\n        out["exact_duplicate_groups"] = [g for g in groups if len(g) > 1]\n    if "fingerprint" in manifest:\n        fps = manifest[["case_id", "fingerprint"]].dropna()\n        codes = {\n            r.case_id: np.frombuffer(r.fingerprint.encode(), dtype=np.uint8) - ord("0")\n            for r in fps.itertuples() if r.fingerprint != "empty"\n        }\n        ids = sorted(codes)\n        for i, a in enumerate(ids):\n            for b in ids[i + 1:]:\n                if codes[a].shape != codes[b].shape:\n                    continue\n                dist = int(np.sum(codes[a] != codes[b]))\n                if dist <= fingerprint_threshold:\n                    out["near_duplicate_pairs"].append(\n                        {"a": a, "b": b, "hamming": dist}\n                    )\n    return out\n\n\ndef cross_source_overlap(\n    adult: pd.DataFrame, pediatric: pd.DataFrame, threshold: int = 4\n) -> List[Dict[str, Any]]:\n    """Screen for the same patient appearing in both cohorts (plan 5.5)."""\n    hits: List[Dict[str, Any]] = []\n    if "array_sha256" in adult and "array_sha256" in pediatric:\n        shared = set(adult["array_sha256"]) & set(pediatric["array_sha256"])\n        for h in shared:\n            hits.append({\n                "kind": "exact",\n                "adult": adult.loc[adult.array_sha256 == h, "case_id"].tolist(),\n                "pediatric": pediatric.loc[pediatric.array_sha256 == h, "case_id"].tolist(),\n            })\n    if "fingerprint" in adult and "fingerprint" in pediatric:\n        for ra in adult.itertuples():\n            fa = getattr(ra, "fingerprint", None)\n            if not fa or fa == "empty":\n                continue\n            va = np.frombuffer(fa.encode(), dtype=np.uint8)\n            for rp in pediatric.itertuples():\n                fp = getattr(rp, "fingerprint", None)\n                if not fp or fp == "empty" or len(fp) != len(fa):\n                    continue\n                vp = np.frombuffer(fp.encode(), dtype=np.uint8)\n                dist = int(np.sum(va != vp))\n                if dist <= threshold:\n                    hits.append({\n                        "kind": "near", "adult": ra.case_id,\n                        "pediatric": rp.case_id, "hamming": dist,\n                    })\n    return hits\n\n\ndef manifest_hash(manifest: pd.DataFrame) -> str:\n    cols = [c for c in ("case_id", "array_sha256", "label_array_sha256")\n            if c in manifest.columns]\n    if not cols:\n        cols = ["case_id"]\n    payload = manifest[cols].sort_values("case_id").to_dict(orient="records")\n    return sha256_obj(payload)[:16]\n', 'segmentation/src/qmmf/metrics.py': '"""Patient-level segmentation metrics (plan 10.1).\n\nRules that the plan makes non-negotiable and that are enforced here:\n  * every metric is computed per patient on the reconstructed 3D volume, then\n    summarised across patients - never pooled over slices;\n  * empty-reference cases (typically ET) are handled by an explicit,\n    pre-specified rule and reported separately, never silently counted as\n    Dice 1.0 or dropped;\n  * surface metrics use physical spacing in millimetres.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom typing import Dict, List, Optional, Sequence, Tuple\n\nimport numpy as np\nfrom scipy import ndimage\n\nREGIONS = ("wt", "tc", "et")\n\n# Pre-specified empty-reference rule (plan 10.1 "Empty-region rule").\n#   both empty        -> Dice 1.0, but flagged and reported in its own column\n#   reference empty,\n#   prediction non-empty -> Dice 0.0, and counted as a false-positive case\nEMPTY_BOTH_DICE = 1.0\nEMPTY_REF_FP_DICE = 0.0\n\n\n@dataclass\nclass CaseMetrics:\n    case_id: str\n    region: str\n    dice: float\n    hd95: float\n    nsd: float\n    volume_pred_ml: float\n    volume_ref_ml: float\n    volume_error_ml: float\n    relative_volume_error: float\n    reference_empty: bool\n    prediction_empty: bool\n    lesion_recall: float = float("nan")\n    lesion_precision: float = float("nan")\n    lesion_f1: float = float("nan")\n\n\n# --------------------------------------------------------------------------- #\ndef dice_score(pred: np.ndarray, ref: np.ndarray) -> Tuple[float, bool, bool]:\n    p = np.asarray(pred, dtype=bool)\n    r = np.asarray(ref, dtype=bool)\n    p_empty, r_empty = not p.any(), not r.any()\n    if r_empty and p_empty:\n        return EMPTY_BOTH_DICE, r_empty, p_empty\n    if r_empty and not p_empty:\n        return EMPTY_REF_FP_DICE, r_empty, p_empty\n    if p_empty and not r_empty:\n        return 0.0, r_empty, p_empty\n    inter = np.logical_and(p, r).sum()\n    return float(2 * inter / (p.sum() + r.sum())), r_empty, p_empty\n\n\ndef _surface_distances(\n    pred: np.ndarray, ref: np.ndarray, spacing: Sequence[float]\n) -> Tuple[np.ndarray, np.ndarray]:\n    """Distances from each predicted surface voxel to the reference surface and\n    vice versa, in millimetres."""\n    p = np.asarray(pred, dtype=bool)\n    r = np.asarray(ref, dtype=bool)\n    if not p.any() or not r.any():\n        return np.array([]), np.array([])\n\n    def surface(mask):\n        eroded = ndimage.binary_erosion(mask, iterations=1, border_value=0)\n        return mask & ~eroded\n\n    sp, sr = surface(p), surface(r)\n    dt_to_ref = ndimage.distance_transform_edt(~sr, sampling=spacing)\n    dt_to_pred = ndimage.distance_transform_edt(~sp, sampling=spacing)\n    return dt_to_ref[sp], dt_to_pred[sr]\n\n\ndef hausdorff95(pred, ref, spacing) -> float:\n    d_pr, d_rp = _surface_distances(pred, ref, spacing)\n    if d_pr.size == 0 or d_rp.size == 0:\n        return float("nan")\n    return float(max(np.percentile(d_pr, 95), np.percentile(d_rp, 95)))\n\n\ndef normalized_surface_dice(pred, ref, spacing, tolerance_mm: float = 1.0) -> float:\n    """Fraction of surface within `tolerance_mm` of the other surface."""\n    d_pr, d_rp = _surface_distances(pred, ref, spacing)\n    if d_pr.size == 0 or d_rp.size == 0:\n        return float("nan")\n    num = (d_pr <= tolerance_mm).sum() + (d_rp <= tolerance_mm).sum()\n    return float(num / (d_pr.size + d_rp.size))\n\n\ndef lesion_wise_scores(\n    pred: np.ndarray, ref: np.ndarray, min_voxels: int = 50,\n    overlap_threshold: float = 0.1,\n) -> Dict[str, float]:\n    """Connected-component detection scores.\n\n    A reference lesion counts as detected when a predicted component overlaps\n    at least `overlap_threshold` of it. Components smaller than `min_voxels` are\n    ignored on both sides, which is stated rather than tuned per result.\n    """\n    p_lab, p_n = ndimage.label(np.asarray(pred, dtype=bool))\n    r_lab, r_n = ndimage.label(np.asarray(ref, dtype=bool))\n    p_ids = [i for i in range(1, p_n + 1) if (p_lab == i).sum() >= min_voxels]\n    r_ids = [i for i in range(1, r_n + 1) if (r_lab == i).sum() >= min_voxels]\n    if not r_ids and not p_ids:\n        return {"recall": float("nan"), "precision": float("nan"), "f1": float("nan")}\n    tp_ref = 0\n    for ri in r_ids:\n        rmask = r_lab == ri\n        overlap = np.logical_and(rmask, p_lab > 0).sum() / rmask.sum()\n        tp_ref += int(overlap >= overlap_threshold)\n    tp_pred = 0\n    for pi in p_ids:\n        pmask = p_lab == pi\n        overlap = np.logical_and(pmask, r_lab > 0).sum() / pmask.sum()\n        tp_pred += int(overlap >= overlap_threshold)\n    recall = tp_ref / len(r_ids) if r_ids else float("nan")\n    precision = tp_pred / len(p_ids) if p_ids else float("nan")\n    if np.isnan(recall) or np.isnan(precision) or (recall + precision) == 0:\n        f1 = float("nan") if (np.isnan(recall) or np.isnan(precision)) else 0.0\n    else:\n        f1 = 2 * recall * precision / (recall + precision)\n    return {"recall": float(recall), "precision": float(precision), "f1": float(f1)}\n\n\n# --------------------------------------------------------------------------- #\ndef evaluate_case(\n    pred: np.ndarray,             # [3, H, W, D] binary\n    ref: np.ndarray,              # [3, H, W, D] binary\n    spacing: Sequence[float],\n    case_id: str = "",\n    nsd_tolerance_mm: float = 1.0,\n    lesion_metrics: bool = True,\n    surface_metrics: bool = True,\n) -> List[CaseMetrics]:\n    """All metrics for one patient, one row per nested region."""\n    voxel_ml = float(np.prod(np.asarray(spacing, dtype=np.float64))) / 1000.0\n    rows: List[CaseMetrics] = []\n    for i, region in enumerate(REGIONS):\n        p, r = np.asarray(pred[i], dtype=bool), np.asarray(ref[i], dtype=bool)\n        d, r_empty, p_empty = dice_score(p, r)\n        vp, vr = float(p.sum()) * voxel_ml, float(r.sum()) * voxel_ml\n        rel = (vp - vr) / vr if vr > 0 else float("nan")\n        hd, nsd = float("nan"), float("nan")\n        if surface_metrics:\n            dp, dr = _surface_distances(p, r, spacing)\n            if dp.size and dr.size:\n                hd = float(max(np.percentile(dp, 95), np.percentile(dr, 95)))\n                nsd = float(((dp <= nsd_tolerance_mm).sum() + (dr <= nsd_tolerance_mm).sum()) / (dp.size + dr.size))\n        row = CaseMetrics(\n            case_id=case_id, region=region, dice=d,\n            hd95=hd,\n            nsd=nsd,\n            volume_pred_ml=vp, volume_ref_ml=vr,\n            volume_error_ml=vp - vr, relative_volume_error=rel,\n            reference_empty=r_empty, prediction_empty=p_empty,\n        )\n        if lesion_metrics:\n            ls = lesion_wise_scores(p, r)\n            row.lesion_recall = ls["recall"]\n            row.lesion_precision = ls["precision"]\n            row.lesion_f1 = ls["f1"]\n        rows.append(row)\n    return rows\n\n\ndef macro_dice(rows: Sequence[CaseMetrics], exclude_empty_reference: bool = True\n               ) -> float:\n    """Macro Dice over WT/TC/ET for one patient.\n\n    With exclude_empty_reference=True (the pre-specified primary rule), a region\n    whose reference is empty does not contribute, so the headline number is not\n    inflated by free 1.0 scores.\n    """\n    vals = [\n        r.dice for r in rows\n        if not (exclude_empty_reference and r.reference_empty)\n    ]\n    return float(np.mean(vals)) if vals else float("nan")\n\n\ndef summarize(\n    rows: Sequence[CaseMetrics], exclude_empty_reference: bool = True\n) -> Dict[str, float]:\n    """Cohort summary: per-region means plus the empty-reference bookkeeping."""\n    import pandas as pd\n    df = pd.DataFrame([r.__dict__ for r in rows])\n    out: Dict[str, float] = {}\n    for region in REGIONS:\n        sub = df[df.region == region]\n        counted = sub[~sub.reference_empty] if exclude_empty_reference else sub\n        out[f"dice_{region}"] = float(counted.dice.mean()) if len(counted) else float("nan")\n        out[f"hd95_{region}"] = float(counted.hd95.dropna().mean()) if len(counted) else float("nan")\n        out[f"nsd_{region}"] = float(counted.nsd.dropna().mean()) if len(counted) else float("nan")\n        out[f"rve_{region}"] = float(counted.relative_volume_error.dropna().mean()) if len(counted) else float("nan")\n        out[f"n_empty_reference_{region}"] = int(sub.reference_empty.sum())\n        out[f"n_evaluable_dice_{region}"] = int(len(counted))\n        out[f"n_undefined_hd95_{region}"] = int(counted.hd95.isna().sum())\n        out[f"n_empty_prediction_{region}"] = int(sub.prediction_empty.sum())\n        out[f"n_empty_ref_false_positive_{region}"] = int(\n            (sub.reference_empty & ~sub.prediction_empty).sum()\n        )\n    out["macro_dice"] = float(np.nanmean(list(per_case_macro(rows).values())))\n    return out\n\n\ndef per_case_macro(rows: Sequence[CaseMetrics]) -> Dict[str, float]:\n    """case_id -> macro Dice, the unit of every paired statistical test."""\n    by_case: Dict[str, List[CaseMetrics]] = {}\n    for r in rows:\n        by_case.setdefault(r.case_id, []).append(r)\n    return {cid: macro_dice(rs) for cid, rs in by_case.items()}\n', 'segmentation/src/qmmf/models/__init__.py': '"""Model registry and the A0-A17 ablation table (plan 9.3).\n\nEach ablation is expressed as a set of dotted config overrides plus, where\nneeded, a different fusion module. Nothing is hard-coded inside the network:\nan ablation that cannot be expressed as a config change is a design smell.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom typing import Any, Callable, Dict, List, Optional, Sequence\n\nfrom ..config import ExperimentConfig, ModelConfig\nfrom .baselines import (\n    HeMIS25D, SegResNet3DWrapper, SwinUNETRWrapper, UNet2D, UNet25D,\n)\nfrom .qmmf_net import QMMFNet, project_nested, project_nested_numpy\n\nMODEL_REGISTRY: Dict[str, Callable] = {\n    "qmmf_net": QMMFNet,\n    "unet2d": UNet2D,          # B1\n    "unet25d": UNet25D,        # B2\n    "hemis25d": HeMIS25D,      # B3\n    "segresnet3d": SegResNet3DWrapper,   # B4\n    "swinunetr": SwinUNETRWrapper,       # B6, optional\n}\n\nBASELINE_IDS = {\n    "B1": "unet2d", "B2": "unet25d", "B3": "hemis25d",\n    "B4": "segresnet3d", "B5": "qmmf_net", "B6": "swinunetr",\n}\n\n\n@dataclass(frozen=True)\nclass Ablation:\n    ident: str\n    description: str\n    question: str\n    overrides: Dict[str, Any]\n    fusion_kind: str = "qmmf"\n    data_overrides: Dict[str, Any] = None            # type: ignore[assignment]\n    loss_overrides: Dict[str, Any] = None            # type: ignore[assignment]\n    train_overrides: Dict[str, Any] = None           # type: ignore[assignment]\n\n    def apply(self, cfg: ExperimentConfig) -> ExperimentConfig:\n        merged: Dict[str, Any] = {}\n        for prefix, table in (\n            ("net", self.overrides), ("data", self.data_overrides),\n            ("loss", self.loss_overrides), ("train", self.train_overrides),\n        ):\n            for key, value in (table or {}).items():\n                merged[f"{prefix}.{key}"] = value\n        merged["ablation"] = self.ident\n        return cfg.merged(merged)\n\n\nABLATIONS: Dict[str, Ablation] = {a.ident: a for a in [\n    Ablation("A0", "Full QMMF-Net", "Reference", {}),\n    Ablation("A1", "Early channel concatenation",\n             "Does the entire modality-aware design matter?",\n             {}, fusion_kind="concat"),\n    Ablation("A2", "Equal masked mean only", "Do the weighted moments matter?",\n             {}, fusion_kind="equal_mean"),\n    Ablation("A3", "HeMIS equal masked mean + variance", "Foundational baseline",\n             {}, fusion_kind="equal_mean_var"),\n    Ablation("A4", "Availability-only gate",\n             "Separates quality conditioning from dynamic availability",\n             {"use_quality": False, "use_availability_gate": False}),\n    Ablation("A5", "Remove quality vector", "Direct quality contribution",\n             {"use_quality": False}),\n    Ablation("A6", "Remove weighted variance",\n             "Disagreement / complementarity contribution",\n             {"moment_fusion": ["mean", "max"]}),\n    Ablation("A7", "Remove max-available branch",\n             "Localised strong-evidence contribution",\n             {"moment_fusion": ["mean", "variance"]}),\n    Ablation("A8", "Remove axial/large-kernel context", "Context mixer contribution",\n             {"context_block": "none"}),\n    Ablation("A9", "Kernel 3 vs kernel 7", "Receptive-field trade-off",\n             {"context_block": "kernel3"}),\n    Ablation("A10", "Remove subset consistency",\n             "Robustness and label-efficiency contribution",\n             {}, loss_overrides={"consistency": 0.0}),\n    Ablation("A11", "Uniform modality sampling from epoch 1",\n             "Curriculum contribution",\n             {}, train_overrides={"modality_curriculum": "uniform"}),\n    Ablation("A12", "Remove nesting loss", "Anatomical consistency contribution",\n             {}, loss_overrides={"nested": 0.0}),\n    Ablation("A13", "Remove boundary loss", "Surface-metric contribution",\n             {}, loss_overrides={"boundary": 0.0}),\n    Ablation("A14", "D = 1 / 3 / 5 / 7 slices", "2D-to-2.5D context trade-off",\n             {}, data_overrides={"context_slices": 3}),\n    Ablation("A15", "Remove modality embedding / FiLM",\n             "Identity-conditioning contribution", {"use_film": False}),\n    # Widths chosen by parameter_matched_widths() so that A16 sits within ~1%\n    # of QMMF-Net\'s parameter count at the default widths. Re-derive and update\n    # this list whenever the default widths change; the matching is asserted in\n    # tests/test_model.py rather than assumed.\n    Ablation("A16", "Parameter-matched widened HeMIS / simple fusion",\n             "Controls for capacity",\n             {"widths": [24, 48, 98, 164]}, fusion_kind="equal_mean_var"),\n    Ablation("A17", "Shuffle quality vectors across patients",\n             "Negative control for spurious quality conditioning", {}),\n]}\n\n# A17 is a data-side control: the flag is read by SliceDataset, not the network.\nDATASET_FLAG_ABLATIONS = {"A17": {"shuffle_quality": True},\n                          "A5": {"zero_quality": True}}\n\n# A14 sweeps several depths; the config generator expands them.\nA14_VARIANTS = (1, 3, 5, 7)\n\n\ndef build_model(cfg: ExperimentConfig):\n    """Instantiate the model named by cfg.model with the ablation applied."""\n    name = cfg.model\n    if name not in MODEL_REGISTRY:\n        raise KeyError(f"Unknown model \'{name}\'. Have {sorted(MODEL_REGISTRY)}.")\n    ablation = ABLATIONS.get(cfg.ablation)\n    fusion_kind = ablation.fusion_kind if ablation else "qmmf"\n    kwargs = dict(\n        cfg=cfg.net,\n        n_modalities=len(cfg.data.modalities),\n        context_slices=cfg.data.context_slices,\n        n_outputs=len(cfg.data.outputs),\n    )\n    if name == "qmmf_net":\n        kwargs["fusion_kind"] = fusion_kind\n    return MODEL_REGISTRY[name](**kwargs)\n\n\ndef parameter_matched_widths(\n    cfg: ExperimentConfig,\n    fusion_kind: str,\n    base_widths=(24, 48, 96, 160),\n    tolerance: float = 0.05,\n    max_scale: float = 1.6,\n) -> Dict[str, Any]:\n    """Find widths that give `fusion_kind` the same parameter count as QMMF-Net.\n\n    Plan 9.2 requires a parameter-matched control: a simpler fusion must not be\n    allowed to look worse merely because it is smaller. This searches a scale\n    factor over the base widths and returns the closest match, so the A16 entry\n    above is derived rather than guessed.\n    """\n    from ..utils import count_parameters\n    from .qmmf_net import QMMFNet\n\n    reference = count_parameters(build_model(cfg))["total"]\n    best: Optional[Dict[str, Any]] = None\n    scale = 1.0\n    while scale <= max_scale:\n        widths = [int(round(w * scale / 2)) * 2 for w in base_widths]\n        model = QMMFNet(\n            cfg.merged({"net.widths": widths}).net,\n            n_modalities=len(cfg.data.modalities),\n            context_slices=cfg.data.context_slices,\n            n_outputs=len(cfg.data.outputs),\n            fusion_kind=fusion_kind,\n        )\n        total = count_parameters(model)["total"]\n        ratio = total / reference\n        if best is None or abs(ratio - 1) < abs(best["ratio"] - 1):\n            best = {"widths": widths, "parameters": total, "ratio": ratio,\n                    "reference_parameters": reference}\n        scale += 0.005\n    assert best is not None\n    best["within_tolerance"] = abs(best["ratio"] - 1) <= tolerance\n    return best\n\n\n__all__ = [\n    "MODEL_REGISTRY", "BASELINE_IDS", "ABLATIONS", "Ablation", "build_model",\n    "parameter_matched_widths",\n    "QMMFNet", "UNet2D", "UNet25D", "HeMIS25D", "SegResNet3DWrapper",\n    "SwinUNETRWrapper", "project_nested", "project_nested_numpy",\n    "DATASET_FLAG_ABLATIONS", "A14_VARIANTS",\n]\n', 'segmentation/src/qmmf/models/baselines.py': '"""Reimplemented baselines B1-B4 (+ optional B6/B7), plan 9.1.\n\nEvery baseline takes the *same* input signature as QMMF-Net\n(image, availability, quality) so that the training loop, augmentation, splits,\nmetric code and modality-subset curriculum are byte-for-byte identical across\nmodels. That is what makes the comparison fair (plan 9.2); differences in\ntuning budget are disclosed rather than hidden.\n"""\n\nfrom __future__ import annotations\n\nfrom typing import Dict, Optional, Sequence\n\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\n\nfrom ..config import ModelConfig\nfrom .blocks import ConvBlock, PseudoConv3DStem, UpBlock, norm_layer\nfrom .qmmf import EqualMaskedMean, masked_feature_max\n\n\nclass _UNet2DCore(nn.Module):\n    """Shared encoder/decoder body so baselines differ only in their input stage."""\n\n    def __init__(self, cin: int, widths: Sequence[int], n_outputs: int = 3):\n        super().__init__()\n        self.widths = tuple(widths)\n        self.inc = ConvBlock(cin, self.widths[0], depth=2)\n        self.pool = nn.AvgPool2d(2)\n        self.encoders = nn.ModuleList([\n            ConvBlock(self.widths[i - 1], self.widths[i], depth=2)\n            for i in range(1, len(self.widths))\n        ])\n        rev = list(reversed(self.widths))\n        self.decoders = nn.ModuleList([\n            UpBlock(rev[i], rev[i + 1], rev[i + 1]) for i in range(len(rev) - 1)\n        ])\n        self.head = nn.Conv2d(self.widths[0], n_outputs, 1)\n\n    def forward(self, x: torch.Tensor) -> torch.Tensor:\n        feats = [self.inc(x)]\n        for enc in self.encoders:\n            feats.append(enc(self.pool(feats[-1])))\n        y = feats[-1]\n        for i, dec in enumerate(self.decoders):\n            y = dec(y, feats[-2 - i])\n        return self.head(y)\n\n\nclass UNet2D(nn.Module):\n    """B1: single central slice, four channels (or the available subset)."""\n\n    def __init__(self, cfg: Optional[ModelConfig] = None, n_modalities: int = 4,\n                 context_slices: int = 5, n_outputs: int = 3):\n        super().__init__()\n        cfg = cfg or ModelConfig()\n        self.center = context_slices // 2\n        self.core = _UNet2DCore(n_modalities, cfg.widths, n_outputs)\n\n    def forward(self, image, availability, quality, return_aux: bool = False):\n        x = image[:, :, self.center] * availability[:, :, None, None]\n        logits = self.core(x)\n        return (logits, {"deep_logits": []}) if return_aux else logits\n\n\nclass UNet25D(nn.Module):\n    """B2: five adjacent slices x four modalities as channels + availability mask.\n\n    The dimensionality-matched control: same 2.5D context as QMMF-Net, but the\n    modality handling is plain channel concatenation.\n    """\n\n    def __init__(self, cfg: Optional[ModelConfig] = None, n_modalities: int = 4,\n                 context_slices: int = 5, n_outputs: int = 3):\n        super().__init__()\n        cfg = cfg or ModelConfig()\n        self.n_modalities = n_modalities\n        self.context_slices = context_slices\n        # +M channels carry the availability mask explicitly, so this baseline\n        # is not handicapped by having to infer which sequences are missing.\n        cin = n_modalities * context_slices + n_modalities\n        self.core = _UNet2DCore(cin, cfg.widths, n_outputs)\n\n    def forward(self, image, availability, quality, return_aux: bool = False):\n        b, m, d, h, w = image.shape\n        x = (image * availability[:, :, None, None, None]).reshape(b, m * d, h, w)\n        mask_planes = availability[:, :, None, None].expand(b, m, h, w)\n        logits = self.core(torch.cat([x, mask_planes], dim=1))\n        return (logits, {"deep_logits": []}) if return_aux else logits\n\n\nclass HeMIS25D(nn.Module):\n    """B3: shared modality stem + equal-weight masked mean and variance.\n\n    The foundational arbitrary-modality baseline (Havaei et al., MICCAI 2016),\n    reimplemented at 2.5D under this study\'s pipeline. Ablation A3 is the same\n    fusion inside QMMF-Net\'s body; this is the standalone architecture.\n    """\n\n    def __init__(self, cfg: Optional[ModelConfig] = None, n_modalities: int = 4,\n                 context_slices: int = 5, n_outputs: int = 3):\n        super().__init__()\n        cfg = cfg or ModelConfig()\n        self.widths = tuple(cfg.widths)\n        self.stem = PseudoConv3DStem(context_slices, self.widths[0],\n                                     cond_dim=cfg.modality_embed_dim, use_film=False)\n        self.fuse = EqualMaskedMean(self.widths[0], with_variance=True)\n        self.core_encoders = nn.ModuleList([\n            ConvBlock(self.widths[i - 1], self.widths[i], depth=2)\n            for i in range(1, len(self.widths))\n        ])\n        self.pool = nn.AvgPool2d(2)\n        rev = list(reversed(self.widths))\n        self.decoders = nn.ModuleList([\n            UpBlock(rev[i], rev[i + 1], rev[i + 1]) for i in range(len(rev) - 1)\n        ])\n        self.head = nn.Conv2d(self.widths[0], n_outputs, 1)\n\n    def forward(self, image, availability, quality, return_aux: bool = False):\n        b, m, d, h, w = image.shape\n        feats = self.stem(image.reshape(b * m, d, h, w), None)\n        feats = feats.reshape(b, m, *feats.shape[1:])\n        x, aux = self.fuse(feats, availability, quality, None)\n        skips = [x]\n        for enc in self.core_encoders:\n            skips.append(enc(self.pool(skips[-1])))\n        y = skips[-1]\n        for i, dec in enumerate(self.decoders):\n            y = dec(y, skips[-2 - i])\n        logits = self.head(y)\n        if return_aux:\n            return logits, {"deep_logits": [], "gate_alpha": aux["alpha"].unsqueeze(1)}\n        return logits\n\n\nclass SegResNet3DWrapper(nn.Module):\n    """B4: small 3D SegResNet (MONAI) on cropped patches.\n\n    Wrapped so it accepts the same call signature. It consumes the 2.5D window\n    as a short 3D volume; the plan treats it as the full-modality volumetric\n    reference, and its comparison is the H1 non-inferiority test.\n\n    Requires MONAI. Raises a clear error rather than silently substituting a\n    different architecture.\n    """\n\n    def __init__(self, cfg: Optional[ModelConfig] = None, n_modalities: int = 4,\n                 context_slices: int = 5, n_outputs: int = 3, init_filters: int = 16):\n        super().__init__()\n        try:\n            from monai.networks.nets import SegResNet\n        except ImportError as exc:  # pragma: no cover - environment dependent\n            raise ImportError(\n                "Baseline B4 needs MONAI: pip install monai. "\n                "Do not substitute another 3D network silently."\n            ) from exc\n        self.n_modalities = n_modalities\n        self.net = SegResNet(\n            spatial_dims=3, init_filters=init_filters,\n            in_channels=n_modalities, out_channels=n_outputs,\n            blocks_down=(1, 2, 2, 4), blocks_up=(1, 1, 1),\n        )\n        self.center = context_slices // 2\n\n    def forward(self, image, availability, quality, return_aux: bool = False):\n        # image [B, M, D, H, W] is already the right layout for a 3D network.\n        x = image * availability[:, :, None, None, None]\n        out = self.net(x)                       # [B, 3, D, H, W]\n        logits = out[:, :, self.center]         # supervise the central slice\n        return (logits, {"deep_logits": []}) if return_aux else logits\n\n\nclass SwinUNETRWrapper(nn.Module):\n    """B6 (optional): tiny SwinUNETR, included only if it clears the pilot gate.\n\n    Plan 11.5: if this OOMs or runs >1.5x QMMF-Net runtime, it is removed from\n    the mandatory comparisons and the feasibility failure is documented rather\n    than hidden.\n    """\n\n    def __init__(self, cfg: Optional[ModelConfig] = None, n_modalities: int = 4,\n                 context_slices: int = 5, n_outputs: int = 3,\n                 img_size=(64, 192, 192), feature_size: int = 24):\n        super().__init__()\n        try:\n            from monai.networks.nets import SwinUNETR\n        except ImportError as exc:  # pragma: no cover\n            raise ImportError("Baseline B6 needs MONAI: pip install monai.") from exc\n        self.net = SwinUNETR(\n            img_size=img_size, in_channels=n_modalities,\n            out_channels=n_outputs, feature_size=feature_size,\n        )\n        self.center = context_slices // 2\n\n    def forward(self, image, availability, quality, return_aux: bool = False):\n        x = image * availability[:, :, None, None, None]\n        logits = self.net(x)[:, :, self.center]\n        return (logits, {"deep_logits": []}) if return_aux else logits\n', 'segmentation/src/qmmf/models/blocks.py': '"""Reusable network blocks: pseudo-3D stem, FiLM, factorized large-kernel context.\n\nNo quadratic self-attention and no custom CUDA kernels anywhere on the\nmandatory path (plan 7.6), so the model trains on a single 16 GB T4.\n"""\n\nfrom __future__ import annotations\n\nfrom typing import Optional, Sequence\n\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\n\n\ndef norm_layer(channels: int, groups: int = 8) -> nn.Module:\n    """GroupNorm: stable at the small per-GPU batches this study uses, and it\n    needs no SyncBatchNorm across the two independent T4 jobs.\n\n    The group count falls back to the largest divisor of `channels` that is at\n    most `groups`, so an arbitrary width (e.g. a parameter-matched ablation)\n    does not crash the model.\n    """\n    g = min(groups, channels)\n    while g > 1 and channels % g != 0:\n        g -= 1\n    return nn.GroupNorm(num_groups=g, num_channels=channels)\n\n\nclass ConvBlock(nn.Module):\n    """Conv -> Norm -> GELU, optionally twice."""\n\n    def __init__(self, cin: int, cout: int, kernel: int = 3, depth: int = 2,\n                 dropout: float = 0.0):\n        super().__init__()\n        layers = []\n        c = cin\n        for _ in range(depth):\n            layers += [\n                nn.Conv2d(c, cout, kernel, padding=kernel // 2, bias=False),\n                norm_layer(cout),\n                nn.GELU(),\n            ]\n            if dropout > 0:\n                layers.append(nn.Dropout2d(dropout))\n            c = cout\n        self.body = nn.Sequential(*layers)\n\n    def forward(self, x: torch.Tensor) -> torch.Tensor:\n        return self.body(x)\n\n\nclass FiLM(nn.Module):\n    """Feature-wise linear modulation from a conditioning vector.\n\n    Used to tell one shared stem which sequence it is looking at (plan 7.2),\n    so the parameter count does not scale with the modality count.\n    """\n\n    def __init__(self, cond_dim: int, channels: int, hidden: int = 32):\n        super().__init__()\n        self.net = nn.Sequential(\n            nn.Linear(cond_dim, hidden), nn.GELU(), nn.Linear(hidden, 2 * channels)\n        )\n        # Start as the identity so an untrained FiLM does not distort the stem.\n        nn.init.zeros_(self.net[-1].weight)\n        nn.init.zeros_(self.net[-1].bias)\n\n    def forward(self, x: torch.Tensor, cond: torch.Tensor) -> torch.Tensor:\n        gamma, beta = self.net(cond).chunk(2, dim=-1)\n        gamma = gamma[..., None, None]\n        beta = beta[..., None, None]\n        return x * (1.0 + gamma) + beta\n\n\nclass PseudoConv3DStem(nn.Module):\n    """Mix the D adjacent slices, then act in-plane.\n\n    The depth mixing is a small factorized convolution over the slice axis\n    (D -> 1), which is cheaper than a full 3D stem and keeps the model 2.5D.\n    Weights are shared across modalities; identity comes from FiLM.\n    """\n\n    def __init__(self, context_slices: int, out_channels: int,\n                 cond_dim: int = 16, use_film: bool = True):\n        super().__init__()\n        self.context_slices = context_slices\n        self.depth_mix = nn.Conv3d(\n            1, out_channels, kernel_size=(context_slices, 3, 3),\n            padding=(0, 1, 1), bias=False,\n        )\n        self.norm = norm_layer(out_channels)\n        self.act = nn.GELU()\n        self.use_film = use_film\n        self.film = FiLM(cond_dim, out_channels) if use_film else None\n        self.refine = ConvBlock(out_channels, out_channels, depth=1)\n\n    def forward(self, x: torch.Tensor, cond: Optional[torch.Tensor] = None\n                ) -> torch.Tensor:\n        """x: [B, D, H, W] for one modality -> [B, C, H, W]."""\n        h = self.depth_mix(x.unsqueeze(1)).squeeze(2)      # [B, C, H, W]\n        h = self.act(self.norm(h))\n        if self.use_film and cond is not None:\n            h = self.film(h, cond)\n        return self.refine(h)\n\n\nclass FactorizedLargeKernelBlock(nn.Module):\n    """Depthwise (1 x k) then (k x 1) large-kernel convolution with a pointwise MLP.\n\n    Gives a wide receptive field with linear cost, which is the cheap stand-in\n    for global attention at the bottleneck (plan 7.6). Ablation A8 removes the\n    block; A9 replaces k=7 with k=3.\n    """\n\n    def __init__(self, channels: int, kernel: int = 7, expansion: int = 2):\n        super().__init__()\n        pad = kernel // 2\n        self.dw_h = nn.Conv2d(channels, channels, (1, kernel), padding=(0, pad),\n                              groups=channels, bias=False)\n        self.dw_v = nn.Conv2d(channels, channels, (kernel, 1), padding=(pad, 0),\n                              groups=channels, bias=False)\n        self.norm = norm_layer(channels)\n        self.mlp = nn.Sequential(\n            nn.Conv2d(channels, channels * expansion, 1), nn.GELU(),\n            nn.Conv2d(channels * expansion, channels, 1),\n        )\n        # Small non-zero LayerScale: zero-init would give the block\'s own\n        # weights exactly zero gradient on the first step.\n        self.gamma = nn.Parameter(torch.full((1, channels, 1, 1), 1e-2))\n\n    def forward(self, x: torch.Tensor) -> torch.Tensor:\n        h = self.dw_v(self.dw_h(x))\n        h = self.mlp(self.norm(h))\n        return x + self.gamma * h\n\n\nclass ContextMixer(nn.Module):\n    """Two to four lightweight large-kernel blocks at the bottleneck."""\n\n    def __init__(self, channels: int, depth: int = 2, kernel: int = 7,\n                 mode: str = "factorized_large_kernel"):\n        super().__init__()\n        if mode == "none":\n            self.body = nn.Identity()\n        elif mode == "kernel3":\n            self.body = nn.Sequential(\n                *[FactorizedLargeKernelBlock(channels, 3) for _ in range(depth)]\n            )\n        elif mode == "factorized_large_kernel":\n            self.body = nn.Sequential(\n                *[FactorizedLargeKernelBlock(channels, kernel) for _ in range(depth)]\n            )\n        else:\n            raise KeyError(f"Unknown context block \'{mode}\'")\n\n    def forward(self, x: torch.Tensor) -> torch.Tensor:\n        return self.body(x)\n\n\nclass UpBlock(nn.Module):\n    """Bilinear upsample + skip concatenation + conv (light U-Net decoder)."""\n\n    def __init__(self, cin: int, cskip: int, cout: int, dropout: float = 0.0):\n        super().__init__()\n        self.reduce = nn.Conv2d(cin, cout, 1, bias=False)\n        self.block = ConvBlock(cout + cskip, cout, depth=2, dropout=dropout)\n\n    def forward(self, x: torch.Tensor, skip: torch.Tensor) -> torch.Tensor:\n        x = F.interpolate(x, size=skip.shape[-2:], mode="bilinear", align_corners=False)\n        x = self.reduce(x)\n        return self.block(torch.cat([x, skip], dim=1))\n', 'segmentation/src/qmmf/models/qmmf.py': '"""Quality-conditioned masked moment fusion (QMMF).\n\nImplements plan 7.4 / Appendix B exactly:\n\n    h_m^s     = [GAP(F_m^s), q_m, e_m]\n    l_m^s     = g_s(h_m^s)\n    alpha_m^s = masked_softmax(l_m^s ; a_m)\n    mu^s      = sum_m alpha_m^s * F_m^s\n    v^s       = sum_m alpha_m^s * (F_m^s - mu^s)^2\n    r^s       = max over available modalities of F_m^s\n    Z^s       = Conv1x1([mu^s, sqrt(v^s + eps), r^s])\n\nTwo properties are guaranteed structurally, not by convention:\n  1. an absent modality contributes nothing - it is excluded from the softmax\n     denominator and from the max branch, so its features cannot leak in;\n  2. the weights sum to one over the *available* modalities only, so the fused\n     statistic keeps the same scale regardless of how many sequences are present.\n"""\n\nfrom __future__ import annotations\n\nfrom typing import Dict, List, Optional, Sequence, Tuple\n\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\n\nNEG_INF = -1e4      # finite so that fp16 autocast stays well-defined\n\n\ndef _gn(channels: int, groups: int = 8) -> nn.GroupNorm:\n    """GroupNorm with a group count that always divides `channels`."""\n    g = min(groups, channels)\n    while g > 1 and channels % g != 0:\n        g -= 1\n    return nn.GroupNorm(g, channels)\n\n\ndef masked_softmax(logits: torch.Tensor, mask: torch.Tensor, dim: int = 1\n                   ) -> torch.Tensor:\n    """Softmax over `dim`, restricted to entries where mask > 0.\n\n    logits: [B, M, ...]; mask: [B, M] broadcast over the trailing dims.\n    Rows with no available entry would be undefined; the caller guarantees\n    sum(mask) >= 1 (see subsets.availability_mask), and this function still\n    returns zeros rather than NaN if that guarantee is ever violated.\n    """\n    while mask.dim() < logits.dim():\n        mask = mask.unsqueeze(-1)\n    mask = mask.to(logits.dtype)\n    logits = logits.float()\n    masked = logits.masked_fill(mask <= 0, NEG_INF)\n    weights = torch.softmax(masked, dim=dim)\n    weights = weights * (mask > 0).to(weights.dtype)\n    total = weights.sum(dim=dim, keepdim=True)\n    return weights / total.clamp_min(1e-8)\n\n\ndef masked_feature_max(\n    features: torch.Tensor, mask: torch.Tensor, dim: int = 1\n) -> torch.Tensor:\n    """Max over available modalities only. features: [B, M, C, H, W]."""\n    while mask.dim() < features.dim():\n        mask = mask.unsqueeze(-1)\n    filled = features.masked_fill(mask <= 0, NEG_INF)\n    out = filled.max(dim=dim).values\n    # If (impossibly) nothing is available, fall back to zeros rather than -inf.\n    any_avail = (mask > 0).any(dim=dim)\n    return torch.where(any_avail.expand_as(out), out, torch.zeros_like(out))\n\n\nclass QMMFBlock(nn.Module):\n    """One fusion block, applied at every encoder scale.\n\n    Args:\n        channels: feature channels C at this scale.\n        quality_dim: length of the per-modality quality vector q_m.\n        embed_dim: length of the learned modality identity embedding e_m.\n        moments: which branches to concatenate before the 1x1 fusion.\n        use_quality: A5 sets False (availability gating only).\n        use_availability_gate: A4 keeps availability but drops learned gating.\n    """\n\n    def __init__(\n        self,\n        channels: int,\n        quality_dim: int = 7,\n        embed_dim: int = 16,\n        hidden: int = 32,\n        moments: Sequence[str] = ("mean", "variance", "max"),\n        use_quality: bool = True,\n        learned_gate: bool = True,\n    ):\n        super().__init__()\n        self.channels = channels\n        self.moments = tuple(moments)\n        self.use_quality = use_quality\n        self.learned_gate = learned_gate\n        for m in self.moments:\n            if m not in ("mean", "variance", "max"):\n                raise KeyError(f"Unknown moment branch \'{m}\'")\n        if "mean" not in self.moments:\n            raise ValueError("The weighted mean branch is required.")\n\n        descriptor_dim = channels + (quality_dim if use_quality else 0) + embed_dim\n        if learned_gate:\n            # No bias on the final layer: the gate logits enter a softmax over\n            # modalities, so a shared additive constant is unidentifiable and\n            # would sit in the model with a permanently zero gradient.\n            self.gate = nn.Sequential(\n                nn.Linear(descriptor_dim, hidden), nn.GELU(),\n                nn.Linear(hidden, 1, bias=False),\n            )\n        else:\n            self.gate = None\n\n        self.fuse = nn.Sequential(\n            nn.Conv2d(channels * len(self.moments), channels, 1, bias=False),\n            _gn(channels),\n            nn.GELU(),\n        )\n\n    # ------------------------------------------------------------------ #\n    def gate_logits(\n        self,\n        features: torch.Tensor,          # [B, M, C, H, W]\n        quality: torch.Tensor,           # [B, M, Q]\n        embedding: torch.Tensor,         # [M, E] or [B, M, E]\n    ) -> torch.Tensor:\n        """Per-modality scalar logit l_m from a pooled descriptor."""\n        b, m = features.shape[0], features.shape[1]\n        if self.gate is None:\n            # A4: availability-only gate = equal weights over available inputs.\n            return torch.zeros(b, m, device=features.device, dtype=features.dtype)\n        gap = features.mean(dim=(-2, -1))                       # [B, M, C]\n        parts = [gap]\n        if self.use_quality:\n            parts.append(quality.to(gap.dtype))\n        emb = embedding if embedding.dim() == 3 else embedding.unsqueeze(0).expand(b, -1, -1)\n        parts.append(emb.to(gap.dtype))\n        descriptor = torch.cat(parts, dim=-1)                   # [B, M, D]\n        return self.gate(descriptor).squeeze(-1)                # [B, M]\n\n    def forward(\n        self,\n        features: torch.Tensor,          # [B, M, C, H, W]\n        availability: torch.Tensor,      # [B, M]\n        quality: torch.Tensor,           # [B, M, Q]\n        embedding: torch.Tensor,         # [M, E]\n    ) -> Tuple[torch.Tensor, Dict[str, torch.Tensor]]:\n        logits = self.gate_logits(features, quality, embedding)\n        alpha = masked_softmax(logits, availability, dim=1)      # [B, M]\n        alpha_map = alpha[..., None, None, None]                 # [B, M, 1, 1, 1]\n\n        features = features.float()  # stable moment reductions under autocast\n        mu = (alpha_map * features).sum(dim=1)                   # [B, C, H, W]\n        branches: List[torch.Tensor] = []\n        for name in self.moments:\n            if name == "mean":\n                branches.append(mu)\n            elif name == "variance":\n                var = (alpha_map * (features - mu.unsqueeze(1)) ** 2).sum(dim=1)\n                branches.append(torch.sqrt(var.clamp_min(0.0) + 1e-6))\n            elif name == "max":\n                branches.append(masked_feature_max(features, availability, dim=1))\n\n        fused = self.fuse(torch.cat(branches, dim=1))\n        aux = {\n            "alpha": alpha,                                      # gate weights\n            "gate_logits": logits,\n            "gate_entropy": _entropy(alpha),\n        }\n        return fused, aux\n\n\ndef _entropy(alpha: torch.Tensor, eps: float = 1e-8) -> torch.Tensor:\n    """Entropy of the gate distribution, a collapse and uncertainty diagnostic."""\n    p = alpha.float().clamp_min(eps)\n    return -(p * p.log()).sum(dim=-1)\n\n\n# --------------------------------------------------------------------------- #\n# Ablation variants A1 / A2 / A3 (plan 9.3)\n# --------------------------------------------------------------------------- #\nclass ChannelConcatFusion(nn.Module):\n    """A1: early channel concatenation with a zero-filled absent modality.\n\n    The classic weak baseline: absent sequences are zeros and the network is\n    never told which ones they are.\n    """\n\n    def __init__(self, channels: int, n_modalities: int = 4, **_: object):\n        super().__init__()\n        self.fuse = nn.Sequential(\n            nn.Conv2d(channels * n_modalities, channels, 1, bias=False),\n            _gn(channels), nn.GELU(),\n        )\n\n    def forward(self, features, availability, quality, embedding):\n        b, m, c, h, w = features.shape\n        masked = features * availability[:, :, None, None, None]\n        fused = self.fuse(masked.reshape(b, m * c, h, w))\n        return fused, {"alpha": availability / availability.sum(1, keepdim=True).clamp_min(1),\n                       "gate_logits": torch.zeros(b, m, device=features.device),\n                       "gate_entropy": torch.zeros(b, device=features.device)}\n\n\nclass EqualMaskedMean(nn.Module):\n    """A2/A3: equal-weight masked mean (A2) or mean+variance (A3, HeMIS-style)."""\n\n    def __init__(self, channels: int, with_variance: bool = False, **_: object):\n        super().__init__()\n        self.with_variance = with_variance\n        n = 2 if with_variance else 1\n        self.fuse = nn.Sequential(\n            nn.Conv2d(channels * n, channels, 1, bias=False),\n            _gn(channels), nn.GELU(),\n        )\n\n    def forward(self, features, availability, quality, embedding):\n        a = availability\n        w = a / a.sum(dim=1, keepdim=True).clamp_min(1e-8)\n        wm = w[..., None, None, None]\n        mu = (wm * features).sum(dim=1)\n        parts = [mu]\n        if self.with_variance:\n            var = (wm * (features - mu.unsqueeze(1)) ** 2).sum(dim=1)\n            parts.append(torch.sqrt(var.clamp_min(0) + 1e-6))\n        fused = self.fuse(torch.cat(parts, dim=1))\n        return fused, {"alpha": w, "gate_logits": torch.zeros_like(w),\n                       "gate_entropy": _entropy(w)}\n\n\ndef build_fusion(kind: str, channels: int, **kwargs) -> nn.Module:\n    """Fusion factory used by the ablation registry."""\n    if kind == "qmmf":\n        return QMMFBlock(channels, **kwargs)\n    if kind == "concat":\n        return ChannelConcatFusion(channels, **kwargs)\n    if kind == "equal_mean":\n        return EqualMaskedMean(channels, with_variance=False)\n    if kind == "equal_mean_var":\n        return EqualMaskedMean(channels, with_variance=True)\n    raise KeyError(f"Unknown fusion kind \'{kind}\'")\n', 'segmentation/src/qmmf/models/qmmf_net.py': '"""QMMF-Net: compact arbitrary-modality 2.5D segmentation network.\n\nShared pseudo-3D modality stems -> multi-scale per-modality features ->\nQMMF at every scale -> light large-kernel context mixer -> light U-Net decoder\nwith deep supervision -> three overlapping sigmoid outputs (WT, TC, ET).\n\nDesign targets from plan 7.7: < 8M parameters, < 14.5 GB peak VRAM on one T4.\nBoth are *gates to measure*, not claims; `count_parameters` and the VRAM\nprofiler in utils.py report the measured values into the experiment ledger.\n"""\n\nfrom __future__ import annotations\n\nfrom typing import Dict, List, Optional, Sequence, Tuple\n\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\n\nfrom ..config import MODALITIES, ModelConfig\nfrom .blocks import ContextMixer, ConvBlock, PseudoConv3DStem, UpBlock, norm_layer\nfrom .qmmf import build_fusion\n\n\nclass QMMFNet(nn.Module):\n    def __init__(\n        self,\n        cfg: Optional[ModelConfig] = None,\n        n_modalities: int = 4,\n        context_slices: int = 5,\n        n_outputs: int = 3,\n        fusion_kind: str = "qmmf",\n    ):\n        super().__init__()\n        cfg = cfg or ModelConfig()\n        self.cfg = cfg\n        self.n_modalities = n_modalities\n        self.n_outputs = n_outputs\n        self.widths = tuple(cfg.widths)\n        self.deep_supervision = cfg.deep_supervision\n\n        # One learned identity embedding per sequence; the stem itself is shared.\n        self.modality_embedding = nn.Parameter(\n            torch.randn(n_modalities, cfg.modality_embed_dim) * 0.02\n        )\n\n        self.stem = PseudoConv3DStem(\n            context_slices, self.widths[0],\n            cond_dim=cfg.modality_embed_dim, use_film=cfg.use_film,\n        )\n\n        # Per-modality encoder stages, weights shared across modalities.\n        self.encoders = nn.ModuleList([\n            ConvBlock(self.widths[i - 1], self.widths[i], depth=2, dropout=cfg.dropout)\n            for i in range(1, len(self.widths))\n        ])\n        self.pool = nn.AvgPool2d(2)\n\n        fusion_kwargs = dict(\n            quality_dim=cfg.quality_dim,\n            embed_dim=cfg.modality_embed_dim,\n            hidden=cfg.gate_hidden,\n            moments=cfg.moment_fusion,\n            use_quality=cfg.use_quality,\n            learned_gate=cfg.use_availability_gate,\n        ) if fusion_kind == "qmmf" else dict(n_modalities=n_modalities)\n\n        self.fusions = nn.ModuleList([\n            build_fusion(fusion_kind, w, **fusion_kwargs) for w in self.widths\n        ])\n\n        self.context = ContextMixer(\n            self.widths[-1], depth=cfg.context_depth,\n            kernel=cfg.context_kernel, mode=cfg.context_block,\n        )\n\n        rev = list(reversed(self.widths))\n        self.decoders = nn.ModuleList([\n            UpBlock(rev[i], rev[i + 1], rev[i + 1], dropout=cfg.dropout)\n            for i in range(len(rev) - 1)\n        ])\n        self.head = nn.Conv2d(self.widths[0], n_outputs, 1)\n        self.aux_heads = nn.ModuleList(\n            [nn.Conv2d(rev[i + 1], n_outputs, 1) for i in range(len(rev) - 2)]\n        ) if cfg.deep_supervision else nn.ModuleList()\n\n    # ------------------------------------------------------------------ #\n    def encode(self, image: torch.Tensor) -> List[torch.Tensor]:\n        """Per-modality multi-scale features.\n\n        image: [B, M, D, H, W] -> list of [B, M, C_s, H_s, W_s], one per scale.\n        """\n        b, m, d, h, w = image.shape\n        flat = image.reshape(b * m, d, h, w)\n        cond = self.modality_embedding.unsqueeze(0).expand(b, -1, -1).reshape(b * m, -1)\n\n        feats: List[torch.Tensor] = []\n        x = self.stem(flat, cond)\n        feats.append(x)\n        for enc in self.encoders:\n            x = enc(self.pool(x))\n            feats.append(x)\n        return [f.reshape(b, m, *f.shape[1:]) for f in feats]\n\n    def forward(\n        self,\n        image: torch.Tensor,             # [B, M, D, H, W]\n        availability: torch.Tensor,      # [B, M]\n        quality: torch.Tensor,           # [B, M, Q]\n        return_aux: bool = False,\n    ):\n        if image.dim() != 5:\n            raise ValueError(f"Expected [B, M, D, H, W]; got {tuple(image.shape)}")\n        if (availability.sum(dim=1) < 1).any():\n            raise ValueError("At least one modality must be available per sample.")\n\n        per_modality = self.encode(image)\n\n        fused: List[torch.Tensor] = []\n        aux_all: List[Dict[str, torch.Tensor]] = []\n        for feats, fusion in zip(per_modality, self.fusions):\n            z, aux = fusion(feats, availability, quality, self.modality_embedding)\n            fused.append(z)\n            aux_all.append(aux)\n\n        x = self.context(fused[-1])\n\n        # Deep supervision heads exist only to shape the training gradient, so\n        # they are evaluated in training mode only - at inference they would be\n        # pure wasted compute on a T4.\n        want_deep = self.deep_supervision and self.training\n        deep_logits: List[torch.Tensor] = []\n        skips = list(reversed(fused[:-1]))\n        for i, dec in enumerate(self.decoders):\n            x = dec(x, skips[i])\n            if want_deep and i < len(self.aux_heads):\n                deep_logits.append(self.aux_heads[i](x))\n        logits = self.head(x)\n\n        if not return_aux:\n            return logits\n        return logits, {\n            "deep_logits": deep_logits,\n            "gate_alpha": torch.stack([a["alpha"] for a in aux_all], dim=1),   # [B,S,M]\n            "gate_entropy": torch.stack([a["gate_entropy"] for a in aux_all], dim=1),\n            "fused": fused,\n        }\n\n    # ------------------------------------------------------------------ #\n    @torch.no_grad()\n    def gate_summary(\n        self, image: torch.Tensor, availability: torch.Tensor, quality: torch.Tensor\n    ) -> Dict[str, torch.Tensor]:\n        """Per-modality gate weights averaged over scales, for the gate-Shapley\n        alignment analysis (plan 10.4)."""\n        _, aux = self.forward(image, availability, quality, return_aux=True)\n        return {\n            "alpha_per_scale": aux["gate_alpha"],\n            "alpha_mean": aux["gate_alpha"].mean(dim=1),\n            "entropy_mean": aux["gate_entropy"].mean(dim=1),\n        }\n\n\n# --------------------------------------------------------------------------- #\n# Nested post-processing\n# --------------------------------------------------------------------------- #\ndef project_nested(probs: torch.Tensor) -> torch.Tensor:\n    """Enforce ET subset TC subset WT on probabilities.\n\n    p_TC <- min(p_TC, p_WT); p_ET <- min(p_ET, p_TC). Applied at inference, and\n    ablation A12 removes the matching training penalty to test its contribution.\n    """\n    wt = probs[:, 0:1]\n    tc = torch.minimum(probs[:, 1:2], wt)\n    et = torch.minimum(probs[:, 2:3], tc)\n    return torch.cat([wt, tc, et], dim=1)\n\n\ndef project_nested_numpy(probs):\n    import numpy as np\n    wt = probs[0]\n    tc = np.minimum(probs[1], wt)\n    et = np.minimum(probs[2], tc)\n    return np.stack([wt, tc, et], axis=0)\n', 'segmentation/src/qmmf/paths.py': '"""Deterministic dataset root resolution (plan 5.4).\n\nFails loudly when the root is ambiguous. Never guesses a mirror silently.\n"""\n\nfrom __future__ import annotations\n\nfrom pathlib import Path\nfrom typing import List, Optional\n\n# Kaggle mount candidates for MSD Task01_BrainTumour, in priority order.\nPRIMARY_CANDIDATES: List[str] = [\n    "/kaggle/input/medical-segmentation-decathlon-brain-tumour",\n    "/kaggle/input/medical-segmentation-decathlon-brain-tumor",\n    "/kaggle/working/msd_lite/MSD-BrainTumour",\n    "/kaggle/input/msd-task01-braintumour",\n]\n\nPEDIATRIC_CANDIDATES: List[str] = [\n    "/kaggle/working/brats2023_ped",\n    "/kaggle/input/brats2023-ped-dataset",\n    "/kaggle/input/brats-peds-2023",\n]\n\nHF_PRIMARY = dict(\n    repo_id="YongchengYAO/MSD-Lite",\n    repo_type="dataset",\n    local_dir="/kaggle/working/msd_lite",\n    allow_patterns=["MSD-BrainTumour/**", "README.md"],\n)\n\nHF_PEDIATRIC = dict(\n    repo_id="MedOtter/brats2023-ped-dataset",\n    repo_type="dataset",\n    local_dir="/kaggle/working/brats2023_ped",\n    allow_patterns=["data/nii/BraTS2023_PED/**", "train.jsonl", "README.md"],\n)\n\nKAGGLE_SLUG = "thisisrick25/medical-segmentation-decathlon-brain-tumour"\n\n\nclass DatasetRootError(RuntimeError):\n    """Raised when the dataset root cannot be resolved unambiguously."""\n\n\ndef _looks_like_msd(root: Path) -> bool:\n    return (\n        (root / "dataset.json").exists()\n        or (root / "imagesTr").is_dir()\n        or any(p.name == "imagesTr" for p in root.glob("*/imagesTr"))\n    )\n\n\ndef resolve_primary_root(\n    candidates: Optional[List[str]] = None, strict: bool = True\n) -> Path:\n    """Return the MSD Task01 root directory.\n\n    strict=True (the default, and what Notebook 01 uses) raises when zero or\n    more than one plausible root exists, rather than picking one.\n    """\n    candidates = candidates or PRIMARY_CANDIDATES\n    found = []\n    for c in candidates:\n        p = Path(c)\n        if not p.exists():\n            continue\n        if _looks_like_msd(p):\n            found.append(p)\n        else:\n            # One directory level down (Kaggle often nests the archive folder).\n            for child in sorted(p.iterdir()):\n                if child.is_dir() and _looks_like_msd(child):\n                    found.append(child)\n    found = sorted(set(found))\n    if not found:\n        raise DatasetRootError(\n            "No MSD Task01_BrainTumour root found. Attach the Kaggle dataset "\n            f"\'{KAGGLE_SLUG}\' or run the Hugging Face snapshot download "\n            f"({HF_PRIMARY[\'repo_id\']}). Searched: {candidates}"\n        )\n    if strict and len(found) > 1:\n        raise DatasetRootError(\n            f"Ambiguous dataset roots: {[str(p) for p in found]}. "\n            "Refusing to guess. Pass an explicit root."\n        )\n    return found[0]\n\n\ndef resolve_pediatric_root(\n    candidates: Optional[List[str]] = None, strict: bool = True\n) -> Path:\n    candidates = candidates or PEDIATRIC_CANDIDATES\n    found = [Path(c) for c in candidates if Path(c).exists()]\n    if not found:\n        raise DatasetRootError(\n            "No BraTS-PEDs 2023 root found. Download the public labelled "\n            f"training subset ({HF_PEDIATRIC[\'repo_id\']}) first."\n        )\n    if strict and len(found) > 1:\n        raise DatasetRootError(f"Ambiguous pediatric roots: {found}")\n    return found[0]\n\n\ndef download_primary_hf(**kwargs):\n    """Hugging Face fallback route; only used when the Kaggle mount is absent."""\n    from huggingface_hub import snapshot_download\n    args = dict(HF_PRIMARY)\n    args.update(kwargs)\n    return snapshot_download(**args)\n\n\ndef download_pediatric_hf(**kwargs):\n    from huggingface_hub import snapshot_download\n    args = dict(HF_PEDIATRIC)\n    args.update(kwargs)\n    return snapshot_download(**args)\n', 'segmentation/src/qmmf/quality.py': '"""Label-free per-sequence quality vector q (plan 7.3).\n\nSeven features per modality, computed from the image alone. They never see the\nsegmentation mask, and they are normalised using training-fold statistics only.\n\nThe shuffled-quality negative control (ablation A17) and the no-quality control\n(A5) are the evidence that decides whether the quality claim survives; this\nmodule provides both.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, asdict\nfrom typing import Dict, List, Optional, Sequence\n\nimport numpy as np\n\nQUALITY_FEATURES: List[str] = [\n    "snr_proxy",            # robust foreground variation / noise support\n    "coefficient_variation",\n    "entropy",\n    "robust_dynamic_range",\n    "zero_support_fraction",\n    "high_frequency_energy",\n    "center_of_mass_shift",\n]\nQUALITY_DIM = len(QUALITY_FEATURES)\n\n\ndef _robust_stats(values: np.ndarray) -> Dict[str, float]:\n    med = float(np.median(values))\n    mad = float(np.median(np.abs(values - med)))\n    return {"median": med, "mad": mad}\n\n\ndef compute_quality_vector(\n    volume: np.ndarray,\n    brain_mask: Optional[np.ndarray] = None,\n    n_bins: int = 64,\n) -> np.ndarray:\n    """Raw (un-normalised) 7-feature quality vector for one modality volume.\n\n    volume: 3D array in native intensity units.\n    brain_mask: optional boolean support; defaults to the nonzero voxels.\n    """\n    vol = np.asarray(volume, dtype=np.float32)\n    if brain_mask is None:\n        brain_mask = vol != 0\n    brain_mask = np.asarray(brain_mask, dtype=bool)\n\n    fg = vol[brain_mask]\n    out = np.zeros(QUALITY_DIM, dtype=np.float32)\n    if fg.size < 10:\n        # An absent or degenerate sequence gets a zero vector; the availability\n        # mask, not the quality vector, is what excludes it from fusion.\n        return out\n\n    stats = _robust_stats(fg)\n    bg = vol[~brain_mask]\n    noise = float(np.median(np.abs(bg - np.median(bg)))) if bg.size > 10 else 0.0\n    noise = max(noise, 1e-6)\n\n    out[0] = stats["mad"] / noise                                   # snr_proxy\n    mean = float(fg.mean())\n    out[1] = float(fg.std()) / (abs(mean) + 1e-6)                   # coeff. variation\n\n    p_lo, p_hi = np.percentile(fg, [0.5, 99.5])\n    if p_hi > p_lo:\n        hist, _ = np.histogram(np.clip(fg, p_lo, p_hi), bins=n_bins, range=(p_lo, p_hi))\n        p = hist.astype(np.float64) / max(hist.sum(), 1)\n        nz = p[p > 0]\n        out[2] = float(-(nz * np.log(nz)).sum() / np.log(n_bins))   # normalised entropy\n    p05, p95 = np.percentile(fg, [5, 95])\n    out[3] = float(p95 - p05) / (stats["mad"] + 1e-6)               # dynamic range\n\n    out[4] = float((np.abs(fg) < 1e-6).mean())                      # zero support\n\n    # Gradient energy as a blur/sharpness proxy, normalised by intensity scale.\n    grads = np.gradient(vol.astype(np.float32))\n    gmag = np.sqrt(sum(g ** 2 for g in grads))\n    out[5] = float(gmag[brain_mask].mean() / (stats["mad"] + 1e-6))\n\n    # Centre-of-mass displacement relative to the support centroid, in voxels,\n    # normalised by volume extent: detects large bias fields / intensity asymmetry.\n    coords = np.array(np.nonzero(brain_mask), dtype=np.float32)\n    if coords.shape[1] > 0:\n        support_c = coords.mean(axis=1)\n        weights = np.clip(vol[brain_mask], 0, None)\n        wsum = float(weights.sum())\n        if wsum > 0:\n            intensity_c = (coords * weights[None, :]).sum(axis=1) / wsum\n            extent = np.array(vol.shape, dtype=np.float32)\n            out[6] = float(np.linalg.norm((intensity_c - support_c) / extent))\n    return np.nan_to_num(out, nan=0.0, posinf=0.0, neginf=0.0)\n\n\ndef compute_quality_matrix(\n    volumes: Sequence[np.ndarray], brain_mask: Optional[np.ndarray] = None\n) -> np.ndarray:\n    """Quality matrix [M, Q] for one case, one row per modality."""\n    return np.stack(\n        [compute_quality_vector(v, brain_mask) for v in volumes], axis=0\n    ).astype(np.float32)\n\n\n# --------------------------------------------------------------------------- #\n@dataclass\nclass QualityNormalizer:\n    """Per-modality robust normaliser fitted on training-fold cases only."""\n\n    median: np.ndarray          # [M, Q]\n    iqr: np.ndarray             # [M, Q]\n    feature_names: List[str]\n\n    @classmethod\n    def fit(cls, matrices: Sequence[np.ndarray]) -> "QualityNormalizer":\n        stack = np.stack(matrices, axis=0)                    # [N, M, Q]\n        med = np.median(stack, axis=0)\n        q75, q25 = np.percentile(stack, [75, 25], axis=0)\n        iqr = np.maximum(q75 - q25, 1e-6)\n        return cls(median=med, iqr=iqr, feature_names=list(QUALITY_FEATURES))\n\n    def transform(self, matrix: np.ndarray, clip: float = 5.0) -> np.ndarray:\n        z = (np.asarray(matrix, dtype=np.float32) - self.median) / self.iqr\n        return np.clip(z, -clip, clip).astype(np.float32)\n\n    def to_dict(self) -> Dict:\n        d = asdict(self)\n        d["median"] = self.median.tolist()\n        d["iqr"] = self.iqr.tolist()\n        return d\n\n    @classmethod\n    def from_dict(cls, d: Dict) -> "QualityNormalizer":\n        return cls(\n            median=np.array(d["median"], dtype=np.float32),\n            iqr=np.array(d["iqr"], dtype=np.float32),\n            feature_names=list(d.get("feature_names", QUALITY_FEATURES)),\n        )\n\n\n# --------------------------------------------------------------------------- #\n# Negative controls\n# --------------------------------------------------------------------------- #\ndef shuffle_quality_across_patients(\n    quality: np.ndarray, rng: np.random.Generator\n) -> np.ndarray:\n    """A17 negative control: permute quality vectors across patients in a batch.\n\n    If the model\'s quality claim is real, this must degrade the relevant\n    endpoint. If it does not, the quality contribution claim is dropped\n    (gate G3).\n    """\n    q = np.asarray(quality)\n    if q.ndim != 3:\n        raise ValueError("Expected a batch of quality matrices [B, M, Q].")\n    perm = rng.permutation(q.shape[0])\n    return q[perm]\n\n\ndef zero_quality(quality: np.ndarray) -> np.ndarray:\n    """A5 control: remove the quality signal entirely (availability gate only)."""\n    return np.zeros_like(quality)\n', 'segmentation/src/qmmf/shapley.py': '"""Exact patient-level Shapley modality attribution (plan 10.3).\n\n    phi_m = sum over S subset of M without m\n              |S|! (|M|-|S|-1)! / |M|!  *  [ v(S union {m}) - v(S) ]\n\nWith |M| = 4 there are only 15 non-empty subsets, and every one of them is\nevaluated for every locked-test patient, so the Shapley values are exact - no\nMonte Carlo sampling and no approximation error to caveat.\n\nTwo conventions must be stated because they change the numbers:\n  * v(empty set) is not defined by a model prediction (the network requires at\n    least one sequence). We set v(empty) = `empty_value`, default 0.0, which\n    means phi_m is the contribution relative to predicting nothing. This is\n    declared, not silently assumed, and `efficiency_gap` reports the residual.\n  * v is patient-level Dice for the region in question, so Shapley values are\n    computed separately for WT, TC, ET and macro Dice.\n"""\n\nfrom __future__ import annotations\n\nfrom itertools import combinations\nfrom math import factorial\nfrom typing import Callable, Dict, Iterable, List, Mapping, Optional, Sequence, Tuple\n\nimport numpy as np\n\nfrom .config import MODALITIES\nfrom .subsets import ALL_SUBSETS, subset_key\n\n\ndef shapley_weights(n: int) -> Dict[int, float]:\n    """Weight |S|! (n-|S|-1)! / n! for each coalition size |S|."""\n    return {\n        s: factorial(s) * factorial(n - s - 1) / factorial(n)\n        for s in range(n)\n    }\n\n\ndef exact_shapley(\n    value_fn: Mapping[Tuple[str, ...], float] | Callable[[Tuple[str, ...]], float],\n    modalities: Sequence[str] = MODALITIES,\n    empty_value: float = 0.0,\n) -> Dict[str, float]:\n    """Exact Shapley values for every modality.\n\n    value_fn: either a dict keyed by subset tuple, or a callable.\n    """\n    mods = tuple(modalities)\n    n = len(mods)\n    weights = shapley_weights(n)\n\n    def v(subset: Tuple[str, ...]) -> float:\n        if not subset:\n            return empty_value\n        if callable(value_fn):\n            return float(value_fn(subset))\n        if subset in value_fn:\n            return float(value_fn[subset])\n        # Accept string-keyed tables too.\n        return float(value_fn[subset_key(subset)])  # type: ignore[index]\n\n    phi: Dict[str, float] = {}\n    for m in mods:\n        others = [x for x in mods if x != m]\n        total = 0.0\n        for size in range(len(others) + 1):\n            for combo in combinations(others, size):\n                s = tuple(sorted(combo, key=mods.index))\n                s_with = tuple(sorted(combo + (m,), key=mods.index))\n                total += weights[size] * (v(s_with) - v(s))\n        phi[m] = float(total)\n    return phi\n\n\ndef efficiency_gap(\n    phi: Mapping[str, float],\n    full_value: float,\n    empty_value: float = 0.0,\n) -> float:\n    """Shapley efficiency axiom check: sum(phi) must equal v(M) - v(empty).\n\n    Returned as a residual so the notebook can assert it is ~0 rather than\n    trusting the implementation.\n    """\n    return float(sum(phi.values()) - (full_value - empty_value))\n\n\n# --------------------------------------------------------------------------- #\ndef shapley_from_subset_table(\n    subset_scores: Mapping[str, float],\n    modalities: Sequence[str] = MODALITIES,\n    empty_value: float = 0.0,\n) -> Dict[str, float]:\n    """Convenience wrapper taking the \'+\'-joined subset keys used in results\n    files, e.g. {\'t1\': .., \'t1+flair\': .., ...}."""\n    table = {s: float(subset_scores[subset_key(s)]) for s in ALL_SUBSETS}\n    return exact_shapley(table, modalities, empty_value)\n\n\ndef patient_shapley_table(\n    per_case_subset_scores: Mapping[str, Mapping[str, float]],\n    modalities: Sequence[str] = MODALITIES,\n    empty_value: float = 0.0,\n):\n    """One Shapley row per patient.\n\n    per_case_subset_scores: case_id -> {subset_key: score}\n    Returns a DataFrame with columns [case_id, <modality>..., efficiency_gap].\n    """\n    import pandas as pd\n    rows = []\n    for case_id, table in per_case_subset_scores.items():\n        phi = shapley_from_subset_table(table, modalities, empty_value)\n        full = float(table[subset_key(tuple(modalities))])\n        row = {"case_id": case_id, **phi,\n               "efficiency_gap": efficiency_gap(phi, full, empty_value),\n               "full_value": full}\n        rows.append(row)\n    return pd.DataFrame(rows)\n\n\n# --------------------------------------------------------------------------- #\n# Gate versus Shapley (plan 10.4)\n# --------------------------------------------------------------------------- #\ndef normalize_positive(values: Mapping[str, float]) -> Dict[str, float]:\n    """Normalise the *positive* part of a contribution vector to sum to one.\n\n    Negative Shapley values are real and interesting (Qiu et al. 2025 show an\n    added modality can hurt), so they are clipped for the comparison with the\n    gate simplex but reported separately.\n    """\n    pos = {k: max(v, 0.0) for k, v in values.items()}\n    total = sum(pos.values())\n    if total <= 0:\n        n = len(pos)\n        return {k: 1.0 / n for k in pos}\n    return {k: v / total for k, v in pos.items()}\n\n\ndef gate_shapley_mismatch(\n    gate_weights: Mapping[str, float],\n    shapley_values: Mapping[str, float],\n) -> float:\n    """Standardised divergence between learned gates and exact contributions.\n\n    Total-variation distance between the two normalised distributions, in\n    [0, 1]. This is the reliability signal tested in RQ5 / C4.\n    """\n    g = normalize_positive(dict(gate_weights))\n    s = normalize_positive(dict(shapley_values))\n    keys = sorted(set(g) | set(s))\n    return float(0.5 * sum(abs(g.get(k, 0.0) - s.get(k, 0.0)) for k in keys))\n\n\ndef gate_shapley_alignment(\n    gate_table, shapley_table, modalities: Sequence[str] = MODALITIES,\n) -> Dict[str, float]:\n    """Per-patient Spearman correlation between gate weights and Shapley values,\n    plus the mean mismatch. Bootstrap CIs are added by stats.bootstrap_ci."""\n    from scipy.stats import spearmanr\n    import pandas as pd\n\n    gate = pd.DataFrame(gate_table).set_index("case_id")\n    shap = pd.DataFrame(shapley_table).set_index("case_id")\n    shared = sorted(set(gate.index) & set(shap.index))\n    if not shared:\n        raise ValueError("No overlapping case ids between gate and Shapley tables.")\n\n    rhos, mismatches = [], []\n    for cid in shared:\n        g = [float(gate.loc[cid, m]) for m in modalities]\n        s = [float(shap.loc[cid, m]) for m in modalities]\n        if np.std(g) < 1e-12 or np.std(s) < 1e-12:\n            rho = np.nan            # a constant vector has no rank correlation\n        else:\n            rho = float(spearmanr(g, s).statistic)\n        rhos.append(rho)\n        mismatches.append(gate_shapley_mismatch(\n            dict(zip(modalities, g)), dict(zip(modalities, s))\n        ))\n    return {\n        "mean_spearman": float(np.nanmean(rhos)),\n        "median_spearman": float(np.nanmedian(rhos)),\n        "mean_mismatch": float(np.mean(mismatches)),\n        "n_cases": len(shared),\n        "n_undefined_spearman": int(np.sum(np.isnan(rhos))),\n        "per_case_spearman": rhos,\n        "per_case_mismatch": mismatches,\n        "case_ids": shared,\n    }\n\n\ndef mismatch_predicts_error(\n    mismatch: Sequence[float],\n    error: Sequence[float],\n    entropy: Optional[Sequence[float]] = None,\n    modality_count: Optional[Sequence[int]] = None,\n) -> Dict[str, float]:\n    """Exploratory regression: does gate-Shapley mismatch explain segmentation\n    error beyond entropy and modality count?\n\n    Reported as exploratory evidence (RQ5), never as a causal claim.\n    """\n    import pandas as pd\n    import statsmodels.api as sm  # optional dependency; see requirements.txt\n\n    df = pd.DataFrame({"mismatch": np.asarray(mismatch, dtype=float),\n                       "error": np.asarray(error, dtype=float)})\n    cols = ["mismatch"]\n    if entropy is not None:\n        df["entropy"] = np.asarray(entropy, dtype=float)\n        cols.append("entropy")\n    if modality_count is not None:\n        df["n_modalities"] = np.asarray(modality_count, dtype=float)\n        cols.append("n_modalities")\n    df = df.dropna()\n    X = sm.add_constant(df[cols])\n    model = sm.OLS(df["error"], X).fit()\n    return {\n        "coef_mismatch": float(model.params["mismatch"]),\n        "pvalue_mismatch": float(model.pvalues["mismatch"]),\n        "r_squared": float(model.rsquared),\n        "n": int(len(df)),\n        "summary": model.summary().as_text(),\n    }\n', 'segmentation/src/qmmf/slab_cache.py': '"""Lossless slice-chunk cache: identical training samples with less decompression."""\nfrom pathlib import Path\nimport hashlib\nimport numpy as np\nfrom .transforms import sample_slice_from_indices\n\n\ndef build_training_slabs(source, destination, slab_depth=8):\n    source, destination = Path(source), Path(destination)\n    with np.load(source, allow_pickle=False) as z:\n        if int(z["cache_version"]) != 2 or list(z["source_channel_order"]) != [1, 2, 3, 0]:\n            raise ValueError("Training slabs require a verified canonical version-2 cache")\n        image, target, brain = z["image"], z["target"], z["brain_mask"]\n        payload = {"format_version": np.array(1), "source_cache_version": np.array(2),\n            "source_channel_order": z["source_channel_order"], "quality_raw": z["quality_raw"],\n            "slab_depth": np.array(slab_depth), "image_depth": np.array(image.shape[-1]),\n            "brain_slices": np.flatnonzero(brain.any(axis=(0, 1))),\n            "tumour_slices": np.flatnonzero((target[0] > 0).any(axis=(0, 1)))}\n    for start in range(0, image.shape[-1], slab_depth):\n        index = start // slab_depth\n        payload[f"image_{index:03d}"] = image[..., start:start + slab_depth]\n        payload[f"target_{index:03d}"] = target[..., start:start + slab_depth]\n    destination.parent.mkdir(parents=True, exist_ok=True)\n    temp = destination.with_suffix(".tmp.npz")\n    np.savez_compressed(temp, **payload)\n    # Compare every voxel after compression, not just a checksum of the writer\'s input.\n    with np.load(temp, allow_pickle=False) as z:\n        for start in range(0, image.shape[-1], slab_depth):\n            index = start // slab_depth\n            if not np.array_equal(z[f"image_{index:03d}"], image[..., start:start + slab_depth]):\n                raise ValueError("Image values changed during chunk-cache conversion")\n            if not np.array_equal(z[f"target_{index:03d}"], target[..., start:start + slab_depth]):\n                raise ValueError("Target values changed during chunk-cache conversion")\n    temp.replace(destination)\n    return {"case_id": source.stem, "source_sha256": hashlib.sha256(source.read_bytes()).hexdigest(),\n        "slab_sha256": hashlib.sha256(destination.read_bytes()).hexdigest(),\n        "source_bytes": source.stat().st_size, "slab_bytes": destination.stat().st_size,\n        "voxel_equality_verified": True, "image_depth": image.shape[-1]}\n\n\nclass TrainingSlabReader:\n    def __init__(self, directory):\n        self.directory = Path(directory)\n        self._metadata = {}\n\n    def metadata(self, cid):\n        if cid not in self._metadata:\n            with np.load(self.directory / f"{cid}.npz", allow_pickle=False) as z:\n                if int(z["format_version"]) != 1 or int(z["source_cache_version"]) != 2:\n                    raise ValueError("Unrecognized training slab format")\n                if list(z["source_channel_order"]) != [1, 2, 3, 0]:\n                    raise ValueError("Training slab channel order is incorrect")\n                self._metadata[cid] = {key: z[key] for key in ["slab_depth", "image_depth",\n                    "brain_slices", "tumour_slices", "quality_raw"]}\n        return self._metadata[cid]\n\n    def window(self, cid, zslice, context=5):\n        if context < 1 or context % 2 != 1:\n            raise ValueError("Context must be a positive odd number")\n        meta = self.metadata(cid)\n        size, depth = int(meta["slab_depth"]), int(meta["image_depth"])\n        if not 0 <= zslice < depth:\n            raise ValueError("Slice index outside the volume")\n        indices = np.clip(np.arange(zslice - context // 2, zslice + context // 2 + 1), 0, depth - 1)\n        with np.load(self.directory / f"{cid}.npz", allow_pickle=False) as z:\n            slabs = {int(i): z[f"image_{i:03d}"] for i in np.unique(indices // size)}\n            window = np.stack([slabs[int(i // size)][..., i % size] for i in indices], axis=1)\n            target = z[f"target_{zslice // size:03d}"][..., zslice % size]\n        return window.astype(np.float32), target.astype(np.float32)\n\n    def sample(self, cid, cfg, rng):\n        meta = self.metadata(cid)\n        zslice = sample_slice_from_indices(int(meta["image_depth"]), meta["brain_slices"],\n            meta["tumour_slices"], rng, cfg.p_tumor_window, cfg.p_boundary_window)\n        window, target = self.window(cid, zslice, cfg.context_slices)\n        return window, target, zslice, meta["quality_raw"]\n', 'segmentation/src/qmmf/splits.py': '"""Hashed case and conservative-group splits, with legacy provenance support.\n\n`build_splits` preserves the original case-ID protocol for auditing. Real MRI\nexperiments use `build_grouped_splits` to keep related volumes in the same role.\nSimilarity groups do not establish verified patient identities.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, asdict, field\nfrom pathlib import Path\nfrom typing import Dict, List, Optional, Sequence\n\nimport numpy as np\nimport pandas as pd\n\nfrom .utils import sha256_obj, write_json\n\n\nLOCKED_TEST_FRACTION = 0.20\nN_FOLDS = 4\nINNER_VAL_FRACTION = 0.15   # of each training fold, for early stop / thresholds\nLABEL_FRACTIONS = (0.25, 0.50, 1.00)\n\n\n@dataclass\nclass Splits:\n    locked_test: List[str]\n    development: List[str]\n    folds: Dict[str, Dict[str, List[str]]]      # "0" -> {train, inner_val, outer_val}\n    label_subsets: Dict[str, List[str]]         # "0.25" -> case ids\n    strata: Dict[str, str]\n    seed: int\n    split_hash: str = ""\n    case_to_group: Dict[str, str] = field(default_factory=dict)\n    partition_policy: Dict = field(default_factory=dict)\n\n    def to_dict(self) -> Dict:\n        d = asdict(self)\n        d.pop("split_hash", None)\n        # Keep old hashes readable as provenance, while hashing every new group.\n        if not d["case_to_group"]:\n            d.pop("case_to_group")\n        if not d["partition_policy"]:\n            d.pop("partition_policy")\n        return d\n\n    def compute_hash(self) -> str:\n        return sha256_obj(self.to_dict())[:16]\n\n    def save(self, path: str | Path) -> str:\n        self.split_hash = self.compute_hash()\n        payload = self.to_dict()\n        payload["split_hash"] = self.split_hash\n        write_json(path, payload)\n        return self.split_hash\n\n    @classmethod\n    def load(cls, path: str | Path) -> "Splits":\n        import json\n        payload = json.loads(Path(path).read_text())\n        stored = payload.pop("split_hash", "")\n        obj = cls(**payload)\n        recomputed = obj.compute_hash()\n        if stored and stored != recomputed:\n            raise ValueError(\n                f"Split file hash mismatch: stored {stored}, recomputed {recomputed}. "\n                "The partition has been modified; refuse to train or test."\n            )\n        obj.split_hash = recomputed\n        return obj\n\n\n# --------------------------------------------------------------------------- #\ndef make_strata(\n    manifest: pd.DataFrame,\n    volume_col: str = "wt_volume_ml",\n    et_col: str = "et_present",\n    n_quantiles: int = 4,\n    min_per_stratum: int = 8,\n) -> pd.Series:\n    """Stratification code = ET presence x tumour-volume quartile (plan 6.1).\n\n    Sparse strata are merged deterministically so that every stratum can supply\n    at least one case to the locked test and to each of the four folds.\n    """\n    if volume_col not in manifest or et_col not in manifest:\n        raise KeyError(f"Manifest needs \'{volume_col}\' and \'{et_col}\' columns.")\n    vol = manifest[volume_col].astype(float)\n    try:\n        quart = pd.qcut(vol, q=n_quantiles, labels=False, duplicates="drop")\n    except ValueError:\n        quart = pd.Series(np.zeros(len(vol), dtype=int), index=manifest.index)\n    quart = quart.fillna(0).astype(int)\n    et = manifest[et_col].astype(int)\n    code = et.astype(str) + "_q" + quart.astype(str)\n\n    counts = code.value_counts()\n    # Merge any stratum that is too small into the nearest quartile with the\n    # same ET status; fall back to the ET status alone.\n    remap: Dict[str, str] = {}\n    for key, count in counts.items():\n        if count >= min_per_stratum:\n            continue\n        et_val = key.split("_")[0]\n        siblings = [k for k, c in counts.items()\n                    if k != key and k.startswith(et_val + "_") and c >= min_per_stratum]\n        remap[key] = siblings[0] if siblings else f"{et_val}_merged"\n    return code.map(lambda k: remap.get(k, k))\n\n\ndef _stratified_partition(\n    ids: Sequence[str], strata: Sequence[str], fractions: Sequence[float],\n    rng: np.random.Generator,\n) -> List[List[str]]:\n    """Split ids into len(fractions) groups, stratified and deterministic."""\n    ids = list(ids)\n    strata = list(strata)\n    groups: List[List[str]] = [[] for _ in fractions]\n    by_stratum: Dict[str, List[str]] = {}\n    for cid, s in zip(ids, strata):\n        by_stratum.setdefault(s, []).append(cid)\n\n    for stratum in sorted(by_stratum):\n        members = sorted(by_stratum[stratum])\n        perm = rng.permutation(len(members))\n        members = [members[i] for i in perm]\n        n = len(members)\n        # Largest-remainder allocation keeps the totals exact.\n        raw = [f * n for f in fractions]\n        counts = [int(np.floor(r)) for r in raw]\n        remainder = n - sum(counts)\n        order = np.argsort([-(r - np.floor(r)) for r in raw], kind="stable")\n        for i in range(remainder):\n            counts[order[i % len(counts)]] += 1\n        pos = 0\n        for gi, c in enumerate(counts):\n            groups[gi].extend(members[pos:pos + c])\n            pos += c\n    return [sorted(g) for g in groups]\n\n\ndef build_splits(\n    manifest: pd.DataFrame,\n    seed: int = 42,\n    case_col: str = "case_id",\n    locked_fraction: float = LOCKED_TEST_FRACTION,\n    n_folds: int = N_FOLDS,\n    inner_val_fraction: float = INNER_VAL_FRACTION,\n) -> Splits:\n    """Create the locked test, the four development folds and nested label subsets.\n\n    Returns a Splits object; call .save() to freeze it with a hash.\n    """\n    if manifest[case_col].duplicated().any():\n        raise ValueError("Duplicate case ids in manifest; resolve before splitting.")\n    rng = np.random.default_rng(seed)\n    strata = make_strata(manifest)\n    ids = manifest[case_col].astype(str).tolist()\n    strata_map = {cid: str(s) for cid, s in zip(ids, strata)}\n\n    locked, development = _stratified_partition(\n        ids, [strata_map[c] for c in ids], [locked_fraction, 1 - locked_fraction], rng\n    )\n\n    # Four outer-validation partitions over the development pool.\n    fold_parts = _stratified_partition(\n        development, [strata_map[c] for c in development],\n        [1.0 / n_folds] * n_folds, rng,\n    )\n\n    folds: Dict[str, Dict[str, List[str]]] = {}\n    for k in range(n_folds):\n        outer_val = fold_parts[k]\n        train_pool = sorted(set(development) - set(outer_val))\n        inner_val, train = _stratified_partition(\n            train_pool, [strata_map[c] for c in train_pool],\n            [inner_val_fraction, 1 - inner_val_fraction],\n            np.random.default_rng(seed + 1000 + k),\n        )\n        folds[str(k)] = {\n            "train": sorted(train),\n            "inner_val": sorted(inner_val),\n            "outer_val": sorted(outer_val),\n        }\n\n    label_subsets = build_nested_label_subsets(\n        development, strata_map, seed=seed, fractions=LABEL_FRACTIONS\n    )\n\n    splits = Splits(\n        locked_test=sorted(locked),\n        development=sorted(development),\n        folds=folds,\n        label_subsets=label_subsets,\n        strata=strata_map,\n        seed=seed,\n    )\n    validate_splits(splits)\n    splits.split_hash = splits.compute_hash()\n    return splits\n\n\ndef build_grouped_splits(\n    manifest: pd.DataFrame,\n    case_to_group: Dict[str, str],\n    seed: int = 42,\n    locked_ineligible_groups: Sequence[str] = (),\n    locked_fraction: float = LOCKED_TEST_FRACTION,\n    n_folds: int = N_FOLDS,\n    inner_val_fraction: float = INNER_VAL_FRACTION,\n) -> Splits:\n    """Partition complete similarity groups; never split related case IDs.\n\n    A fresh protected test can exclude groups exposed during an aborted pilot.\n    Stratification uses median group tumour volume and any enhancing target.\n    """\n    frame = manifest.copy()\n    ids = frame.case_id.astype(str).tolist()\n    if len(ids) != len(set(ids)) or set(ids) != set(case_to_group):\n        raise ValueError("Grouping must cover the unique manifest case IDs exactly")\n    frame["group_id"] = frame.case_id.map(case_to_group)\n    frame["wt_volume_ml"] = frame.wt_volume_ml.astype(float)\n    frame["et_present"] = frame.et_present.astype(int)\n    grouped = frame.groupby("group_id", sort=True).agg(\n        wt_volume_ml=("wt_volume_ml", "median"), et_present=("et_present", "max"))\n    grouped = grouped.reset_index().rename(columns={"group_id": "case_id"})\n    group_ids = grouped.case_id.tolist()\n    strata = make_strata(grouped)\n    strata_map = dict(zip(group_ids, map(str, strata)))\n    excluded = set(locked_ineligible_groups)\n    if not excluded <= set(group_ids):\n        raise ValueError("Unknown group in protected-test exclusion list")\n    eligible = sorted(set(group_ids) - excluded)\n    target = max(1, int(round(locked_fraction * len(group_ids))))\n    if len(eligible) <= target:\n        raise ValueError("Insufficient unexposed groups for a fresh protected test")\n    fraction = target / len(eligible)\n    locked, _ = _stratified_partition(\n        eligible, [strata_map[g] for g in eligible], [fraction, 1 - fraction],\n        np.random.default_rng(seed))\n    development = sorted(set(group_ids) - set(locked))\n    fold_parts = _stratified_partition(\n        development, [strata_map[g] for g in development], [1 / n_folds] * n_folds,\n        np.random.default_rng(seed + 1))\n    by_group = frame.groupby("group_id").case_id.agg(list).to_dict()\n    def expand(groups):\n        return sorted(cid for group in groups for cid in by_group[group])\n    folds = {}\n    for k, outer in enumerate(fold_parts):\n        pool = sorted(set(development) - set(outer))\n        inner, train = _stratified_partition(\n            pool, [strata_map[g] for g in pool], [inner_val_fraction, 1 - inner_val_fraction],\n            np.random.default_rng(seed + 1000 + k))\n        folds[str(k)] = {"train": expand(train), "inner_val": expand(inner), "outer_val": expand(outer)}\n    label_groups = build_nested_label_subsets(development, strata_map, seed=seed)\n    result = Splits(locked_test=expand(locked), development=expand(development), folds=folds,\n        label_subsets={key: expand(value) for key, value in label_groups.items()},\n        strata={cid: strata_map[case_to_group[cid]] for cid in sorted(ids)}, seed=seed,\n        case_to_group=dict(sorted(case_to_group.items())),\n        partition_policy={"unit": "conservative_image_similarity_group",\n            "locked_ineligible_groups": sorted(excluded), "eligible_test_groups": len(eligible),\n            "target_test_groups": target, "actual_test_groups": len(locked),\n            "group_stratification": "median WT volume and any ET presence",\n            "pilot_exposure_excluded": bool(excluded)})\n    validate_splits(result)\n    result.split_hash = result.compute_hash()\n    return result\n\n\ndef build_nested_label_subsets(\n    development: Sequence[str],\n    strata_map: Dict[str, str],\n    seed: int = 42,\n    fractions: Sequence[float] = LABEL_FRACTIONS,\n) -> Dict[str, List[str]]:\n    """Strictly nested 25% subset of 50% subset of 100% (plan 6.5)."""\n    fractions = sorted(fractions)\n    rng = np.random.default_rng(seed + 77)\n    current = sorted(development)\n    subsets: Dict[str, List[str]] = {f"{max(fractions):.2f}": sorted(development)}\n    # Build from the largest downwards so each is a strict subset of the previous.\n    for frac in sorted(fractions, reverse=True)[1:]:\n        target_n = int(round(frac * len(development)))\n        keep, _ = _stratified_partition(\n            current, [strata_map[c] for c in current],\n            [target_n / len(current), 1 - target_n / len(current)], rng,\n        )\n        subsets[f"{frac:.2f}"] = sorted(keep)\n        current = sorted(keep)\n    return dict(sorted(subsets.items()))\n\n\n# --------------------------------------------------------------------------- #\ndef validate_splits(splits: Splits) -> None:\n    """Assertions the plan requires before training is permitted (gate G0)."""\n    locked = set(splits.locked_test)\n    dev = set(splits.development)\n    if locked & dev:\n        raise AssertionError(f"Locked test leaks into development: {sorted(locked & dev)}")\n    if not locked or not dev:\n        raise AssertionError("Empty locked test or development pool.")\n\n    seen_outer: List[str] = []\n    for k, part in splits.folds.items():\n        tr, iv, ov = set(part["train"]), set(part["inner_val"]), set(part["outer_val"])\n        if tr & iv or tr & ov or iv & ov:\n            raise AssertionError(f"Fold {k} partitions overlap.")\n        if (tr | iv | ov) != dev:\n            missing = dev - (tr | iv | ov)\n            extra = (tr | iv | ov) - dev\n            raise AssertionError(\n                f"Fold {k} does not cover the development pool exactly "\n                f"(missing {len(missing)}, extra {len(extra)})."\n            )\n        if (tr | iv | ov) & locked:\n            raise AssertionError(f"Fold {k} touches the locked test.")\n        seen_outer.extend(part["outer_val"])\n\n    # Each development case appears once in the outer partitions. Patient\n    # independence additionally needs the group/identity checks below.\n    counts = pd.Series(seen_outer).value_counts()\n    if len(seen_outer) != len(dev) or (counts != 1).any():\n        raise AssertionError("Outer-validation partitions do not cover each case once.")\n\n    keys = sorted(splits.label_subsets, key=float)\n    for small, large in zip(keys, keys[1:]):\n        if not set(splits.label_subsets[small]) <= set(splits.label_subsets[large]):\n            raise AssertionError(\n                f"Label subset {small} is not a strict subset of {large}."\n            )\n    if not set(splits.label_subsets[keys[-1]]) <= dev:\n        raise AssertionError("Label subsets contain non-development cases.")\n\n    if splits.case_to_group:\n        mapping = splits.case_to_group\n        if set(mapping) != locked | dev or any(not isinstance(g, str) or not g for g in mapping.values()):\n            raise AssertionError("Group map must cover every case exactly")\n        def groups(cases):\n            return {mapping[c] for c in cases}\n        locked_groups = groups(locked)\n        if locked_groups & groups(dev):\n            raise AssertionError("Similarity group crosses locked test and development")\n        forbidden = set(splits.partition_policy.get("locked_ineligible_groups", []))\n        if locked_groups & forbidden:\n            raise AssertionError("Protected test includes a group exposed during the aborted pilot")\n        for k, part in splits.folds.items():\n            roles = {name: groups(cases) for name, cases in part.items()}\n            names = list(roles)\n            for i, a in enumerate(names):\n                for b in names[i + 1:]:\n                    if roles[a] & roles[b]:\n                        raise AssertionError(f"Similarity group crosses {a}/{b} in fold {k}")\n        for key, cases in splits.label_subsets.items():\n            selected = set(cases)\n            for cid in dev - selected:\n                if mapping[cid] in groups(selected):\n                    raise AssertionError(f"Label subset {key} splits a similarity group")\n\n\ndef training_cases(\n    splits: Splits, fold: int, label_fraction: float = 1.0\n) -> List[str]:\n    """Training ids for a fold, intersected with the nested label subset."""\n    part = splits.folds[str(fold)]\n    allowed = set(splits.label_subsets[f"{label_fraction:.2f}"])\n    return sorted(set(part["train"]) & allowed)\n', 'segmentation/src/qmmf/stats.py': '"""Patient-level statistical analysis (plan 10.5).\n\nEvery function here operates on *paired, patient-level* values. Slice-level\nnumbers are never valid input; the aggregation happens in metrics.py first.\n\nReported quantities are effect sizes with confidence intervals; p-values are\nsecondary and always Holm-corrected within a pre-declared comparison family.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, asdict\nfrom typing import Dict, Iterable, List, Optional, Sequence, Tuple\n\nimport numpy as np\n\n\n# --------------------------------------------------------------------------- #\n@dataclass\nclass PairedResult:\n    name: str\n    n: int\n    mean_a: float\n    mean_b: float\n    mean_difference: float\n    ci_low: float\n    ci_high: float\n    effect_size: float          # Cohen\'s d_z for paired data\n    p_value: float\n    test: str\n    p_holm: float = float("nan")\n\n    def to_dict(self) -> Dict:\n        return asdict(self)\n\n\n# --------------------------------------------------------------------------- #\ndef bootstrap_ci(\n    values: Sequence[float],\n    statistic=np.mean,\n    n_boot: int = 10_000,\n    alpha: float = 0.05,\n    seed: int = 12345,\n    strata: Optional[Sequence] = None,\n) -> Tuple[float, float, float]:\n    """Percentile bootstrap CI, optionally stratified (e.g. by ET presence).\n\n    Returns (point_estimate, ci_low, ci_high).\n    """\n    x = np.asarray(values, dtype=np.float64)\n    x = x[np.isfinite(x)]\n    if x.size == 0:\n        return float("nan"), float("nan"), float("nan")\n    rng = np.random.default_rng(seed)\n    point = float(statistic(x))\n\n    if strata is None:\n        idx = rng.integers(0, x.size, size=(n_boot, x.size))\n        samples = np.apply_along_axis(statistic, 1, x[idx]) if statistic is not np.mean \\\n            else x[idx].mean(axis=1)\n    else:\n        s = np.asarray(strata)[np.isfinite(np.asarray(values, dtype=np.float64))]\n        groups = [np.flatnonzero(s == g) for g in np.unique(s)]\n        samples = np.empty(n_boot, dtype=np.float64)\n        for b in range(n_boot):\n            pick = np.concatenate([\n                g[rng.integers(0, g.size, size=g.size)] for g in groups if g.size\n            ])\n            samples[b] = statistic(x[pick])\n    lo, hi = np.percentile(samples, [100 * alpha / 2, 100 * (1 - alpha / 2)])\n    return point, float(lo), float(hi)\n\n\ndef paired_bootstrap_difference(\n    a: Sequence[float], b: Sequence[float],\n    n_boot: int = 10_000, alpha: float = 0.05, seed: int = 12345,\n    strata: Optional[Sequence] = None,\n) -> Tuple[float, float, float]:\n    """CI for mean(a) - mean(b) with patients resampled as pairs."""\n    a = np.asarray(a, dtype=np.float64)\n    b = np.asarray(b, dtype=np.float64)\n    if a.shape != b.shape:\n        raise ValueError("Paired inputs must have the same length and ordering.")\n    keep = np.isfinite(a) & np.isfinite(b)\n    d = a[keep] - b[keep]\n    st = np.asarray(strata)[keep] if strata is not None else None\n    return bootstrap_ci(d, np.mean, n_boot, alpha, seed, st)\n\n\ndef permutation_test(\n    a: Sequence[float], b: Sequence[float], n_perm: int = 10_000, seed: int = 999,\n) -> float:\n    """Two-sided paired permutation (sign-flip) test on the mean difference."""\n    a = np.asarray(a, dtype=np.float64)\n    b = np.asarray(b, dtype=np.float64)\n    keep = np.isfinite(a) & np.isfinite(b)\n    d = a[keep] - b[keep]\n    if d.size == 0:\n        return float("nan")\n    observed = abs(d.mean())\n    rng = np.random.default_rng(seed)\n    signs = rng.choice([-1.0, 1.0], size=(n_perm, d.size))\n    null = np.abs((signs * d).mean(axis=1))\n    # +1 in numerator and denominator: the observed assignment is one of the\n    # permutations, which keeps the test valid rather than reporting p = 0.\n    return float((np.sum(null >= observed) + 1) / (n_perm + 1))\n\n\ndef wilcoxon_test(a: Sequence[float], b: Sequence[float]) -> float:\n    from scipy.stats import wilcoxon\n    a = np.asarray(a, dtype=np.float64)\n    b = np.asarray(b, dtype=np.float64)\n    keep = np.isfinite(a) & np.isfinite(b)\n    d = a[keep] - b[keep]\n    if np.allclose(d, 0):\n        return 1.0\n    return float(wilcoxon(a[keep], b[keep], zero_method="wilcox").pvalue)\n\n\ndef cohens_dz(a: Sequence[float], b: Sequence[float]) -> float:\n    a = np.asarray(a, dtype=np.float64)\n    b = np.asarray(b, dtype=np.float64)\n    keep = np.isfinite(a) & np.isfinite(b)\n    d = a[keep] - b[keep]\n    sd = d.std(ddof=1)\n    return float(d.mean() / sd) if sd > 0 else float("nan")\n\n\ndef compare_paired(\n    a: Sequence[float], b: Sequence[float], name: str = "",\n    test: str = "permutation", n_boot: int = 10_000, alpha: float = 0.05,\n    seed: int = 12345, strata: Optional[Sequence] = None,\n) -> PairedResult:\n    """The standard comparison used everywhere in Notebook 03."""\n    a_arr, b_arr = np.asarray(a, dtype=np.float64), np.asarray(b, dtype=np.float64)\n    keep = np.isfinite(a_arr) & np.isfinite(b_arr)\n    diff, lo, hi = paired_bootstrap_difference(a, b, n_boot, alpha, seed, strata)\n    p = (permutation_test(a, b, seed=seed) if test == "permutation"\n         else wilcoxon_test(a, b))\n    return PairedResult(\n        name=name, n=int(keep.sum()),\n        mean_a=float(a_arr[keep].mean()), mean_b=float(b_arr[keep].mean()),\n        mean_difference=diff, ci_low=lo, ci_high=hi,\n        effect_size=cohens_dz(a, b), p_value=p, test=test,\n    )\n\n\n# --------------------------------------------------------------------------- #\ndef holm_correction(p_values: Sequence[float]) -> np.ndarray:\n    """Holm-Bonferroni step-down adjusted p-values, applied *within* a\n    pre-declared comparison family (core baselines / confirmed ablations /\n    robustness endpoints)."""\n    p = np.asarray(p_values, dtype=np.float64)\n    n = p.size\n    order = np.argsort(p, kind="stable")\n    adjusted = np.empty(n, dtype=np.float64)\n    running = 0.0\n    for rank, idx in enumerate(order):\n        value = (n - rank) * p[idx]\n        running = max(running, value)\n        adjusted[idx] = min(running, 1.0)\n    return adjusted\n\n\ndef apply_holm(results: List[PairedResult]) -> List[PairedResult]:\n    adj = holm_correction([r.p_value for r in results])\n    for r, a in zip(results, adj):\n        r.p_holm = float(a)\n    return results\n\n\n# --------------------------------------------------------------------------- #\ndef non_inferiority(\n    proposed: Sequence[float], reference: Sequence[float],\n    margin: float, n_boot: int = 10_000, alpha: float = 0.05,\n    seed: int = 4242, strata: Optional[Sequence] = None,\n) -> Dict[str, float]:\n    """One-sided non-inferiority on the paired mean difference (H1).\n\n    `margin` is expressed in the same units as the scores and must be fixed\n    before any locked-test result is viewed (plan 4.1: -1.5 percentage points\n    on macro Dice, i.e. margin=0.015 for Dice in [0, 1]).\n\n    Non-inferiority is concluded when the lower bound of the two-sided CI for\n    (proposed - reference) lies above -margin.\n    """\n    diff, lo, hi = paired_bootstrap_difference(\n        proposed, reference, n_boot, alpha, seed, strata\n    )\n    return {\n        "mean_difference": diff,\n        "ci_low": lo,\n        "ci_high": hi,\n        "margin": float(margin),\n        "non_inferior": bool(np.isfinite(lo) and lo > -abs(margin)),\n        "superior": bool(np.isfinite(lo) and lo > 0.0),\n        "alpha": alpha,\n    }\n\n\n# --------------------------------------------------------------------------- #\ndef summarize_subset_performance(\n    per_case_subset: Dict[str, Dict[str, float]],\n    n_boot: int = 10_000, alpha: float = 0.05, seed: int = 7,\n):\n    """Mean / worst-subset summary with CIs (endpoints 2 and 3 of plan 4.2).\n\n    per_case_subset: case_id -> {subset_key: macro Dice}\n    """\n    import pandas as pd\n    df = pd.DataFrame(per_case_subset).T          # rows = cases, cols = subsets\n    per_case_mean = df.mean(axis=1).to_numpy()\n    per_case_worst = df.min(axis=1).to_numpy()\n    rows = []\n    for label, values in (("mean_over_subsets", per_case_mean),\n                          ("worst_subset", per_case_worst)):\n        point, lo, hi = bootstrap_ci(values, np.mean, n_boot, alpha, seed)\n        rows.append({"endpoint": label, "mean": point, "ci_low": lo, "ci_high": hi,\n                     "n": int(np.isfinite(values).sum())})\n    for col in df.columns:\n        point, lo, hi = bootstrap_ci(df[col].to_numpy(), np.mean, n_boot, alpha, seed)\n        rows.append({"endpoint": f"subset::{col}", "mean": point,\n                     "ci_low": lo, "ci_high": hi, "n": int(df[col].notna().sum())})\n    return pd.DataFrame(rows)\n\n\ndef bootstrap_difference_between_cohorts(\n    adult: Sequence[float], pediatric: Sequence[float],\n    n_boot: int = 10_000, alpha: float = 0.05, seed: int = 31337,\n) -> Dict[str, float]:\n    """Unpaired bootstrap for the adult-to-pediatric degradation (plan 10.5).\n\n    The cohorts contain different patients, so this is an unpaired comparison\n    and it is reported with the caveat that age, disease and acquisition all\n    differ - it is domain-shift evidence, not external validation.\n    """\n    a = np.asarray(adult, dtype=np.float64)\n    p = np.asarray(pediatric, dtype=np.float64)\n    a, p = a[np.isfinite(a)], p[np.isfinite(p)]\n    rng = np.random.default_rng(seed)\n    diffs = np.empty(n_boot)\n    for b in range(n_boot):\n        diffs[b] = (a[rng.integers(0, a.size, a.size)].mean()\n                    - p[rng.integers(0, p.size, p.size)].mean())\n    lo, hi = np.percentile(diffs, [100 * alpha / 2, 100 * (1 - alpha / 2)])\n    return {\n        "adult_mean": float(a.mean()), "pediatric_mean": float(p.mean()),\n        "difference": float(a.mean() - p.mean()),\n        "ci_low": float(lo), "ci_high": float(hi),\n        "n_adult": int(a.size), "n_pediatric": int(p.size),\n        "caveat": ("Unpaired comparison across cohorts differing in age, tumour "\n                   "phenotype, acquisition and label domain; out-of-domain stress "\n                   "test, not external validation."),\n    }\n', 'segmentation/src/qmmf/subsets.py': '"""The 15 non-empty modality subsets and the training curriculum over them.\n\nPlan 9.5: evaluation is exhaustive and exact, not sampled - with |M| = 4 there\nare 2^4 - 1 = 15 non-empty subsets, so no Monte Carlo approximation is needed\nanywhere in this study (including Shapley, see shapley.py).\n"""\n\nfrom __future__ import annotations\n\nfrom itertools import combinations\nfrom typing import Dict, List, Sequence, Tuple\n\nimport numpy as np\n\nfrom .config import MODALITIES\n\n\ndef all_subsets(modalities: Sequence[str] = MODALITIES) -> List[Tuple[str, ...]]:\n    """All 15 non-empty subsets, ordered by size then canonical modality order."""\n    out: List[Tuple[str, ...]] = []\n    for size in range(1, len(modalities) + 1):\n        for combo in combinations(modalities, size):\n            out.append(combo)\n    return out\n\n\ndef subset_key(subset: Sequence[str]) -> str:\n    """Stable identifier, e.g. (\'t1\',\'flair\') -> \'t1+flair\'."""\n    order = {m: i for i, m in enumerate(MODALITIES)}\n    return "+".join(sorted(subset, key=lambda m: order[m]))\n\n\ndef availability_mask(\n    subset: Sequence[str], modalities: Sequence[str] = MODALITIES\n) -> np.ndarray:\n    """Binary availability vector a in {0,1}^M with sum(a) >= 1."""\n    mask = np.array([1.0 if m in set(subset) else 0.0 for m in modalities],\n                    dtype=np.float32)\n    if mask.sum() < 1:\n        raise ValueError("The empty modality subset is not a valid input.")\n    return mask\n\n\ndef mask_to_subset(\n    mask: Sequence[float], modalities: Sequence[str] = MODALITIES\n) -> Tuple[str, ...]:\n    return tuple(m for m, a in zip(modalities, mask) if a > 0.5)\n\n\nALL_SUBSETS: List[Tuple[str, ...]] = all_subsets()\nALL_SUBSET_KEYS: List[str] = [subset_key(s) for s in ALL_SUBSETS]\nSUBSETS_BY_SIZE: Dict[int, List[Tuple[str, ...]]] = {\n    k: [s for s in ALL_SUBSETS if len(s) == k] for k in (1, 2, 3, 4)\n}\n\n\n# --------------------------------------------------------------------------- #\n# Training-time subset curriculum (plan 8.3)\n# --------------------------------------------------------------------------- #\n# Phase boundaries as fractions of the total epoch budget, with the subset-size\n# distribution used in each phase. "hard" phases additionally oversample the\n# T1ce-missing and FLAIR-missing subsets, which are the clinically hard cases.\nCURRICULUM_V1: List[Dict] = [\n    dict(until=0.15, size_probs={4: 0.50, 3: 0.40, 2: 0.10, 1: 0.00}, hard_boost=0.0),\n    dict(until=0.60, size_probs={4: 0.30, 3: 0.30, 2: 0.25, 1: 0.15}, hard_boost=0.0),\n    dict(until=0.90, size_probs={4: 0.20, 3: 0.25, 2: 0.30, 1: 0.25}, hard_boost=0.5),\n    dict(until=1.01, size_probs={4: 0.25, 3: 0.25, 2: 0.25, 1: 0.25}, hard_boost=0.0),\n]\n\n# A11 negative control: uniform over the 15 subsets from epoch 1.\nCURRICULUM_UNIFORM: List[Dict] = [\n    dict(until=1.01, size_probs=None, hard_boost=0.0),\n]\n\nCURRICULA = {"v1": CURRICULUM_V1, "uniform": CURRICULUM_UNIFORM}\n\n# Subsets missing the two most informative sequences for TC/ET and WT.\nHARD_SUBSETS = [s for s in ALL_SUBSETS if "t1ce" not in s] + \\\n               [s for s in ALL_SUBSETS if "flair" not in s]\n\n\ndef curriculum_probabilities(\n    epoch_frac: float, curriculum: str = "v1"\n) -> np.ndarray:\n    """Sampling probability over the 15 subsets at a given point in training.\n\n    epoch_frac is (epoch / max_epochs) in [0, 1].\n    """\n    if curriculum not in CURRICULA:\n        raise KeyError(f"Unknown curriculum \'{curriculum}\'. Have {list(CURRICULA)}.")\n    phases = CURRICULA[curriculum]\n    phase = next(p for p in phases if epoch_frac < p["until"])\n\n    n = len(ALL_SUBSETS)\n    if phase["size_probs"] is None:\n        return np.full(n, 1.0 / n, dtype=np.float64)\n\n    probs = np.zeros(n, dtype=np.float64)\n    for size, mass in phase["size_probs"].items():\n        members = [i for i, s in enumerate(ALL_SUBSETS) if len(s) == size]\n        if not members or mass <= 0:\n            continue\n        for i in members:\n            probs[i] += mass / len(members)\n\n    boost = phase.get("hard_boost", 0.0)\n    if boost > 0:\n        hard_idx = [i for i, s in enumerate(ALL_SUBSETS)\n                    if "t1ce" not in s or "flair" not in s]\n        probs[hard_idx] *= (1.0 + boost)\n\n    total = probs.sum()\n    if total <= 0:\n        raise ValueError("Degenerate curriculum phase produced zero mass.")\n    return probs / total\n\n\ndef sample_subset(\n    rng: np.random.Generator, epoch_frac: float, curriculum: str = "v1"\n) -> Tuple[str, ...]:\n    probs = curriculum_probabilities(epoch_frac, curriculum)\n    idx = rng.choice(len(ALL_SUBSETS), p=probs)\n    return ALL_SUBSETS[idx]\n\n\ndef sample_availability(\n    rng: np.random.Generator,\n    batch_size: int,\n    epoch_frac: float,\n    curriculum: str = "v1",\n) -> np.ndarray:\n    """Availability masks [B, M] for one batch. Never returns an all-zero row."""\n    probs = curriculum_probabilities(epoch_frac, curriculum)\n    idx = rng.choice(len(ALL_SUBSETS), size=batch_size, p=probs)\n    return np.stack([availability_mask(ALL_SUBSETS[i]) for i in idx], axis=0)\n', 'segmentation/src/qmmf/trainer.py': '"""Training loop: AMP, gradient accumulation, EMA teacher, early stopping,\ncomposite checkpoint selection, resume (plan 8.4-8.5, 11.3).\n\nOne process trains on one T4. Experiment-level parallelism across the two GPUs\nis handled by worker.py; there is no DDP on the default path, because two 16 GB\nT4s are two devices, not one 32 GB device.\n"""\n\nfrom __future__ import annotations\n\nimport json\nimport math\nimport time\nfrom dataclasses import dataclass, field\nfrom pathlib import Path\nfrom typing import Any, Callable, Dict, List, Optional, Sequence\n\nimport numpy as np\nimport torch\nimport torch.nn as nn\nfrom torch.utils.data import DataLoader\n\nfrom .config import ExperimentConfig\nfrom .dataset import SliceDataset, collate\nfrom .ema import ModelEMA\nfrom .losses import QMMFLoss\nfrom .models import build_model\nfrom .utils import seed_everything, worker_init_fn, write_json\n\n\n# --------------------------------------------------------------------------- #\n@dataclass\nclass TrainState:\n    epoch: int = 0\n    global_step: int = 0\n    best_score: float = -float("inf")\n    best_epoch: int = -1\n    epochs_without_improvement: int = 0\n    history: List[Dict[str, Any]] = field(default_factory=list)\n\n\ndef composite_selection_score(\n    full_macro_dice: float,\n    mean_subset_macro_dice: float,\n    worst_subset_macro_dice: float,\n) -> float:\n    """Checkpoint selection rule, fixed before the main runs (plan 8.5):\n\n        0.6 * full-modality macro Dice\n      + 0.3 * mean selected-subset macro Dice\n      + 0.1 * worst selected-subset macro Dice\n\n    Calibration and pediatric performance are deliberately *not* inputs.\n    """\n    parts = [full_macro_dice, mean_subset_macro_dice, worst_subset_macro_dice]\n    if any(not np.isfinite(p) for p in parts):\n        return -float("inf")\n    return 0.6 * full_macro_dice + 0.3 * mean_subset_macro_dice + 0.1 * worst_subset_macro_dice\n\n\n# --------------------------------------------------------------------------- #\nclass Trainer:\n    def __init__(\n        self,\n        cfg: ExperimentConfig,\n        train_dataset: SliceDataset,\n        validate_fn: Callable[[nn.Module, int], Dict[str, float]],\n        device: Optional[torch.device] = None,\n        region_weights: Optional[Sequence[float]] = None,\n        run_dir: Optional[Path] = None,\n        logger: Optional[Callable[[str], None]] = None,\n    ):\n        self.cfg = cfg\n        self.device = device or torch.device(\n            "cuda" if torch.cuda.is_available() else "cpu"\n        )\n        self.log = logger or (lambda msg: print(msg, flush=True))\n        self.run_dir = Path(run_dir or cfg.run_dir())\n        self.run_dir.mkdir(parents=True, exist_ok=True)\n\n        seed_everything(cfg.train.seed)\n        self.model = build_model(cfg).to(self.device)\n        self.model.quality_normalizer = train_dataset.quality_norm\n        self.criterion = QMMFLoss(cfg.loss, region_weights).to(self.device)\n        self.validate_fn = validate_fn\n\n        self.train_dataset = train_dataset\n        self.loader = DataLoader(\n            train_dataset,\n            batch_size=cfg.train.batch_size,\n            shuffle=False,               # the dataset itself samples randomly\n            num_workers=cfg.train.num_workers,\n            pin_memory=(self.device.type == "cuda"),\n            persistent_workers=False,   # epoch/curriculum must reach each worker\n            drop_last=False,             # plan 8.4: drop_last=False\n            collate_fn=collate,\n            worker_init_fn=worker_init_fn,\n        )\n\n        decay = cfg.train.weight_decay\n        self.optimizer = torch.optim.AdamW(\n            self.model.parameters(), lr=cfg.train.lr, weight_decay=decay\n        )\n        self.scaler = torch.amp.GradScaler("cuda", enabled=cfg.train.amp and self.device.type == "cuda")\n\n        steps_per_epoch = max(math.ceil(len(self.loader) / cfg.train.accumulation_steps), 1)\n        self.total_steps = steps_per_epoch * cfg.train.max_epochs\n        self.warmup_steps = max(int(self.total_steps * cfg.train.warmup_frac), 1)\n\n        self.ema: Optional[ModelEMA] = None\n        if cfg.loss.consistency > 0:\n            self.ema = ModelEMA(\n                self.model, cfg.train.ema_decay_start, cfg.train.ema_decay_end,\n                warmup_steps=self.warmup_steps, device=self.device,\n            )\n        self.state = TrainState()\n\n    # ------------------------------------------------------------------ #\n    def lr_at(self, step: int) -> float:\n        """Linear warmup then cosine decay."""\n        base = self.cfg.train.lr\n        if step < self.warmup_steps:\n            return base * (step + 1) / self.warmup_steps\n        progress = (step - self.warmup_steps) / max(self.total_steps - self.warmup_steps, 1)\n        return base * 0.5 * (1 + math.cos(math.pi * min(progress, 1.0)))\n\n    def _set_lr(self, lr: float) -> None:\n        for group in self.optimizer.param_groups:\n            group["lr"] = lr\n\n    # ------------------------------------------------------------------ #\n    def train_epoch(self, epoch: int) -> Dict[str, float]:\n        self.model.train()\n        self.train_dataset.set_epoch(epoch, self.cfg.train.max_epochs)\n        cfg = self.cfg\n        accum = cfg.train.accumulation_steps\n        consistency_active = (\n            self.ema is not None\n            and epoch >= cfg.loss.consistency_warmup_frac * cfg.train.max_epochs\n        )\n\n        totals: Dict[str, float] = {}\n        n_batches = 0\n        t0 = time.perf_counter()\n        self.optimizer.zero_grad(set_to_none=True)\n\n        for i, batch in enumerate(self.loader):\n            image = batch["image"].to(self.device, non_blocking=True)\n            target = batch["target"].to(self.device, non_blocking=True)\n            avail = batch["availability"].to(self.device, non_blocking=True)\n            quality = batch["quality"].to(self.device, non_blocking=True)\n\n            teacher_logits = None\n            if consistency_active:\n                with torch.no_grad(), torch.autocast(\n                    "cuda", enabled=cfg.train.amp and self.device.type == "cuda"\n                ):\n                    full = torch.ones_like(avail)\n                    full_image = batch["full_image"].to(self.device, non_blocking=True)\n                    teacher_logits = self.ema.module(full_image, full, quality)\n\n            with torch.autocast("cuda", enabled=cfg.train.amp and self.device.type == "cuda"):\n                logits, aux = self.model(image, avail, quality, return_aux=True)\n                parts = self.criterion(\n                    logits, target, aux.get("deep_logits"), teacher_logits,\n                    use_consistency=consistency_active,\n                )\n                # The final accumulation group may contain fewer microbatches.\n                group_start = (i // accum) * accum\n                actual_accum = min(accum, len(self.loader) - group_start)\n                loss = parts["total"] / actual_accum\n\n            if not torch.isfinite(loss):\n                raise FloatingPointError("Non-finite training loss")\n\n            self.scaler.scale(loss).backward()\n\n            if (i + 1) % accum == 0 or (i + 1) == len(self.loader):\n                self._set_lr(self.lr_at(self.state.global_step))\n                self.scaler.unscale_(self.optimizer)\n                torch.nn.utils.clip_grad_norm_(\n                    self.model.parameters(), self.cfg.train.grad_clip\n                )\n                self.scaler.step(self.optimizer)\n                self.scaler.update()\n                self.optimizer.zero_grad(set_to_none=True)\n                self.state.global_step += 1\n                if self.ema is not None:\n                    self.ema.update(self.model)\n\n            for k, v in parts.items():\n                totals[k] = totals.get(k, 0.0) + float(v.detach())\n            n_batches += 1\n\n        out = {k: v / max(n_batches, 1) for k, v in totals.items()}\n        out["epoch_seconds"] = time.perf_counter() - t0\n        out["lr"] = self.lr_at(self.state.global_step)\n        return out\n\n    # ------------------------------------------------------------------ #\n    def fit(self, resume: bool = True) -> TrainState:\n        if resume:\n            self.maybe_resume()\n        cfg = self.cfg\n        for epoch in range(self.state.epoch, cfg.train.max_epochs):\n            self.state.epoch = epoch\n            train_metrics = self.train_epoch(epoch)\n\n            record: Dict[str, Any] = {"epoch": epoch, **train_metrics}\n            if (epoch + 1) % cfg.train.val_every == 0 or epoch + 1 == cfg.train.max_epochs:\n                val = self.validate_fn(self.model, epoch)\n                record.update({f"val_{k}": v for k, v in val.items()})\n                score = composite_selection_score(\n                    val.get("full_macro_dice", float("nan")),\n                    val.get("mean_subset_macro_dice", float("nan")),\n                    val.get("worst_subset_macro_dice", float("nan")),\n                )\n                if not np.isfinite(score):\n                    raise FloatingPointError("Checkpoint selection received invalid validation metrics")\n                record["selection_score"] = score\n                improved = score > self.state.best_score\n                if improved:\n                    self.state.best_score = score\n                    self.state.best_epoch = epoch\n                    self.state.epochs_without_improvement = 0\n                    self.save_checkpoint("best.pt")\n                else:\n                    self.state.epochs_without_improvement += 1\n\n            self.state.history.append(record)\n            self.log(\n                f"epoch {epoch:3d} loss {record.get(\'total\', float(\'nan\')):.4f} "\n                f"score {record.get(\'selection_score\', float(\'nan\')):.4f} "\n                f"best {self.state.best_score:.4f} @ {self.state.best_epoch} "\n                f"({record[\'epoch_seconds\']:.1f}s)"\n            )\n            # Save every epoch so a Kaggle interruption costs at most one epoch.\n            self.save_checkpoint("last.pt")\n            self.write_history()\n\n            if self.state.epochs_without_improvement >= cfg.train.early_stopping_patience:\n                self.log(\n                    f"early stopping at epoch {epoch}: no improvement for "\n                    f"{cfg.train.early_stopping_patience} validations"\n                )\n                break\n        return self.state\n\n    # ------------------------------------------------------------------ #\n    def save_checkpoint(self, name: str) -> Path:\n        """Atomic checkpoint write: temp file then rename."""\n        path = self.run_dir / name\n        tmp = path.with_suffix(".tmp")\n        payload = {\n            "model": self.model.state_dict(),\n            "optimizer": self.optimizer.state_dict(),\n            "scaler": self.scaler.state_dict(),\n            "state": {\n                "epoch": self.state.epoch + 1,\n                "global_step": self.state.global_step,\n                "best_score": self.state.best_score,\n                "best_epoch": self.state.best_epoch,\n                "epochs_without_improvement": self.state.epochs_without_improvement,\n            },\n            "config": self.cfg.to_dict(),\n            "config_hash": self.cfg.config_hash(),\n        }\n        if self.ema is not None:\n            payload["ema"] = self.ema.state_dict()\n        if self.train_dataset.quality_norm is not None:\n            payload["quality_normalizer"] = self.train_dataset.quality_norm.to_dict()\n        torch.save(payload, tmp)\n        tmp.replace(path)\n        return path\n\n    def maybe_resume(self, name: str = "last.pt") -> bool:\n        path = self.run_dir / name\n        if not path.exists():\n            return False\n        payload = torch.load(path, map_location=self.device, weights_only=False)\n        if payload.get("config_hash") != self.cfg.config_hash():\n            raise RuntimeError(\n                f"Checkpoint {path} was written under a different configuration "\n                f"({payload.get(\'config_hash\')} vs {self.cfg.config_hash()}). "\n                "Refusing to resume into a different experiment."\n            )\n        self.model.load_state_dict(payload["model"])\n        self.optimizer.load_state_dict(payload["optimizer"])\n        self.scaler.load_state_dict(payload["scaler"])\n        if self.ema is not None and "ema" in payload:\n            self.ema.load_state_dict(payload["ema"])\n        s = payload["state"]\n        self.state.epoch = int(s["epoch"])\n        self.state.global_step = int(s["global_step"])\n        self.state.best_score = float(s["best_score"])\n        self.state.best_epoch = int(s["best_epoch"])\n        self.state.epochs_without_improvement = int(s["epochs_without_improvement"])\n        history_path = self.run_dir / "history.csv"\n        if history_path.exists():\n            import pandas as pd\n            self.state.history = pd.read_csv(history_path).to_dict("records")\n        self.log(f"resumed from {path} at epoch {self.state.epoch}")\n        return True\n\n    def write_history(self) -> None:\n        import pandas as pd\n        pd.DataFrame(self.state.history).to_csv(self.run_dir / "history.csv", index=False)\n\n\n# --------------------------------------------------------------------------- #\ndef speed_and_memory_pilot(\n    cfg: ExperimentConfig, dataset: SliceDataset, steps: int = 200,\n    device: Optional[torch.device] = None,\n) -> Dict[str, float]:\n    """The 200-step benchmark that plan 11.4 requires before committing to the\n    run matrix. Returns measured VRAM and throughput - never planning estimates.\n    """\n    from .utils import count_parameters, vram_profiler\n\n    device = device or torch.device("cuda" if torch.cuda.is_available() else "cpu")\n    model = build_model(cfg).to(device)\n    criterion = QMMFLoss(cfg.loss).to(device)\n    optimizer = torch.optim.AdamW(model.parameters(), lr=cfg.train.lr)\n    scaler = torch.amp.GradScaler("cuda", enabled=cfg.train.amp and device.type == "cuda")\n    loader = DataLoader(dataset, batch_size=cfg.train.batch_size, num_workers=0,\n                        collate_fn=collate)\n\n    model.train()\n    it = iter(loader)\n    with vram_profiler(0) as stats:\n        done = 0\n        while done < steps:\n            try:\n                batch = next(it)\n            except StopIteration:\n                it = iter(loader)\n                continue\n            image = batch["image"].to(device)\n            target = batch["target"].to(device)\n            avail = batch["availability"].to(device)\n            quality = batch["quality"].to(device)\n            with torch.autocast("cuda", enabled=cfg.train.amp and device.type == "cuda"):\n                logits, aux = model(image, avail, quality, return_aux=True)\n                loss = criterion(logits, target, aux.get("deep_logits"))["total"]\n            scaler.scale(loss).backward()\n            scaler.step(optimizer)\n            scaler.update()\n            optimizer.zero_grad(set_to_none=True)\n            done += 1\n\n    params = count_parameters(model)\n    return {\n        "steps": steps,\n        "batch_size": cfg.train.batch_size,\n        "wall_seconds": stats["wall_seconds"],\n        "steps_per_second": steps / max(stats["wall_seconds"], 1e-9),\n        "peak_vram_gb": stats["peak_vram_gb"],\n        "peak_reserved_gb": stats["peak_reserved_gb"],\n        "parameters_total": params["total"],\n        "parameters_millions": params["total"] / 1e6,\n    }\n\n\ndef check_resource_gates(pilot: Dict[str, float], vram_gate_gb: float = 14.5,\n                         param_gate_m: float = 8.0) -> Dict[str, Any]:\n    """Plan 7.7 / 11.5 gates, evaluated against *measured* pilot numbers."""\n    vram = pilot.get("peak_vram_gb", float("nan"))\n    params = pilot.get("parameters_millions", float("nan"))\n    return {\n        "vram_gate_gb": vram_gate_gb,\n        "measured_peak_vram_gb": vram,\n        "vram_pass": bool(np.isfinite(vram) and vram < vram_gate_gb),\n        "param_gate_millions": param_gate_m,\n        "measured_parameters_millions": params,\n        "param_pass": bool(np.isfinite(params) and params < param_gate_m),\n        "action_if_failed": (\n            "Reduce widths/crop or enable activation checkpointing; do not hide "\n            "parameter inflation (plan 7.7)."\n        ),\n    }\n', 'segmentation/src/qmmf/transforms.py': '"""Preprocessing, 2.5D windowing, augmentation and the fixed corruption suite.\n\nPlan 6.2-6.4 and 9.6. Pure numpy so it runs identically in DataLoader workers.\n\nTwo rules are enforced structurally rather than by convention:\n  * spatial transforms are applied identically to every modality and to labels\n    (nearest-neighbour for labels);\n  * the corruption severities used for the locked robustness test are a fixed\n    grid that is *not* drawn from the training augmentation distribution.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom typing import Dict, List, Optional, Sequence, Tuple\n\nimport numpy as np\nfrom scipy import ndimage\n\n\n# --------------------------------------------------------------------------- #\n# Preprocessing\n# --------------------------------------------------------------------------- #\ndef brain_support_mask(volume_4d: np.ndarray) -> np.ndarray:\n    """Union of nonzero voxels across modalities (plan 6.2 step 8)."""\n    return np.any(np.asarray(volume_4d) != 0, axis=0)\n\n\ndef bounding_box(mask: np.ndarray, margin: int = 8) -> Tuple[slice, ...]:\n    coords = np.array(np.nonzero(mask))\n    if coords.size == 0:\n        return tuple(slice(0, s) for s in mask.shape)\n    lo = np.maximum(coords.min(axis=1) - margin, 0)\n    hi = np.minimum(coords.max(axis=1) + 1 + margin, mask.shape)\n    return tuple(slice(int(a), int(b)) for a, b in zip(lo, hi))\n\n\ndef robust_zscore(\n    volume: np.ndarray, mask: np.ndarray, clip_sigma: float = 5.0\n) -> np.ndarray:\n    """Per-case, per-modality z-score over nonzero brain, clipped (plan 6.2 step 9).\n\n    Voxels outside the brain support stay at zero so that an absent sequence and\n    the background remain distinguishable from normalised tissue.\n    """\n    vol = np.asarray(volume, dtype=np.float32)\n    fg = vol[mask]\n    fg = fg[fg != 0]\n    if fg.size < 10:\n        return np.zeros_like(vol)\n    mean, std = float(fg.mean()), float(fg.std())\n    if std < 1e-6:\n        return np.zeros_like(vol)\n    out = np.zeros_like(vol)\n    out[mask] = np.clip((vol[mask] - mean) / std, -clip_sigma, clip_sigma)\n    return out\n\n\ndef preprocess_case(\n    image_4d: np.ndarray,\n    label_3d: Optional[np.ndarray] = None,\n    clip_sigma: float = 5.0,\n    crop_margin: int = 8,\n) -> Dict[str, object]:\n    """Crop to brain, normalise each modality, and record the crop for\n    deterministic reconstruction back into the original volume geometry."""\n    image = np.asarray(image_4d, dtype=np.float32)          # [M, H, W, D]\n    support = brain_support_mask(image)\n    box = bounding_box(support, margin=crop_margin)\n    cropped = image[(slice(None),) + box]\n    support_c = support[box]\n    normed = np.stack(\n        [robust_zscore(cropped[m], support_c, clip_sigma) for m in range(cropped.shape[0])],\n        axis=0,\n    )\n    out: Dict[str, object] = {\n        "image": normed,\n        "brain_mask": support_c,\n        "crop_box": [[int(s.start), int(s.stop)] for s in box],\n        "original_shape": tuple(int(s) for s in image.shape[1:]),\n    }\n    if label_3d is not None:\n        out["label"] = np.asarray(label_3d)[box]\n    return out\n\n\ndef uncrop_to_original(\n    array: np.ndarray, crop_box: Sequence[Sequence[int]], original_shape: Sequence[int],\n    fill: float = 0.0,\n) -> np.ndarray:\n    """Inverse of the brain crop; used to place predictions back in volume space."""\n    arr = np.asarray(array)\n    lead = arr.shape[: arr.ndim - 3]\n    full = np.full(tuple(lead) + tuple(original_shape), fill, dtype=arr.dtype)\n    sl = (Ellipsis,) + tuple(slice(a, b) for a, b in crop_box)\n    full[sl] = arr\n    return full\n\n\n# --------------------------------------------------------------------------- #\n# 2.5D windows\n# --------------------------------------------------------------------------- #\ndef extract_window(\n    image: np.ndarray, z: int, context: int = 5, axis: int = -1\n) -> np.ndarray:\n    """Five adjacent axial slices centred on z, edge-padded at the boundaries.\n\n    image: [M, H, W, D]; returns [M, context, H, W].\n    """\n    if context % 2 != 1:\n        raise ValueError("context_slices must be odd so the window has a centre slice.")\n    half = context // 2\n    depth = image.shape[axis]\n    idx = np.clip(np.arange(z - half, z + half + 1), 0, depth - 1)\n    win = np.take(image, idx, axis=axis)                # [M, H, W, context]\n    return np.moveaxis(win, -1, 1)                      # [M, context, H, W]\n\n\ndef center_pad_or_crop(\n    array: np.ndarray, size: Tuple[int, int], value: float = 0.0\n) -> Tuple[np.ndarray, Tuple[int, int, int, int]]:\n    """Centre pad/crop the last two dims to `size`. Returns the applied offsets\n    so the operation can be inverted exactly at reconstruction time."""\n    arr = np.asarray(array)\n    h, w = arr.shape[-2], arr.shape[-1]\n    th, tw = size\n    # Crop\n    top = max((h - th) // 2, 0)\n    left = max((w - tw) // 2, 0)\n    arr = arr[..., top:top + min(th, h), left:left + min(tw, w)]\n    # Pad\n    ch, cw = arr.shape[-2], arr.shape[-1]\n    pt, pl = (th - ch) // 2, (tw - cw) // 2\n    pad = [(0, 0)] * (arr.ndim - 2) + [(pt, th - ch - pt), (pl, tw - cw - pl)]\n    arr = np.pad(arr, pad, mode="constant", constant_values=value)\n    return arr, (top, left, pt, pl)\n\n\ndef invert_center_pad_or_crop(\n    array: np.ndarray, offsets: Tuple[int, int, int, int],\n    original_hw: Tuple[int, int], value: float = 0.0,\n) -> np.ndarray:\n    """Exact inverse of center_pad_or_crop for prediction reconstruction."""\n    top, left, pt, pl = offsets\n    h, w = original_hw\n    arr = np.asarray(array)\n    th, tw = arr.shape[-2], arr.shape[-1]\n    # Undo the pad, then place the remaining content back on the original canvas.\n    ch = min(th - pt, h - top)\n    cw = min(tw - pl, w - left)\n    inner = arr[..., pt:pt + ch, pl:pl + cw]\n    out = np.full(arr.shape[:-2] + (h, w), value, dtype=arr.dtype)\n    out[..., top:top + ch, left:left + cw] = inner\n    return out\n\n\ndef window_indices(depth: int, stride: int = 1) -> List[int]:\n    return list(range(0, depth, stride))\n\n\ndef sample_slice_index(\n    label_3d: Optional[np.ndarray],\n    brain_mask: np.ndarray,\n    rng: np.random.Generator,\n    p_tumor: float = 0.50,\n    p_boundary: float = 0.25,\n) -> int:\n    """Slice sampling policy of plan 6.3: 50% tumour, 25% boundary, 25% brain."""\n    depth = brain_mask.shape[-1]\n    brain_slices = np.nonzero(brain_mask.any(axis=(0, 1)))[0]\n    tumour_slices = (np.nonzero((np.asarray(label_3d) > 0).any(axis=(0, 1)))[0]\n                     if label_3d is not None else np.array([], dtype=int))\n    return sample_slice_from_indices(depth, brain_slices, tumour_slices, rng, p_tumor, p_boundary)\n\n\ndef sample_slice_from_indices(depth, brain_slices, tumour_slices, rng,\n                              p_tumor=0.50, p_boundary=0.25):\n    """Same RNG sequence as volume-based sampling, using lossless cached indices."""\n    if brain_slices.size == 0:\n        return int(rng.integers(depth))\n\n    u = rng.random()\n    if u < p_tumor and tumour_slices.size:\n        return int(rng.choice(tumour_slices))\n    if u < p_tumor + p_boundary and tumour_slices.size:\n        # Slices at the axial extent of the tumour, where the surface is.\n        lo, hi = int(tumour_slices.min()), int(tumour_slices.max())\n        band = np.unique(np.clip([lo - 1, lo, lo + 1, hi - 1, hi, hi + 1],\n                                 0, depth - 1))\n        return int(rng.choice(band))\n    return int(rng.choice(brain_slices))\n\n\n# --------------------------------------------------------------------------- #\n# Augmentation\n# --------------------------------------------------------------------------- #\n@dataclass\nclass AugmentConfig:\n    flip_lr: bool = True\n    rotation_deg: float = 10.0\n    scale: float = 0.1\n    elastic: bool = False\n    intensity: bool = True\n    p_geometric: float = 0.5\n    p_intensity: float = 0.5\n\n\ndef augment_window(\n    image: np.ndarray,          # [M, C, H, W]\n    target: np.ndarray,         # [3, H, W]\n    rng: np.random.Generator,\n    cfg: AugmentConfig,\n) -> Tuple[np.ndarray, np.ndarray]:\n    """Shared spatial transforms for all modalities and labels; independent\n    intensity transforms per modality (plan 6.4)."""\n    img = np.asarray(image, dtype=np.float32).copy()\n    tgt = np.asarray(target).copy()\n\n    if cfg.flip_lr and rng.random() < 0.5:\n        img = img[..., ::-1].copy()\n        tgt = tgt[..., ::-1].copy()\n\n    if rng.random() < cfg.p_geometric and (cfg.rotation_deg > 0 or cfg.scale > 0):\n        angle = float(rng.uniform(-cfg.rotation_deg, cfg.rotation_deg))\n        zoom = 1.0 + float(rng.uniform(-cfg.scale, cfg.scale))\n        img = _affine_2d(img, angle, zoom, order=1)\n        tgt = _affine_2d(tgt.astype(np.float32), angle, zoom, order=0).astype(tgt.dtype)\n\n    if cfg.intensity:\n        for m in range(img.shape[0]):\n            if rng.random() >= cfg.p_intensity:\n                continue\n            img[m] = _intensity_jitter(img[m], rng)\n\n    return img, tgt\n\n\ndef _affine_2d(array: np.ndarray, angle: float, zoom: float, order: int) -> np.ndarray:\n    """Rotate + scale about the image centre, applied to the last two axes."""\n    arr = np.asarray(array, dtype=np.float32)\n    lead_shape = arr.shape[:-2]\n    h, w = arr.shape[-2], arr.shape[-1]\n    flat = arr.reshape(-1, h, w)\n    theta = np.deg2rad(angle)\n    cos, sin = np.cos(theta) / zoom, np.sin(theta) / zoom\n    matrix = np.array([[cos, -sin], [sin, cos]], dtype=np.float32)\n    centre = np.array([h / 2.0, w / 2.0], dtype=np.float32)\n    offset = centre - matrix @ centre\n    out = np.stack([\n        ndimage.affine_transform(f, matrix, offset=offset, order=order,\n                                 mode="constant", cval=0.0)\n        for f in flat\n    ], axis=0)\n    return out.reshape(lead_shape + (h, w))\n\n\ndef _intensity_jitter(vol: np.ndarray, rng: np.random.Generator) -> np.ndarray:\n    out = np.asarray(vol, dtype=np.float32)\n    kind = rng.integers(0, 4)\n    if kind == 0:                                   # gamma on the positive range\n        shift = out.min()\n        pos = out - shift\n        scale = pos.max() + 1e-6\n        gamma = float(rng.uniform(0.7, 1.4))\n        out = (pos / scale) ** gamma * scale + shift\n    elif kind == 1:                                 # additive Gaussian noise\n        out = out + rng.normal(0.0, float(rng.uniform(0.01, 0.10)), out.shape).astype(np.float32)\n    elif kind == 2:                                 # contrast / brightness\n        out = out * float(rng.uniform(0.9, 1.1)) + float(rng.uniform(-0.1, 0.1))\n    else:                                           # mild blur\n        out = ndimage.gaussian_filter(out, sigma=(0, *(float(rng.uniform(0.3, 1.0)),) * 2))\n    return out.astype(np.float32)\n\n\n# --------------------------------------------------------------------------- #\n# Fixed corruption suite (plan 9.6) - locked, not sampled from augmentation\n# --------------------------------------------------------------------------- #\nCORRUPTIONS: Tuple[str, ...] = (\n    "noise", "bias_field", "gamma", "motion", "ghosting", "blur",\n)\nSEVERITIES: Tuple[int, ...] = (1, 2, 3)\n\n_SEVERITY_TABLE: Dict[str, Dict[int, float]] = {\n    "noise":      {1: 0.05, 2: 0.10, 3: 0.20},   # sigma in normalised units\n    "bias_field": {1: 0.15, 2: 0.30, 3: 0.50},   # multiplicative field amplitude\n    "gamma":      {1: 1.3, 2: 1.6, 3: 2.0},      # gamma exponent\n    "motion":     {1: 1.0, 2: 2.0, 3: 4.0},      # ghost displacement in voxels\n    "ghosting":   {1: 0.10, 2: 0.20, 3: 0.35},   # ghost amplitude\n    "blur":       {1: 0.8, 2: 1.5, 3: 2.5},      # gaussian sigma in voxels\n}\n\n\ndef apply_corruption(\n    volume: np.ndarray, kind: str, severity: int, seed: int\n) -> np.ndarray:\n    """Apply one fixed corruption to a single modality. Deterministic in `seed`."""\n    if kind not in _SEVERITY_TABLE:\n        raise KeyError(f"Unknown corruption \'{kind}\'. Have {CORRUPTIONS}.")\n    if severity not in SEVERITIES:\n        raise KeyError(f"Severity must be one of {SEVERITIES}.")\n    rng = np.random.default_rng(seed)\n    vol = np.asarray(volume, dtype=np.float32).copy()\n    level = _SEVERITY_TABLE[kind][severity]\n\n    if kind == "noise":\n        # Rician-like magnitude noise on the two quadrature components.\n        real = vol + rng.normal(0, level, vol.shape).astype(np.float32)\n        imag = rng.normal(0, level, vol.shape).astype(np.float32)\n        vol = np.sqrt(real ** 2 + imag ** 2) * np.sign(np.where(vol == 0, 1.0, 1.0))\n    elif kind == "bias_field":\n        grids = np.meshgrid(*[np.linspace(-1, 1, s) for s in vol.shape], indexing="ij")\n        coeffs = rng.normal(0, 1, len(grids) + 1)\n        field = coeffs[0] + sum(c * g for c, g in zip(coeffs[1:], grids))\n        field = 1.0 + level * (field / (np.abs(field).max() + 1e-6))\n        vol = vol * field.astype(np.float32)\n    elif kind == "gamma":\n        shift = vol.min()\n        pos = vol - shift\n        scale = pos.max() + 1e-6\n        vol = (pos / scale) ** level * scale + shift\n    elif kind == "motion":\n        shift = int(round(level))\n        ghost = np.roll(vol, shift, axis=0)\n        vol = 0.75 * vol + 0.25 * ghost\n    elif kind == "ghosting":\n        ghost = np.roll(vol, vol.shape[1] // 3, axis=1)\n        vol = (1 - level) * vol + level * ghost\n    elif kind == "blur":\n        vol = ndimage.gaussian_filter(vol, sigma=level)\n    return vol.astype(np.float32)\n\n\ndef corruption_grid() -> List[Dict[str, object]]:\n    """The complete locked corruption grid: 6 kinds x 3 severities."""\n    return [{"kind": k, "severity": s} for k in CORRUPTIONS for s in SEVERITIES]\n', 'segmentation/src/qmmf/utils.py': '"""Seeding, hashing, environment capture and resource profiling."""\n\nfrom __future__ import annotations\n\nimport hashlib\nimport json\nimport os\nimport platform\nimport random\nimport subprocess\nimport sys\nimport time\nfrom contextlib import contextmanager\nfrom pathlib import Path\nfrom typing import Any, Dict, Iterable, Optional\n\nimport numpy as np\n\n\n# --------------------------------------------------------------------------- #\n# Determinism\n# --------------------------------------------------------------------------- #\ndef seed_everything(seed: int, deterministic: bool = True) -> None:\n    """Seed python/numpy/torch. Deterministic mode is logged, not silently on."""\n    os.environ["PYTHONHASHSEED"] = str(seed)\n    random.seed(seed)\n    np.random.seed(seed)\n    try:\n        import torch\n        torch.manual_seed(seed)\n        torch.cuda.manual_seed_all(seed)\n        if deterministic:\n            torch.backends.cudnn.deterministic = True\n            torch.backends.cudnn.benchmark = False\n        else:\n            torch.backends.cudnn.benchmark = True\n    except ImportError:  # torch-free contexts (Notebook 01 audit cells)\n        pass\n\n\ndef worker_init_fn(worker_id: int) -> None:\n    """Per-worker seeding so DataLoader workers do not share a stream."""\n    base = int(os.environ.get("QMMF_BASE_SEED", "42"))\n    seed = base + worker_id\n    np.random.seed(seed)\n    random.seed(seed)\n\n\n# --------------------------------------------------------------------------- #\n# Hashing\n# --------------------------------------------------------------------------- #\ndef sha256_file(path: str | Path, chunk_size: int = 1 << 20) -> str:\n    h = hashlib.sha256()\n    with open(path, "rb") as fh:\n        for chunk in iter(lambda: fh.read(chunk_size), b""):\n            h.update(chunk)\n    return h.hexdigest()\n\n\ndef sha256_array(array: np.ndarray) -> str:\n    """Hash of the decompressed voxel content (catches identical images under\n    different filenames, plan 5.5 \'exact duplicates\')."""\n    arr = np.ascontiguousarray(array)\n    h = hashlib.sha256()\n    h.update(str(arr.dtype).encode())\n    h.update(str(arr.shape).encode())\n    h.update(arr.tobytes())\n    return h.hexdigest()\n\n\ndef sha256_obj(obj: Any) -> str:\n    payload = json.dumps(obj, sort_keys=True, separators=(",", ":"), default=str)\n    return hashlib.sha256(payload.encode("utf-8")).hexdigest()\n\n\ndef affine_hash(affine: np.ndarray, decimals: int = 4) -> str:\n    return sha256_array(np.round(np.asarray(affine, dtype=np.float64), decimals))\n\n\n# --------------------------------------------------------------------------- #\n# Environment capture\n# --------------------------------------------------------------------------- #\ndef environment_fingerprint() -> Dict[str, Any]:\n    info: Dict[str, Any] = {\n        "python": sys.version.split()[0],\n        "platform": platform.platform(),\n        "numpy": np.__version__,\n        "timestamp_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),\n    }\n    try:\n        import torch\n        info["torch"] = torch.__version__\n        info["cuda_available"] = bool(torch.cuda.is_available())\n        info["cuda_version"] = torch.version.cuda\n        info["gpus"] = [\n            torch.cuda.get_device_name(i) for i in range(torch.cuda.device_count())\n        ]\n        info["cudnn"] = torch.backends.cudnn.version()\n    except Exception as exc:  # noqa: BLE001 - environment capture must not fail a run\n        info["torch"] = f"unavailable: {exc}"\n    for mod in ("nibabel", "monai", "scipy", "pandas", "sklearn"):\n        try:\n            info[mod] = __import__(mod).__version__\n        except Exception:  # noqa: BLE001\n            info[mod] = "not installed"\n    info["git_commit"] = _git_commit()\n    return info\n\n\ndef _git_commit() -> str:\n    try:\n        out = subprocess.run(\n            ["git", "rev-parse", "HEAD"],\n            capture_output=True, text=True, timeout=5, check=False,\n        )\n        return out.stdout.strip() or "not-a-git-repo"\n    except Exception:  # noqa: BLE001\n        return "unknown"\n\n\ndef code_hash(src_root: str | Path) -> str:\n    """Hash every tracked .py file so the ledger records the exact code state."""\n    src_root = Path(src_root)\n    files = sorted(p for p in src_root.rglob("*.py") if "__pycache__" not in str(p))\n    h = hashlib.sha256()\n    for p in files:\n        h.update(str(p.relative_to(src_root)).encode())\n        h.update(sha256_file(p).encode())\n    return h.hexdigest()[:16]\n\n\n# --------------------------------------------------------------------------- #\n# Resource profiling (plan 11.3 / 11.5 gates)\n# --------------------------------------------------------------------------- #\n@contextmanager\ndef vram_profiler(device: int = 0):\n    """Yield a dict that is filled with peak VRAM in GB on exit."""\n    stats: Dict[str, float] = {}\n    try:\n        import torch\n        have_cuda = torch.cuda.is_available()\n    except ImportError:\n        have_cuda = False\n    if have_cuda:\n        import torch\n        torch.cuda.reset_peak_memory_stats(device)\n        torch.cuda.synchronize(device)\n    t0 = time.perf_counter()\n    try:\n        yield stats\n    finally:\n        stats["wall_seconds"] = time.perf_counter() - t0\n        if have_cuda:\n            import torch\n            torch.cuda.synchronize(device)\n            stats["peak_vram_gb"] = torch.cuda.max_memory_allocated(device) / 1024**3\n            stats["peak_reserved_gb"] = (\n                torch.cuda.max_memory_reserved(device) / 1024**3\n            )\n        else:\n            stats["peak_vram_gb"] = float("nan")\n            stats["peak_reserved_gb"] = float("nan")\n\n\ndef count_parameters(model) -> Dict[str, int]:\n    total = sum(p.numel() for p in model.parameters())\n    trainable = sum(p.numel() for p in model.parameters() if p.requires_grad)\n    return {"total": total, "trainable": trainable}\n\n\ndef estimate_macs(model, sample_inputs: Dict[str, Any]) -> Optional[float]:\n    """MACs via torch profiler FLOPs when available; None if it cannot be measured.\n\n    Reported as an estimate, never as a verified hardware measurement.\n    """\n    try:\n        import torch\n        from torch.utils.flop_counter import FlopCounterMode\n        model.eval()\n        counter = FlopCounterMode(display=False)\n        with counter, torch.no_grad():\n            model(**sample_inputs)\n        return counter.get_total_flops() / 2.0  # FLOPs -> MACs\n    except Exception:  # noqa: BLE001\n        return None\n\n\n# --------------------------------------------------------------------------- #\ndef write_json(path: str | Path, obj: Any) -> None:\n    path = Path(path)\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(obj, indent=2, sort_keys=True, default=str))\n\n\ndef read_json(path: str | Path) -> Any:\n    return json.loads(Path(path).read_text())\n\n\ndef chunked(items: Iterable, size: int):\n    buf = []\n    for item in items:\n        buf.append(item)\n        if len(buf) == size:\n            yield buf\n            buf = []\n    if buf:\n        yield buf\n', 'segmentation/src/qmmf/worker.py': '"""Single-GPU worker and dual-T4 launcher (plan 11.1-11.2).\n\nTwo T4s are two 16 GB devices, not one 32 GB device. The default strategy is\nexperiment-level parallelism: GPU 0 trains one (model, fold, seed) while GPU 1\ntrains another. Each worker claims from the shared queue, writes into its own\nrun directory and appends one ledger row.\n"""\n\nfrom __future__ import annotations\n\nimport json\nimport os\nimport subprocess\nimport sys\nimport time\nfrom pathlib import Path\nfrom typing import Any, Callable, Dict, List, Optional\n\nimport numpy as np\n\nfrom .config import ExperimentConfig\nfrom .ledger import ExperimentEntry, ExperimentQueue, Ledger\nfrom .utils import code_hash, environment_fingerprint, seed_everything\n\n\ndef build_experiment_queue(\n    queue_path: str | Path,\n    models: List[str],\n    folds: List[int],\n    seeds: List[int],\n    ablations: Optional[List[str]] = None,\n    label_fractions: Optional[List[float]] = None,\n    base_cfg: Optional[ExperimentConfig] = None,\n    stage: str = "development",\n) -> int:\n    """Populate the queue with the cross-product the run matrix calls for."""\n    base = base_cfg or ExperimentConfig()\n    ablations = ablations or ["A0"]\n    label_fractions = label_fractions or [1.0]\n    entries: List[ExperimentEntry] = []\n    for model in models:\n        for ablation in ablations:\n            for fold in folds:\n                for seed in seeds:\n                    for lf in label_fractions:\n                        cfg = base.merged({\n                            "model": model, "ablation": ablation, "fold": fold,\n                            "seed": seed, "label_fraction": lf, "stage": stage,\n                            "train.seed": seed,\n                        })\n                        entries.append(ExperimentEntry(\n                            run_id=cfg.run_id(), model=model, ablation=ablation,\n                            fold=fold, seed=seed, label_fraction=lf, stage=stage,\n                        ))\n    return ExperimentQueue(queue_path).add(entries)\n\n\n# --------------------------------------------------------------------------- #\ndef run_worker(\n    gpu: int,\n    queue_path: str | Path,\n    ledger_path: str | Path,\n    run_one: Callable[[ExperimentConfig, int], Dict[str, Any]],\n    base_cfg: Optional[ExperimentConfig] = None,\n    max_runs: Optional[int] = None,\n    time_budget_seconds: Optional[float] = None,\n    src_root: Optional[str | Path] = None,\n    logger: Optional[Callable[[str], None]] = None,\n) -> List[str]:\n    """Claim and execute experiments until the queue empties or a budget expires.\n\n    `run_one(cfg, gpu) -> metrics dict` does the actual training/evaluation.\n    A run that raises is recorded as failed and the worker continues, so one\n    OOM does not take down the whole session.\n    """\n    log = logger or (lambda m: print(f"[gpu{gpu}] {m}", flush=True))\n    queue = ExperimentQueue(queue_path)\n    ledger = Ledger(ledger_path)\n    base = base_cfg or ExperimentConfig()\n    ch = code_hash(src_root) if src_root else ""\n    env = environment_fingerprint()\n    started = time.time()\n    done: List[str] = []\n\n    while True:\n        if max_runs is not None and len(done) >= max_runs:\n            log(f"reached max_runs={max_runs}")\n            break\n        if time_budget_seconds is not None and time.time() - started > time_budget_seconds:\n            log("time budget exhausted; stopping cleanly so the notebook can commit")\n            break\n\n        entry = queue.claim(gpu)\n        if entry is None:\n            log("queue empty")\n            break\n        if entry["run_id"] in ledger.completed_run_ids():\n            log(f"{entry[\'run_id\']} already completed; skipping")\n            queue.release(entry["run_id"], "completed")\n            continue\n\n        cfg = base.merged({\n            "model": entry["model"], "ablation": entry["ablation"],\n            "fold": entry["fold"], "seed": entry["seed"],\n            "label_fraction": entry["label_fraction"], "stage": entry["stage"],\n            "train.seed": entry["seed"],\n        })\n        row = {\n            "run_id": entry["run_id"], "gpu": gpu, "model": cfg.model,\n            "ablation": cfg.ablation, "fold": cfg.fold, "seed": cfg.seed,\n            "label_fraction": cfg.label_fraction, "stage": cfg.stage,\n            "config_hash": cfg.config_hash(),\n            "manifest_hash": cfg.data.manifest_hash,\n            "split_hash": cfg.data.split_hash,\n            "code_hash": ch, "git_commit": env.get("git_commit", ""),\n        }\n        log(f"start {entry[\'run_id\']}")\n        t0 = time.time()\n        try:\n            seed_everything(cfg.train.seed)\n            metrics = run_one(cfg, gpu)\n            row.update(metrics)\n            row["status"] = "completed"\n            row["wall_seconds"] = time.time() - t0\n            ledger.append(row)\n            queue.release(entry["run_id"], "completed")\n            done.append(entry["run_id"])\n            log(f"done {entry[\'run_id\']} in {row[\'wall_seconds\']:.0f}s")\n        except Exception as exc:  # noqa: BLE001 - failures are evidence, not noise\n            row["wall_seconds"] = time.time() - t0\n            status = "resource_rejected" if _is_oom(exc) else "failed"\n            row["status"] = status\n            ledger.record_failure(row, exc)\n            queue.release(entry["run_id"], status)\n            log(f"FAILED {entry[\'run_id\']}: {type(exc).__name__}: {exc}")\n            _empty_cache()\n    return done\n\n\ndef _is_oom(exc: BaseException) -> bool:\n    text = f"{type(exc).__name__} {exc}".lower()\n    return "out of memory" in text or "cuda oom" in text\n\n\ndef _empty_cache() -> None:\n    try:\n        import torch\n        torch.cuda.empty_cache()\n    except Exception:  # noqa: BLE001\n        pass\n\n\n# --------------------------------------------------------------------------- #\ndef launch_dual_gpu(\n    worker_script: str | Path,\n    queue_path: str | Path,\n    ledger_path: str | Path,\n    extra_args: Optional[List[str]] = None,\n    gpus: tuple = (0, 1),\n) -> List[subprocess.Popen]:\n    """Start one independent process per T4.\n\n    Independent processes, separate 16 GB VRAM spaces, one shared ledger. This\n    is not DDP: DDP would duplicate model state on both GPUs for a single run,\n    which is the wrong trade for a study that needs many short runs.\n    """\n    procs: List[subprocess.Popen] = []\n    for gpu in gpus:\n        env = dict(os.environ)\n        env["CUDA_VISIBLE_DEVICES"] = str(gpu)\n        cmd = [\n            sys.executable, str(worker_script),\n            "--gpu", "0",                     # remapped to 0 inside the process\n            "--queue", str(queue_path),\n            "--ledger", str(ledger_path),\n        ] + (extra_args or [])\n        procs.append(subprocess.Popen(cmd, env=env))\n        time.sleep(2)                          # stagger the dataset cache warmup\n    return procs\n\n\ndef wait_for(procs: List[subprocess.Popen], poll: float = 30.0) -> List[int]:\n    codes = []\n    while any(p.poll() is None for p in procs):\n        time.sleep(poll)\n    for p in procs:\n        codes.append(p.returncode)\n    return codes\n'}
